    fn cursor_is_in_package_declaration_default_value(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return false;
        }
        // A `:=` inside the package body's executable region (a routine body or
        // the body's initialization `BEGIN` section) is an assignment statement,
        // not a declaration-item default. The frame model distinguishes the two.
        if Self::cursor_in_plsql_executable_block(tokens, end) {
            return false;
        }

        let toks = Self::meaningful_tokens_before(tokens, end);
        let Some(package_idx) = toks.iter().position(
            |token| matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("PACKAGE")),
        ) else {
            return false;
        };
        if !toks.get(..package_idx).unwrap_or(&[]).iter().any(
            |token| matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("CREATE")),
        ) {
            return false;
        }
        let Some(opener_idx) =
            toks.iter()
                .enumerate()
                .skip(package_idx + 1)
                .find_map(|(idx, token)| {
                    matches!(
                        token,
                        SqlToken::Word(word)
                            if word.eq_ignore_ascii_case("AS") || word.eq_ignore_ascii_case("IS")
                    )
                    .then_some(idx)
                })
        else {
            return false;
        };

        let mut marker_seen = false;
        for token in toks.iter().skip(opener_idx + 1) {
            if matches!(token, SqlToken::Symbol(sym) if sym == ";") {
                marker_seen = false;
                continue;
            }
            if matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("DEFAULT"))
                || matches!(token, SqlToken::Symbol(sym) if sym == ":=")
            {
                marker_seen = true;
            }
        }
        marker_seen
    }

    /// True when the cursor sits in the default-value expression of a PL/SQL
    /// *declaration item* — `DECLARE v NUMBER DEFAULT |` / `:= 1 + |`, or the
    /// same inside a routine's `IS`/`AS` declaration section. The block-declared
    /// counterpart of [`Self::cursor_is_in_package_declaration_default_value`]
    /// (which requires a `CREATE … PACKAGE` header): the marker must appear in
    /// the *current* item (no `;`, region opener, or item keyword in between).
    fn cursor_is_in_plsql_declaration_default_value(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type)
            || !Self::cursor_is_in_plsql_declaration_region(tokens, end)
        {
            return false;
        }
        for token in Self::meaningful_tokens_before(tokens, end).iter().rev() {
            match token {
                SqlToken::Symbol(sym) if sym == ";" => return false,
                SqlToken::Symbol(sym) if sym == ":=" => return true,
                SqlToken::Word(word) => match word.to_ascii_uppercase().as_str() {
                    "DEFAULT" => return true,
                    "DECLARE" | "IS" | "AS" | "BEGIN" | "CURSOR" | "TYPE" | "SUBTYPE"
                    | "PRAGMA" => return false,
                    _ => {}
                },
                _ => {}
            }
        }
        false
    }

    fn cursor_is_at_package_declaration_default_value_operand_start(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if !Self::cursor_is_in_package_declaration_default_value(tokens, end, db_type) {
            return false;
        }
        matches!(
            Self::meaningful_tokens_before(tokens, end).last(),
            Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("DEFAULT")
        ) || matches!(
            Self::meaningful_tokens_before(tokens, end).last(),
            Some(SqlToken::Symbol(sym)) if sym == ":="
        )
    }

