    /// True when the cursor is at a PL/SQL type slot: a routine parameter type
    /// (`PROCEDURE p(x |)`, `(x IN |)`), a function `RETURN |` type, a collection
    /// element type (`TABLE OF |`), or a variable declaration type in a
    /// declaration region (`DECLARE v |`, `…; w |`).
    fn cursor_is_at_plsql_type(tokens: &[SqlToken], end: usize) -> bool {
        let toks = Self::meaningful_tokens_before(tokens, end);
        if toks.len() < 2 {
            return false;
        }
        let last = toks.len() - 1;
        let is_word = |idx: usize, kw: &str| matches!(toks.get(idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case(kw));
        let is_symbol = |idx: usize, sym: &str| matches!(toks.get(idx), Some(SqlToken::Symbol(value)) if value == sym);
        let is_plain_identifier = |idx: usize| matches!(toks.get(idx), Some(SqlToken::Word(word)) if !Self::is_plsql_non_type_keyword(word));

        // Function/cursor `RETURN |` signature type — a `RETURN <expr>` statement
        // lives inside the body, so it is excluded by the routine-header check
        // (`REF CURSOR RETURN |` in a type declaration is matched separately).
        if is_word(last, "RETURN")
            && Self::expected_create_type_constructor_return_keyword_candidates(tokens, end, None)
                .is_none()
            && (is_word(last - 1, "CURSOR") || Self::cursor_is_in_routine_header(tokens, end))
        {
            return true;
        }
        // Collection element type — `TABLE OF |`, `VARRAY(n) OF |`. Anchored on
        // `TABLE` or a declaration region so SQL's `FOR UPDATE OF <col>` (a column
        // position) never offers types.
        if is_word(last, "OF")
            && (is_word(last - 1, "TABLE")
                || Self::cursor_is_in_plsql_declaration_region(tokens, end)
                || Self::cursor_follows_varray_collection_of(tokens, end))
        {
            return true;
        }

        // Routine parameter type, when the cursor is inside a routine's parameter
        // parentheses.
        if Self::cursor_is_inside_routine_param_list(tokens, end) {
            // After a parameter mode (`IN`, `OUT`, `IN OUT`, `NOCOPY`).
            if is_word(last, "IN") || is_word(last, "OUT") || is_word(last, "NOCOPY") {
                return true;
            }
            // Right after the parameter name that begins a parameter.
            if is_plain_identifier(last) && (is_symbol(last - 1, "(") || is_symbol(last - 1, ",")) {
                return true;
            }
        }

        // RECORD field type — `TYPE r IS RECORD (field |)`.
        if Self::cursor_is_at_plsql_record_field_type(tokens, end) {
            return true;
        }

        // SUBTYPE base type — `SUBTYPE st IS |`. The base type follows the
        // declaration's `IS`, so anchor on `SUBTYPE <name> IS` directly before the
        // cursor inside a declaration region.
        if is_word(last, "IS")
            && last >= 2
            && is_word(last - 2, "SUBTYPE")
            && Self::cursor_is_in_plsql_declaration_region(tokens, end)
        {
            return true;
        }

        // Variable declaration type inside a declaration region — the var name is
        // a plain identifier that starts a declaration (`DECLARE`, after `;`, or
        // after a routine `IS`/`AS`), or `name CONSTANT |`.
        if Self::cursor_is_in_plsql_declaration_region(tokens, end) {
            if is_word(last, "CONSTANT") {
                return true;
            }
            if is_plain_identifier(last)
                && (is_symbol(last - 1, ";")
                    || is_word(last - 1, "DECLARE")
                    || is_word(last - 1, "IS")
                    || is_word(last - 1, "AS"))
                // A `TYPE t IS |`/`SUBTYPE t IS |` spec-kind slot is not a
                // variable declaration: `TYPE t IS TABLE |` must await `OF`,
                // not read `TABLE` as a fresh variable name after the `IS`.
                && !(last >= 3
                    && (is_word(last - 1, "IS") || is_word(last - 1, "AS"))
                    && (is_word(last - 3, "TYPE") || is_word(last - 3, "SUBTYPE")))
            {
                return true;
            }
        }

        false
    }

    fn cursor_is_at_plsql_record_field_type(tokens: &[SqlToken], end: usize) -> bool {
        let toks = Self::meaningful_tokens_before(tokens, end);
        let Some(last) = toks.len().checked_sub(1) else {
            return false;
        };
        if last == 0 {
            return false;
        }
        let is_plain_identifier = |idx: usize| matches!(toks.get(idx), Some(SqlToken::Word(word)) if !Self::is_plsql_non_type_keyword(word));
        let is_symbol = |idx: usize, sym: &str| matches!(toks.get(idx), Some(SqlToken::Symbol(value)) if value == sym);

        Self::cursor_is_inside_plsql_record_field_list(tokens, end)
            && is_plain_identifier(last)
            && (is_symbol(last - 1, "(") || is_symbol(last - 1, ","))
    }

    fn cursor_is_inside_plsql_record_field_list(tokens: &[SqlToken], end: usize) -> bool {
        Self::innermost_open_paren_preceding_word(tokens, end)
            .is_some_and(|word| word.eq_ignore_ascii_case("RECORD"))
            && Self::cursor_is_in_plsql_declaration_region(tokens, end)
    }

    fn cursor_follows_varray_collection_of(tokens: &[SqlToken], end: usize) -> bool {
        let Some(of_idx) = Self::previous_non_comment_token_index(tokens, end) else {
            return false;
        };
        if !matches!(tokens.get(of_idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("OF"))
        {
            return false;
        }

        let Some(close_idx) = Self::previous_non_comment_token_index(tokens, of_idx) else {
            return false;
        };
        if !matches!(tokens.get(close_idx), Some(SqlToken::Symbol(sym)) if sym == ")") {
            return false;
        }

        let Some(open_idx) = Self::matching_open_paren_index_before_close(tokens, close_idx) else {
            return false;
        };
        let Some(varray_idx) = Self::previous_non_comment_token_index(tokens, open_idx) else {
            return false;
        };
        if !matches!(tokens.get(varray_idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("VARRAY"))
        {
            return false;
        }

        if Self::cursor_is_in_plsql_declaration_region(tokens, end) {
            return true;
        }

        let words = Self::previous_meaningful_words_upper(tokens, varray_idx, 8);
        words.iter().any(|word| word == "CREATE")
            && words.iter().any(|word| word == "TYPE")
            && !words.iter().any(|word| word == "BODY")
    }

    /// Keywords that occupy an identifier slot in PL/SQL declarations but are not
    /// a variable name, so a following cursor is not a declaration-type position.
    fn is_plsql_non_type_keyword(word: &str) -> bool {
        matches!(
            word.to_ascii_uppercase().as_str(),
            "CONSTANT"
                | "TYPE"
                | "SUBTYPE"
                | "CURSOR"
                | "REF"
                | "PRAGMA"
                | "FUNCTION"
                | "PROCEDURE"
                | "BEGIN"
                | "END"
                | "DECLARE"
                | "IS"
                | "AS"
                | "EXCEPTION"
                | "RETURN"
                | "IN"
                | "INOUT"
                | "OUT"
                | "NOCOPY"
                | "NOT"
                | "NULL"
                | "DEFAULT"
                | "OF"
                // SQL statement keywords can follow a cursor/routine `IS` (e.g.
                // `CURSOR c IS SELECT ...`); they are never a declared variable
                // name, so they must not be treated as a declaration-type slot.
                | "SELECT"
                | "INSERT"
                | "UPDATE"
                | "DELETE"
                | "MERGE"
                | "WITH"
                | "VALUES"
        )
    }

    /// True when the innermost still-open paren at the cursor is a routine or
    /// cursor parameter list — opened right after `FUNCTION|PROCEDURE|CURSOR name`,
    /// including quoted or schema-qualified names.
    fn cursor_is_inside_routine_param_list(tokens: &[SqlToken], end: usize) -> bool {
        let mut param_paren_stack: Vec<bool> = Vec::new();
        for (idx, token) in tokens.get(..end).unwrap_or(tokens).iter().enumerate() {
            match token {
                SqlToken::Comment(_) => {}
                SqlToken::Symbol(sym) if sym == "(" => {
                    param_paren_stack
                        .push(Self::open_paren_introduces_routine_param_list(tokens, idx));
                }
                SqlToken::Symbol(sym) if sym == ")" => {
                    param_paren_stack.pop();
                }
                _ => {}
            }
        }
        param_paren_stack.last().copied().unwrap_or(false)
    }

    fn open_paren_introduces_routine_param_list(tokens: &[SqlToken], open_idx: usize) -> bool {
        let Some(name_idx) = Self::previous_non_comment_token_index(tokens, open_idx) else {
            return false;
        };
        if !Self::token_is_plsql_routine_name_segment(tokens.get(name_idx)) {
            return false;
        }

        let mut chain_start_idx = name_idx;
        loop {
            let Some(prev_idx) = Self::previous_non_comment_token_index(tokens, chain_start_idx)
            else {
                return false;
            };
            if !matches!(tokens.get(prev_idx), Some(SqlToken::Symbol(sym)) if sym == ".") {
                return Self::token_is_plsql_routine_keyword(tokens.get(prev_idx));
            }

            let Some(owner_idx) = Self::previous_non_comment_token_index(tokens, prev_idx) else {
                return false;
            };
            if !Self::token_is_plsql_routine_name_segment(tokens.get(owner_idx)) {
                return false;
            }
            chain_start_idx = owner_idx;
        }
    }

    fn token_is_plsql_routine_name_segment(token: Option<&SqlToken>) -> bool {
        match token {
            Some(SqlToken::Word(word)) => !Self::is_plsql_non_type_keyword(word),
            Some(SqlToken::String(value)) => crate::sql_text::is_quoted_identifier(value),
            _ => false,
        }
    }

    fn token_is_plsql_routine_keyword(token: Option<&SqlToken>) -> bool {
        matches!(
            token,
            Some(SqlToken::Word(word))
                if matches!(
                    word.to_ascii_uppercase().as_str(),
                    "FUNCTION" | "PROCEDURE" | "CURSOR"
                )
        )
    }

    fn cursor_is_at_plsql_routine_parameter_name_slot(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type)
            || !Self::cursor_is_inside_routine_param_list(tokens, end)
        {
            return false;
        }

        let visible_end = end.min(tokens.len());
        let Some(open_idx) = Self::nearest_unclosed_open_paren_before(tokens, visible_end) else {
            return false;
        };

        let mut segment_start = open_idx + 1;
        let mut depth = 0i32;
        for (idx, token) in tokens
            .iter()
            .enumerate()
            .take(visible_end)
            .skip(open_idx + 1)
        {
            match token {
                SqlToken::Symbol(sym) if sym == "(" || sym == "[" => depth += 1,
                SqlToken::Symbol(sym) if sym == ")" || sym == "]" => depth = (depth - 1).max(0),
                SqlToken::Symbol(sym) if sym == "," && depth == 0 => segment_start = idx + 1,
                _ => {}
            }
        }

        tokens
            .get(segment_start..visible_end)
            .unwrap_or(&[])
            .iter()
            .all(|token| matches!(token, SqlToken::Comment(_)))
    }

    fn cursor_is_at_plsql_declaration_object_name_slot(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type)
            || !Self::cursor_is_in_plsql_declaration_region(tokens, end)
        {
            return false;
        }

        let toks = Self::meaningful_tokens_before(tokens, end);
        let last_is_declaration_keyword = matches!(
            toks.last(),
            Some(SqlToken::Word(word))
                if matches!(
                    word.to_ascii_uppercase().as_str(),
                    "TYPE" | "SUBTYPE" | "CURSOR" | "FUNCTION" | "PROCEDURE"
                )
        );
        if !last_is_declaration_keyword {
            return false;
        }
        // `TYPE t IS REF CURSOR |` — this CURSOR is part of the REF CURSOR type
        // specifier, not a cursor declaration; the slot expects `RETURN`, not a
        // new name.
        !(matches!(
            toks.last(),
            Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("CURSOR")
        ) && matches!(
            toks.len().checked_sub(2).and_then(|idx| toks.get(idx)),
            Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("REF")
        ))
    }

    fn cursor_is_at_plsql_declaration_object_name_slot_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let context_end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        if Self::cursor_is_at_plsql_declaration_object_name_slot(tokens, context_end, db_type) {
            return true;
        }

        let statement_tokens = deep_ctx.statement_tokens.as_ref();
        let statement_end = Self::expected_suggestion_context_end(
            statement_tokens,
            deep_ctx.cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::cursor_is_at_plsql_declaration_object_name_slot(
            statement_tokens,
            statement_end,
            db_type,
        )
    }

    fn cursor_is_at_plsql_routine_parameter_name_slot_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let context_end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        if Self::cursor_is_at_plsql_routine_parameter_name_slot(tokens, context_end, db_type) {
            return true;
        }

        let statement_tokens = deep_ctx.statement_tokens.as_ref();
        let statement_end = Self::expected_suggestion_context_end(
            statement_tokens,
            deep_ctx.cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::cursor_is_at_plsql_routine_parameter_name_slot(
            statement_tokens,
            statement_end,
            db_type,
        )
    }

    /// True when the cursor is in a routine signature/header — after a
    /// `FUNCTION`/`PROCEDURE` keyword and before that routine's `IS`/`AS`/`BEGIN`.
    /// Distinguishes a function-signature `RETURN type` from a body `RETURN expr`.
    fn cursor_is_in_routine_header(tokens: &[SqlToken], end: usize) -> bool {
        let mut in_header = false;
        for token in tokens.get(..end).unwrap_or(tokens) {
            if let SqlToken::Word(word) = token {
                match word.to_ascii_uppercase().as_str() {
                    "FUNCTION" | "PROCEDURE" => in_header = true,
                    "IS" | "AS" | "BEGIN" => in_header = false,
                    _ => {}
                }
            }
        }
        in_header
    }

    /// True when the cursor sits in a PL/SQL declaration region — after `DECLARE`
    /// or a routine `IS`/`AS` header and before that block's `BEGIN`.
    fn cursor_is_in_plsql_declaration_region(tokens: &[SqlToken], end: usize) -> bool {
        // Stack entry = whether this block frame is still in its declaration phase.
        let mut block_stack: Vec<bool> = Vec::new();
        let mut pending_routine_header = false;
        for token in tokens.get(..end).unwrap_or(tokens) {
            match token {
                SqlToken::Comment(_) => {}
                SqlToken::Word(word) => {
                    let upper = word.to_ascii_uppercase();
                    match upper.as_str() {
                        "FUNCTION" | "PROCEDURE" | "PACKAGE" => pending_routine_header = true,
                        "DECLARE" => block_stack.push(true),
                        "IS" | "AS" => {
                            if pending_routine_header {
                                block_stack.push(true);
                                pending_routine_header = false;
                            }
                        }
                        "BEGIN" => {
                            match block_stack.last_mut() {
                                Some(top) if *top => *top = false,
                                _ => block_stack.push(false),
                            }
                            pending_routine_header = false;
                        }
                        "END" => {
                            block_stack.pop();
                        }
                        _ => {}
                    }
                }
                _ => {}
            }
        }
        matches!(block_stack.last(), Some(true))
    }

    /// True when the cursor is right after the `AS` of a `CAST`/`TREAT`/`XMLCAST`
    /// call — `CAST(expr AS |)`. Anchored on the enclosing function so precision
    /// args (`CAST(x AS NUMBER(|))`) and ordinary `AS` aliases never trigger it.
    fn cursor_is_after_cast_as(tokens: &[SqlToken], end: usize) -> bool {
        // Stack entry = whether this open paren follows an `…(expr AS type)`
        // function: CAST/TREAT/XMLCAST, plus XMLSERIALIZE (`XMLSERIALIZE(DOCUMENT
        // x AS |)`) and VALIDATE_CONVERSION (`VALIDATE_CONVERSION(x AS |)`), which
        // share the same `AS <type>` slot.
        let mut cast_paren_stack: Vec<bool> = Vec::new();
        let mut last_word: Option<&str> = None;
        for token in tokens.get(..end).unwrap_or(tokens) {
            match token {
                SqlToken::Comment(_) => {}
                SqlToken::Symbol(sym) if sym == "(" => {
                    let follows_cast = last_word.is_some_and(|word| {
                        word.eq_ignore_ascii_case("CAST")
                            || word.eq_ignore_ascii_case("TREAT")
                            || word.eq_ignore_ascii_case("XMLCAST")
                            || word.eq_ignore_ascii_case("XMLSERIALIZE")
                            || word.eq_ignore_ascii_case("VALIDATE_CONVERSION")
                    });
                    cast_paren_stack.push(follows_cast);
                    last_word = None;
                }
                SqlToken::Symbol(sym) if sym == ")" => {
                    cast_paren_stack.pop();
                    last_word = None;
                }
                SqlToken::Word(word) => last_word = Some(word),
                _ => last_word = None,
            }
        }
        cast_paren_stack.last().copied().unwrap_or(false)
            && last_word.is_some_and(|word| word.eq_ignore_ascii_case("AS"))
    }

    fn expected_cast_as_keyword_candidates(
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<&'static [&'static str]> {
        let open_idx = Self::nearest_unclosed_open_paren_before(tokens, end.min(tokens.len()))?;
        let cast_like = Self::innermost_open_paren_preceding_word(tokens, end).is_some_and(|word| {
            matches!(
                word.to_ascii_uppercase().as_str(),
                "CAST" | "TREAT" | "XMLCAST" | "XMLSERIALIZE" | "VALIDATE_CONVERSION"
            )
        });
        if !cast_like {
            return None;
        }

        let mut depth = 0i32;
        for token in tokens
            .get(open_idx + 1..end.min(tokens.len()))
            .unwrap_or(&[])
        {
            match token {
                SqlToken::Symbol(symbol) if symbol == "(" || symbol == "[" => depth += 1,
                SqlToken::Symbol(symbol) if symbol == ")" || symbol == "]" => {
                    depth = (depth - 1).max(0)
                }
                SqlToken::Word(word) if depth == 0 && word.eq_ignore_ascii_case("AS") => {
                    return None;
                }
                _ => {}
            }
        }

        (Self::cursor_follows_complete_operand(tokens, end) == Some(true)).then_some(&["AS"])
    }

    fn expected_table_alias_as_keyword_candidates(
        tokens: &[SqlToken],
        end: usize,
        phase: intellisense_context::SqlPhase,
    ) -> Option<&'static [&'static str]> {
        let alias_lookahead = {
            let mut tail = tokens
                .iter()
                .skip(end.min(tokens.len()))
                .filter(|token| !matches!(token, SqlToken::Comment(_)));
            matches!(tail.next(), Some(SqlToken::Word(_)))
                && matches!(tail.next(), Some(SqlToken::Word(_)))
                && tail.next().is_some_and(|token| {
                    matches!(
                        token,
                        SqlToken::Word(word)
                            if matches!(
                                word.to_ascii_uppercase().as_str(),
                                "FROM" | "GROUP" | "HAVING" | "JOIN" | "ON" | "ORDER"
                                    | "USING" | "WHERE"
                            )
                    )
                })
        };
        if !alias_lookahead
            && (!phase.is_table_context() || Self::unclosed_paren_count(tokens, end) != 0)
        {
            return None;
        }
        let toks = Self::meaningful_tokens_before(tokens, end);
        let last = toks.last()?;
        match last {
            SqlToken::Word(word) => {
                let upper = word.to_ascii_uppercase();
                if matches!(
                    upper.as_str(),
                    "AS" | "FROM" | "JOIN" | "ON" | "USING" | "WHERE" | "GROUP" | "ORDER"
                ) {
                    return None;
                }
                Some(&["AS"])
            }
            SqlToken::Symbol(symbol) if symbol == ")" => Some(&["AS"]),
            _ => None,
        }
    }

    fn expected_mysql_dml_tail_keyword_candidates(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<&'static [&'static str]> {
        if !crate::sql_text::mysql_compatibility_for_sql("", db_type)
            || Self::unclosed_paren_count(tokens, end) != 0
        {
            return None;
        }
        let start = Self::plsql_statement_slot_start(tokens, end);
        let words = tokens
            .get(start..end.min(tokens.len()))
            .unwrap_or(&[])
            .iter()
            .filter_map(|token| match token {
                SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
                _ => None,
            })
            .collect::<Vec<_>>();
        if words.iter().any(|word| word == "WHERE" || word == "USING") {
            return None;
        }
        match words.as_slice() {
            [delete_kw, from_kw, _table] if delete_kw == "DELETE" && from_kw == "FROM" => {
                Some(&["WHERE"])
            }
            [delete_kw, from_kw, _table, _alias]
                if delete_kw == "DELETE" && from_kw == "FROM" =>
            {
                Some(&["WHERE"])
            }
            _ => None,
        }
    }

    fn expected_set_operator_tail_keyword_candidates(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<&'static [&'static str]> {
        if Self::unclosed_paren_count(tokens, end) != 0 {
            return None;
        }
        let words = Self::previous_meaningful_words_upper(tokens, end, 4);
        let mysql = crate::sql_text::mysql_compatibility_for_sql("", db_type);
        let follows_multiset = |operator_from_end: usize| {
            words
                .len()
                .checked_sub(operator_from_end + 1)
                .and_then(|idx| words.get(idx))
                .is_some_and(|word| word == "MULTISET")
        };
        match words.as_slice() {
            [.., last] if last == "UNION" && !follows_multiset(1) => {
                Some(&["ALL", "DISTINCT", "SELECT", "WITH"])
            }
            [.., last]
                if !mysql
                    && matches!(last.as_str(), "INTERSECT" | "EXCEPT" | "MINUS")
                    && !follows_multiset(1) =>
            {
                Some(&["ALL", "DISTINCT", "SELECT", "WITH"])
            }
            [.., prev, last]
                if matches!(prev.as_str(), "UNION" | "INTERSECT" | "EXCEPT" | "MINUS")
                    && matches!(last.as_str(), "ALL" | "DISTINCT")
                    && !follows_multiset(2) =>
            {
                Some(&["SELECT", "WITH"])
            }
            _ => None,
        }
    }

    /// The `EXTRACT(<field> FROM <source>)` argument slot at the cursor, if any.
    /// The field slot accepts only a datetime field keyword (`YEAR`, `MONTH`, …),
    /// never a column, so columns are suppressed and the dialect's field keywords
    /// are offered there. Anchored on the innermost open paren following `EXTRACT`
    /// and on `FROM` not yet appearing in that paren, so the source expression
    /// (`EXTRACT(YEAR FROM |)`, a real column position) is left untouched.
    fn extract_field_position(tokens: &[SqlToken], end: usize) -> Option<ExtractArgPosition> {
        struct Frame {
            follows_extract: bool,
            seen_from: bool,
        }
        let mut stack: Vec<Frame> = Vec::new();
        // Whether the token immediately before the cursor (within the open paren)
        // is the paren itself — i.e. no field word has been typed yet.
        let mut last_was_open_paren = false;
        let mut last_word: Option<&str> = None;
        for token in tokens.get(..end).unwrap_or(tokens) {
            match token {
                SqlToken::Comment(_) => {}
                SqlToken::Symbol(sym) if sym == "(" => {
                    let follows_extract =
                        last_word.is_some_and(|word| word.eq_ignore_ascii_case("EXTRACT"));
                    stack.push(Frame {
                        follows_extract,
                        seen_from: false,
                    });
                    last_word = None;
                    last_was_open_paren = true;
                }
                SqlToken::Symbol(sym) if sym == ")" => {
                    stack.pop();
                    last_word = None;
                    last_was_open_paren = false;
                }
                SqlToken::Word(word) => {
                    if word.eq_ignore_ascii_case("FROM") {
                        if let Some(top) = stack.last_mut() {
                            top.seen_from = true;
                        }
                    }
                    last_word = Some(word);
                    last_was_open_paren = false;
                }
                _ => {
                    last_word = None;
                    last_was_open_paren = false;
                }
            }
        }
        match stack.last() {
            Some(frame) if frame.follows_extract && !frame.seen_from => {
                Some(if last_was_open_paren {
                    ExtractArgPosition::Field
                } else {
                    ExtractArgPosition::AwaitingFrom
                })
            }
            _ => None,
        }
    }

    /// Keyword slot inside a SQL-standard `TRIM`/`SUBSTRING`/`POSITION`/`OVERLAY`
    /// call, at a position *after a complete operand* where the only grammatical
    /// continuation is the function's separator keyword — never another column:
    /// - `POSITION(<substr> |` → `IN`
    /// - `TRIM([{LEADING|TRAILING|BOTH}] [removal] |` → `FROM`
    /// - `SUBSTRING(<str> |` → `FROM` (the standard form; the comma form
    ///   `SUBSTRING(str, pos, len)` takes no keyword, so a seen comma suppresses it)
    /// - `SUBSTRING(<str> FROM <pos> |` → `FOR`
    /// - `OVERLAY(<str> |` → `PLACING`
    /// - `OVERLAY(<str> PLACING <replacement> |` → `FROM`
    /// - `OVERLAY(<str> PLACING <replacement> FROM <start> |` → `FOR`
    ///
    /// Tracked with a per-call frame stack so an operand of a *nested* call does not
    /// confuse the outer one, and only the innermost frame's function counts. The
    /// `SUBSTR` (comma-only) spelling is intentionally excluded.
    fn standard_function_keyword_slot(
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<&'static [&'static str]> {
        struct Frame {
            func: Option<&'static str>,
            seen_from: bool,
            seen_for: bool,
            seen_in: bool,
            seen_placing: bool,
            seen_comma: bool,
        }
        let mut stack: Vec<Frame> = Vec::new();
        let mut last_word: Option<String> = None;
        // Whether the most recent meaningful token completed an operand (a value
        // word/string or a closed `)`), so the cursor sits just past it.
        let mut last_ended_operand = false;
        for token in tokens.get(..end).unwrap_or(tokens) {
            match token {
                SqlToken::Comment(_) => {}
                SqlToken::Symbol(sym) if sym == "(" => {
                    let func = last_word
                        .as_deref()
                        .map(str::to_ascii_uppercase)
                        .and_then(|word| match word.as_str() {
                            "TRIM" => Some("TRIM"),
                            "SUBSTRING" => Some("SUBSTRING"),
                            "POSITION" => Some("POSITION"),
                            "OVERLAY" => Some("OVERLAY"),
                            _ => None,
                        });
                    stack.push(Frame {
                        func,
                        seen_from: false,
                        seen_for: false,
                        seen_in: false,
                        seen_placing: false,
                        seen_comma: false,
                    });
                    last_word = None;
                    last_ended_operand = false;
                }
                SqlToken::Symbol(sym) if sym == ")" => {
                    stack.pop();
                    last_word = None;
                    last_ended_operand = true;
                }
                SqlToken::Symbol(sym) if sym == "," => {
                    if let Some(frame) = stack.last_mut() {
                        frame.seen_comma = true;
                    }
                    last_word = None;
                    last_ended_operand = false;
                }
                SqlToken::Symbol(_) => {
                    // An operator (`||`, `+`, …) leaves the operand incomplete.
                    last_word = None;
                    last_ended_operand = false;
                }
                SqlToken::Word(word) => {
                    let upper = word.to_ascii_uppercase();
                    match upper.as_str() {
                        "FROM" => {
                            if let Some(frame) = stack.last_mut() {
                                frame.seen_from = true;
                            }
                            last_word = None;
                            last_ended_operand = false;
                        }
                        "FOR" => {
                            if let Some(frame) = stack.last_mut() {
                                frame.seen_for = true;
                            }
                            last_word = None;
                            last_ended_operand = false;
                        }
                        "IN" => {
                            if let Some(frame) = stack.last_mut() {
                                frame.seen_in = true;
                            }
                            last_word = None;
                            last_ended_operand = false;
                        }
                        "PLACING" => {
                            if let Some(frame) = stack.last_mut() {
                                frame.seen_placing = true;
                            }
                            last_word = None;
                            last_ended_operand = false;
                        }
                        "LEADING" | "TRAILING" | "BOTH" => {
                            // A trim-spec qualifier, not an operand.
                            last_word = None;
                            last_ended_operand = false;
                        }
                        _ => {
                            last_word = Some(word.clone());
                            last_ended_operand = true;
                        }
                    }
                }
                SqlToken::String(_) => {
                    last_word = None;
                    last_ended_operand = true;
                }
            }
        }
        if !last_ended_operand {
            return None;
        }
        let frame = stack.last()?;
        match frame.func? {
            "POSITION" if !frame.seen_in => Some(&["IN"]),
            "TRIM" if !frame.seen_from => Some(&["FROM"]),
            "SUBSTRING" if frame.seen_from && !frame.seen_for && !frame.seen_comma => {
                Some(&["FOR"])
            }
            "SUBSTRING" if !frame.seen_from && !frame.seen_comma => Some(&["FROM"]),
            "OVERLAY" if frame.seen_from && !frame.seen_for && !frame.seen_comma => Some(&["FOR"]),
            "OVERLAY" if frame.seen_placing && !frame.seen_from && !frame.seen_comma => {
                Some(&["FROM"])
            }
            "OVERLAY" if !frame.seen_placing && !frame.seen_comma => Some(&["PLACING"]),
            _ => None,
        }
    }

    fn standard_function_keyword_slot_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
    ) -> Option<&'static [&'static str]> {
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::standard_function_keyword_slot(tokens, end)
    }

    fn cursor_is_after_complete_standard_function_tail(tokens: &[SqlToken], end: usize) -> bool {
        struct Frame {
            func: Option<&'static str>,
            seen_from: bool,
            seen_for: bool,
            seen_in: bool,
            seen_placing: bool,
            seen_comma: bool,
        }
        let mut stack: Vec<Frame> = Vec::new();
        let mut last_word: Option<String> = None;
        let mut last_ended_operand = false;
        for token in tokens.get(..end).unwrap_or(tokens) {
            match token {
                SqlToken::Comment(_) => {}
                SqlToken::Symbol(sym) if sym == "(" => {
                    let func = last_word
                        .as_deref()
                        .map(str::to_ascii_uppercase)
                        .and_then(|word| match word.as_str() {
                            "TRIM" => Some("TRIM"),
                            "SUBSTRING" => Some("SUBSTRING"),
                            "POSITION" => Some("POSITION"),
                            "OVERLAY" => Some("OVERLAY"),
                            _ => None,
                        });
                    stack.push(Frame {
                        func,
                        seen_from: false,
                        seen_for: false,
                        seen_in: false,
                        seen_placing: false,
                        seen_comma: false,
                    });
                    last_word = None;
                    last_ended_operand = false;
                }
                SqlToken::Symbol(sym) if sym == ")" => {
                    stack.pop();
                    last_word = None;
                    last_ended_operand = true;
                }
                SqlToken::Symbol(sym) if sym == "," => {
                    if let Some(frame) = stack.last_mut() {
                        frame.seen_comma = true;
                    }
                    last_word = None;
                    last_ended_operand = false;
                }
                SqlToken::Symbol(_) => {
                    last_word = None;
                    last_ended_operand = false;
                }
                SqlToken::Word(word) => {
                    let upper = word.to_ascii_uppercase();
                    match upper.as_str() {
                        "FROM" => {
                            if let Some(frame) = stack.last_mut() {
                                frame.seen_from = true;
                            }
                            last_word = None;
                            last_ended_operand = false;
                        }
                        "FOR" => {
                            if let Some(frame) = stack.last_mut() {
                                frame.seen_for = true;
                            }
                            last_word = None;
                            last_ended_operand = false;
                        }
                        "IN" => {
                            if let Some(frame) = stack.last_mut() {
                                frame.seen_in = true;
                            }
                            last_word = None;
                            last_ended_operand = false;
                        }
                        "PLACING" => {
                            if let Some(frame) = stack.last_mut() {
                                frame.seen_placing = true;
                            }
                            last_word = None;
                            last_ended_operand = false;
                        }
                        "LEADING" | "TRAILING" | "BOTH" => {
                            last_word = None;
                            last_ended_operand = false;
                        }
                        _ => {
                            last_word = Some(word.clone());
                            last_ended_operand = true;
                        }
                    }
                }
                SqlToken::String(_) => {
                    last_word = None;
                    last_ended_operand = true;
                }
            }
        }
        if !last_ended_operand {
            return false;
        }
        let Some(frame) = stack.last() else {
            return false;
        };
        match frame.func {
            Some("POSITION") => frame.seen_in,
            Some("TRIM") => frame.seen_from,
            Some("SUBSTRING") => frame.seen_from && frame.seen_for && !frame.seen_comma,
            Some("OVERLAY") => {
                frame.seen_placing && frame.seen_from && frame.seen_for && !frame.seen_comma
            }
            _ => false,
        }
    }

    fn cursor_is_after_complete_standard_function_tail_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
    ) -> bool {
        if !exclude_current_identifier_chain {
            return false;
        }
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::cursor_is_after_complete_standard_function_tail(tokens, end)
    }

    fn extract_field_position_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
    ) -> Option<ExtractArgPosition> {
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::extract_field_position(tokens, end).or_else(|| {
            let statement_tokens = deep_ctx.statement_tokens.as_ref();
            let statement_end = Self::expected_suggestion_context_end(
                statement_tokens,
                deep_ctx.cursor_token_len,
                exclude_current_identifier_chain,
            );
            Self::extract_field_position(statement_tokens, statement_end)
        })
    }

    fn is_completed_interval_unit_word(word: &str) -> bool {
        matches!(
            word.to_ascii_uppercase().as_str(),
            "YEAR"
                | "MONTH"
                | "DAY"
                | "HOUR"
                | "MINUTE"
                | "SECOND"
                | "MICROSECOND"
                | "WEEK"
                | "QUARTER"
                | "SECOND_MICROSECOND"
                | "MINUTE_MICROSECOND"
                | "MINUTE_SECOND"
                | "HOUR_MICROSECOND"
                | "HOUR_SECOND"
                | "HOUR_MINUTE"
                | "DAY_MICROSECOND"
                | "DAY_SECOND"
                | "DAY_MINUTE"
                | "DAY_HOUR"
                | "YEAR_MONTH"
        )
    }

    fn completed_interval_unit_ending_at(
        tokens: &[&SqlToken],
        idx: usize,
    ) -> Option<(usize, IntervalLeadingUnit)> {
        let unit_word = |idx: usize| match tokens.get(idx) {
            Some(SqlToken::Word(word)) if Self::is_completed_interval_unit_word(word) => {
                IntervalLeadingUnit::from_word(word)
            }
            _ => None,
        };

        if let Some(unit) = unit_word(idx) {
            return Some((idx, unit));
        }
        if !matches!(tokens.get(idx), Some(SqlToken::Symbol(sym)) if sym == ")") {
            return None;
        }

        let mut depth = 0i32;
        for open_idx in (0..idx).rev() {
            match tokens.get(open_idx) {
                Some(SqlToken::Symbol(sym)) if sym == ")" => depth += 1,
                Some(SqlToken::Symbol(sym)) if sym == "(" => {
                    if depth == 0 {
                        let unit_idx = open_idx.checked_sub(1)?;
                        return unit_word(unit_idx).map(|unit| (unit_idx, unit));
                    }
                    depth -= 1;
                }
                _ => {}
            }
        }
        None
    }

    fn completed_interval_operand_type(before: &[&SqlToken]) -> Option<PrecedingOperandType> {
        let last = before.len().checked_sub(1)?;
        let is_interval = |idx: usize| matches!(before.get(idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("INTERVAL"));
        let is_string = |idx: usize| matches!(before.get(idx), Some(SqlToken::String(_)));
        let is_to = |idx: usize| matches!(before.get(idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("TO"));

        let last_unit = Self::completed_interval_unit_ending_at(before, last)?.0;
        if last_unit.checked_sub(1).is_some_and(is_string)
            && last_unit.checked_sub(2).is_some_and(is_interval)
        {
            return Some(PrecedingOperandType::Other);
        }
        if last_unit.checked_sub(1).is_some_and(is_to) {
            let first_unit = last_unit.checked_sub(2).and_then(|idx| {
                Self::completed_interval_unit_ending_at(before, idx).map(|(idx, _)| idx)
            })?;
            if first_unit.checked_sub(1).is_some_and(is_string)
                && first_unit.checked_sub(2).is_some_and(is_interval)
            {
                return Some(PrecedingOperandType::Other);
            }
        }
        if last_unit >= 2
            && before
                .get(last_unit - 1)
                .is_some_and(|token| !matches!(token, SqlToken::String(_) | SqlToken::Comment(_)))
            && is_interval(last_unit - 2)
        {
            return Some(PrecedingOperandType::Other);
        }
        None
    }

    /// The interval-literal qualifier slot at the cursor, if any. An ANSI/Oracle
    /// `INTERVAL '<value>' <unit> [TO <unit>]` literal carries its value inside
    /// the string, so the qualifier that follows is keyword-only — a column is
    /// never valid. Anchored on `INTERVAL` immediately followed by a string
    /// literal, so MySQL's unquoted `INTERVAL <expr> <unit>` (where `<expr>` may
    /// be a column) is deliberately left untouched. Optional qualifier precision
    /// parens (for example `INTERVAL '5' DAY(2) TO …`) are treated as part of the
    /// completed unit.
    fn interval_unit_position(tokens: &[SqlToken], end: usize) -> Option<IntervalUnitSlot> {
        let toks = Self::meaningful_tokens_before(tokens, end);
        let last = toks.len().checked_sub(1)?;
        let is_interval = |idx: usize| matches!(toks.get(idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("INTERVAL"));
        let is_string = |idx: usize| matches!(toks.get(idx), Some(SqlToken::String(_)));
        let is_to = |idx: usize| matches!(toks.get(idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("TO"));

        // `INTERVAL '<value>' |` -> leading qualifier unit.
        if is_string(last) && last.checked_sub(1).is_some_and(is_interval) {
            return Some(IntervalUnitSlot::Leading);
        }
        // `INTERVAL '<value>' <unit> |` -> only `TO` (or end) follows.
        if let Some((unit_idx, leading_unit)) = Self::completed_interval_unit_ending_at(&toks, last)
        {
            if unit_idx.checked_sub(1).is_some_and(is_string)
                && unit_idx.checked_sub(2).is_some_and(is_interval)
            {
                return Some(IntervalUnitSlot::AwaitingTo { leading_unit });
            }
        }
        // `INTERVAL '<value>' <unit> TO |` -> trailing qualifier unit.
        if is_to(last) {
            if let Some((unit_idx, leading_unit)) = last
                .checked_sub(1)
                .and_then(|unit_idx| Self::completed_interval_unit_ending_at(&toks, unit_idx))
            {
                if unit_idx.checked_sub(1).is_some_and(is_string)
                    && unit_idx.checked_sub(2).is_some_and(is_interval)
                {
                    if !leading_unit.can_open_trailing_unit() {
                        return None;
                    }
                    return Some(IntervalUnitSlot::Trailing { leading_unit });
                }
            }
        }
        None
    }

    fn interval_unit_position_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
    ) -> Option<IntervalUnitSlot> {
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::interval_unit_position(tokens, end)
    }

    /// True when the cursor sits immediately after a typed temporal-literal
    /// introducer whose next token must be the literal body, not an identifier:
    /// `DATE |`, `TIME |`, `TIMESTAMP |`, `TIMESTAMP WITH TIME ZONE |`;
    /// and Oracle/ANSI `INTERVAL |`.
    /// MySQL's unquoted `INTERVAL <expr> <unit>` deliberately stays an expression
    /// slot, so it is not suppressed for MySQL-compatible dialects.
    fn temporal_literal_body_position(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        let toks = Self::meaningful_tokens_before(tokens, end);
        if Self::typed_temporal_literal_introducer_ending_before(&toks, toks.len()) {
            return true;
        }

        let Some(SqlToken::Word(word)) = toks.last() else {
            return false;
        };
        match word.to_ascii_uppercase().as_str() {
            "INTERVAL" => !crate::sql_text::mysql_compatibility_for_sql("", db_type),
            _ => false,
        }
    }

    fn temporal_literal_body_position_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        // Inside a CREATE TABLE element list, `DATE`/`TIMESTAMP` before the
        // cursor is the column's data type (`created_at TIMESTAMP DEFA|`), not
        // a temporal-literal introducer; that slot expects the column-property
        // keywords (`DEFAULT`/`NOT NULL`/…).
        if Self::cursor_is_at_create_table_element_keyword_slot_for_context(
            deep_ctx,
            exclude_current_identifier_chain,
            db_type,
        ) {
            return false;
        }
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::temporal_literal_body_position(tokens, end, db_type)
    }

    /// True when a value-expression construct keyword has been written and its
    /// next token must be `(`, not an identifier: `CAST |`, `EXISTS |`,
    /// `XMLCAST |`, and Oracle `CURSOR |`. The phase gate keeps DDL/name slots
    /// such as `CREATE TABLE IF NOT EXISTS |` out of this value-only suppression
    /// path.
    fn expression_construct_open_paren_position(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        let toks = Self::meaningful_tokens_before(tokens, end);
        let Some(SqlToken::Word(word)) = toks.last() else {
            return false;
        };
        if matches!(
            toks.get(toks.len().saturating_sub(2)),
            Some(SqlToken::Symbol(sym)) if sym == "."
        ) {
            return false;
        }
        let upper = word.to_ascii_uppercase();
        if upper == "CURSOR" {
            return !crate::sql_text::mysql_compatibility_for_sql("", db_type);
        }
        PARENTHESIZED_EXPRESSION_CONSTRUCT_WORDS.contains(&upper.as_str())
    }

    fn phase_allows_expression_construct_open_paren(phase: intellisense_context::SqlPhase) -> bool {
        matches!(
            phase,
            intellisense_context::SqlPhase::SelectList
                | intellisense_context::SqlPhase::JoinCondition
                | intellisense_context::SqlPhase::WhereClause
                | intellisense_context::SqlPhase::GroupByClause
                | intellisense_context::SqlPhase::HavingClause
                | intellisense_context::SqlPhase::OrderByClause
                | intellisense_context::SqlPhase::SetClause
                | intellisense_context::SqlPhase::DmlReturningList
                | intellisense_context::SqlPhase::ConnectByClause
                | intellisense_context::SqlPhase::StartWithClause
                | intellisense_context::SqlPhase::MatchRecognizeClause
                | intellisense_context::SqlPhase::ValuesClause
                | intellisense_context::SqlPhase::PivotClause
                | intellisense_context::SqlPhase::ModelClause
        )
    }

    fn expression_construct_open_paren_position_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if !Self::phase_allows_expression_construct_open_paren(deep_ctx.phase) {
            return false;
        }
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::expression_construct_open_paren_position(tokens, end, db_type)
    }

    fn full_text_against_open_paren_position(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if !crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return false;
        }
        let toks = Self::meaningful_tokens_before(tokens, end);
        let Some(SqlToken::Word(word)) = toks.last() else {
            return false;
        };
        if !word.eq_ignore_ascii_case("AGAINST") {
            return false;
        }
        if matches!(
            toks.get(toks.len().saturating_sub(2)),
            Some(SqlToken::Symbol(sym)) if sym == "."
        ) {
            return false;
        }
        let before_against = &toks[..toks.len().saturating_sub(1)];
        matches!(before_against.last(), Some(SqlToken::Symbol(sym)) if sym == ")")
            && Self::call_name_before_close(before_against).as_deref() == Some("MATCH")
    }

    fn full_text_against_open_paren_position_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if !Self::phase_allows_expression_construct_open_paren(deep_ctx.phase) {
            return false;
        }
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::full_text_against_open_paren_position(tokens, end, db_type)
    }

    /// True when a completed predicate operator has been written and the next
    /// token must be the opening `(` of its list/subquery operand:
    /// `<expr> IN |`, `<expr> NOT IN |`, and quantified comparisons such as
    /// `<expr> = ANY |`. The left-operand checks keep declaration parameter
    /// modes, set-operation `ALL`, and malformed words from becoming value-only
    /// slots.
    fn predicate_open_paren_position(tokens: &[SqlToken], end: usize) -> bool {
        let meaningful: Vec<(usize, &SqlToken)> = tokens
            .get(..end)
            .unwrap_or(tokens)
            .iter()
            .enumerate()
            .filter(|(_, token)| !matches!(token, SqlToken::Comment(_)))
            .collect();
        let Some((operator_idx, SqlToken::Word(word))) = meaningful.last().copied() else {
            return false;
        };
        if matches!(
            operator_idx.checked_sub(1).and_then(|idx| tokens.get(idx)),
            Some(SqlToken::Symbol(sym)) if sym == "."
        ) {
            return false;
        }

        let left_operand_before =
            |idx: usize| Self::cursor_has_complete_unqualified_operand_before(tokens, idx);

        if word.eq_ignore_ascii_case("IN") && left_operand_before(operator_idx) {
            return true;
        }

        if word.eq_ignore_ascii_case("IN") {
            let Some((not_idx, SqlToken::Word(prev))) = meaningful
                .len()
                .checked_sub(2)
                .and_then(|idx| meaningful.get(idx))
                .copied()
            else {
                return false;
            };
            return prev.eq_ignore_ascii_case("NOT") && left_operand_before(not_idx);
        }

        if !Self::is_quantified_comparison_keyword(word) {
            return false;
        }
        let Some((comparison_idx, SqlToken::Symbol(sym))) = meaningful
            .len()
            .checked_sub(2)
            .and_then(|idx| meaningful.get(idx))
            .copied()
        else {
            return false;
        };
        Self::is_comparison_operator_symbol(sym.as_str()) && left_operand_before(comparison_idx)
    }

    fn predicate_open_paren_position_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
    ) -> bool {
        if !Self::phase_allows_expression_construct_open_paren(deep_ctx.phase) {
            return false;
        }
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::predicate_open_paren_position(tokens, end)
    }

    fn token_is_unqualified_word(tokens: &[SqlToken], idx: usize, expected: &str) -> bool {
        matches!(tokens.get(idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case(expected))
            && !matches!(
                idx.checked_sub(1).and_then(|prev_idx| tokens.get(prev_idx)),
                Some(SqlToken::Symbol(sym)) if sym == "."
            )
    }

    fn cursor_has_complete_unqualified_operand_before(tokens: &[SqlToken], end: usize) -> bool {
        Self::cursor_follows_complete_operand(tokens, end) == Some(true)
            && !matches!(
                end.checked_sub(1).and_then(|prev_idx| tokens.get(prev_idx)),
                Some(SqlToken::Symbol(sym)) if sym == "."
            )
    }

    fn innermost_unclosed_open_paren_index(tokens: &[SqlToken], end: usize) -> Option<usize> {
        let mut stack = Vec::new();
        for (idx, token) in tokens.get(..end).unwrap_or(tokens).iter().enumerate() {
            match token {
                SqlToken::Comment(_) => {}
                SqlToken::Symbol(sym) if sym == "(" => stack.push(idx),
                SqlToken::Symbol(sym) if sym == ")" => {
                    stack.pop();
                }
                _ => {}
            }
        }
        stack.last().copied()
    }

    fn is_predicate_of_type_anchor(tokens: &[SqlToken], type_idx: usize) -> bool {
        if !Self::token_is_unqualified_word(tokens, type_idx, "TYPE") {
            return false;
        }

        let meaningful: Vec<(usize, &SqlToken)> = tokens
            .get(..=type_idx)
            .unwrap_or(tokens)
            .iter()
            .enumerate()
            .filter(|(_, token)| !matches!(token, SqlToken::Comment(_)))
            .collect();
        let Some(type_pos) = meaningful.iter().position(|(idx, _)| *idx == type_idx) else {
            return false;
        };
        let Some((of_idx, _)) = type_pos
            .checked_sub(1)
            .and_then(|pos| meaningful.get(pos))
            .copied()
        else {
            return false;
        };
        if !Self::token_is_unqualified_word(tokens, of_idx, "OF") {
            return false;
        }

        let Some((tail_idx, _)) = type_pos
            .checked_sub(2)
            .and_then(|pos| meaningful.get(pos))
            .copied()
        else {
            return false;
        };
        if Self::token_is_unqualified_word(tokens, tail_idx, "IS") {
            return Self::cursor_has_complete_unqualified_operand_before(tokens, tail_idx);
        }
        if !Self::token_is_unqualified_word(tokens, tail_idx, "NOT") {
            return false;
        }
        let Some((is_idx, _)) = type_pos
            .checked_sub(3)
            .and_then(|pos| meaningful.get(pos))
            .copied()
        else {
            return false;
        };
        Self::token_is_unqualified_word(tokens, is_idx, "IS")
            && Self::cursor_has_complete_unqualified_operand_before(tokens, is_idx)
    }

    fn is_predicate_of_type_open_paren_position(tokens: &[SqlToken], end: usize) -> bool {
        let meaningful: Vec<(usize, &SqlToken)> = tokens
            .get(..end)
            .unwrap_or(tokens)
            .iter()
            .enumerate()
            .filter(|(_, token)| !matches!(token, SqlToken::Comment(_)))
            .collect();
        let Some((type_idx, SqlToken::Word(_))) = meaningful.last().copied() else {
            return false;
        };
        Self::is_predicate_of_type_anchor(tokens, type_idx)
    }

    fn is_predicate_of_type_open_paren_position_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type)
            || !Self::phase_allows_expression_construct_open_paren(deep_ctx.phase)
        {
            return false;
        }
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        if Self::is_predicate_of_type_open_paren_position(tokens, end) {
            return true;
        }
        let statement_tokens = deep_ctx.statement_tokens.as_ref();
        let statement_end = Self::expected_suggestion_context_end(
            statement_tokens,
            deep_ctx.cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::is_predicate_of_type_open_paren_position(statement_tokens, statement_end)
    }

    fn is_predicate_of_type_list_open(tokens: &[SqlToken], open_idx: usize) -> bool {
        if !matches!(tokens.get(open_idx), Some(SqlToken::Symbol(sym)) if sym == "(") {
            return false;
        }
        let meaningful: Vec<(usize, &SqlToken)> = tokens
            .get(..open_idx)
            .unwrap_or(tokens)
            .iter()
            .enumerate()
            .filter(|(_, token)| !matches!(token, SqlToken::Comment(_)))
            .collect();
        let Some((type_idx, SqlToken::Word(_))) = meaningful.last().copied() else {
            return false;
        };
        Self::is_predicate_of_type_anchor(tokens, type_idx)
    }

    fn is_predicate_of_type_type_object_position(tokens: &[SqlToken], end: usize) -> bool {
        let Some(open_idx) = Self::innermost_unclosed_open_paren_index(tokens, end) else {
            return false;
        };
        if !Self::is_predicate_of_type_list_open(tokens, open_idx) {
            return false;
        }
        let meaningful: Vec<(usize, &SqlToken)> = tokens
            .get(open_idx..end)
            .unwrap_or(&[])
            .iter()
            .enumerate()
            .filter_map(|(offset, token)| {
                (!matches!(token, SqlToken::Comment(_))).then_some((open_idx + offset, token))
            })
            .collect();
        let Some((last_idx, last_token)) = meaningful.last().copied() else {
            return false;
        };
        match last_token {
            SqlToken::Symbol(sym) if sym == "(" => last_idx == open_idx,
            SqlToken::Symbol(sym) if sym == "," => true,
            SqlToken::Word(_) => Self::token_is_unqualified_word(tokens, last_idx, "ONLY"),
            _ => false,
        }
    }

    fn is_predicate_of_type_completed_type_tail_position(tokens: &[SqlToken], end: usize) -> bool {
        let Some(open_idx) = Self::innermost_unclosed_open_paren_index(tokens, end) else {
            return false;
        };
        if !Self::is_predicate_of_type_list_open(tokens, open_idx) {
            return false;
        }
        let meaningful: Vec<(usize, &SqlToken)> = tokens
            .get(open_idx..end)
            .unwrap_or(&[])
            .iter()
            .enumerate()
            .filter_map(|(offset, token)| {
                (!matches!(token, SqlToken::Comment(_))).then_some((open_idx + offset, token))
            })
            .collect();
        let Some((last_idx, SqlToken::Word(_))) = meaningful.last().copied() else {
            return false;
        };
        !Self::token_is_unqualified_word(tokens, last_idx, "ONLY")
    }

    fn is_predicate_of_type_completed_type_tail_position_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return false;
        }
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        if Self::is_predicate_of_type_completed_type_tail_position(tokens, end) {
            return true;
        }
        let statement_tokens = deep_ctx.statement_tokens.as_ref();
        let statement_end = Self::expected_suggestion_context_end(
            statement_tokens,
            deep_ctx.cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::is_predicate_of_type_completed_type_tail_position(statement_tokens, statement_end)
    }

    fn expected_is_of_type_keyword_candidates(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<&'static [&'static str]> {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return None;
        }
        if !Self::is_predicate_of_type_type_object_position(tokens, end) {
            return None;
        }
        let meaningful: Vec<(usize, &SqlToken)> = tokens
            .get(..end)
            .unwrap_or(tokens)
            .iter()
            .enumerate()
            .filter(|(_, token)| !matches!(token, SqlToken::Comment(_)))
            .collect();
        match meaningful.last().map(|(_, token)| *token) {
            Some(SqlToken::Symbol(sym)) if sym == "(" || sym == "," => Some(&["ONLY"]),
            _ => None,
        }
    }

    fn quantified_comparison_keyword_at_meaningful_index(
        tokens: &[SqlToken],
        meaningful: &[(usize, &SqlToken)],
        keyword_pos: usize,
    ) -> bool {
        let Some((_, SqlToken::Word(word))) = meaningful.get(keyword_pos).copied() else {
            return false;
        };
        if !Self::is_quantified_comparison_keyword(word) {
            return false;
        }
        let Some((comparison_idx, SqlToken::Symbol(sym))) = keyword_pos
            .checked_sub(1)
            .and_then(|idx| meaningful.get(idx))
            .copied()
        else {
            return false;
        };
        Self::is_comparison_operator_symbol(sym.as_str())
            && Self::cursor_has_complete_unqualified_operand_before(tokens, comparison_idx)
    }

    fn expected_subquery_start_keyword_candidates(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
        allow_table_introducer: bool,
    ) -> Option<&'static [&'static str]> {
        const SUBQUERY_START_KEYWORDS: &[&str] = &["SELECT", "WITH"];
        let meaningful: Vec<(usize, &SqlToken)> = tokens
            .get(..end)
            .unwrap_or(tokens)
            .iter()
            .enumerate()
            .filter(|(_, token)| !matches!(token, SqlToken::Comment(_)))
            .collect();
        let open_pos = meaningful.len().checked_sub(1)?;
        let Some((_, SqlToken::Symbol(sym))) = meaningful.get(open_pos).copied() else {
            return None;
        };
        if sym != "(" {
            return None;
        }
        let Some((introducer_idx, introducer)) = open_pos
            .checked_sub(1)
            .and_then(|pos| meaningful.get(pos))
            .copied()
        else {
            return Some(SUBQUERY_START_KEYWORDS);
        };
        let SqlToken::Word(word) = introducer else {
            // A bare grouping parenthesis after a comma/operator accepts an
            // ordinary value expression as well as a scalar subquery.
            return None;
        };
        if matches!(
            introducer_idx.checked_sub(1).and_then(|idx| tokens.get(idx)),
            Some(SqlToken::Symbol(prev_sym)) if prev_sym == "."
        ) {
            return None;
        }

        let upper = word.to_ascii_uppercase();
        if matches!(upper.as_str(), "THEN" | "ELSE") {
            return Some(SUBQUERY_START_KEYWORDS);
        }
        let prev_before_introducer = open_pos
            .checked_sub(2)
            .and_then(|pos| meaningful.get(pos))
            .map(|(_, token)| *token);
        let prev_prev_before_introducer = open_pos
            .checked_sub(3)
            .and_then(|pos| meaningful.get(pos))
            .map(|(_, token)| *token);
        let prev_prev_is_select = matches!(
            prev_prev_before_introducer,
            Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("SELECT")
        );
        let introducer_starts_select_item = prev_before_introducer.is_none_or(|token| {
            matches!(
                token,
                SqlToken::Word(word)
                    if matches!(
                        word.to_ascii_uppercase().as_str(),
                        "SELECT" | "THEN" | "ELSE" | "WHEN" | "AND" | "OR" | "NOT" | "BY"
                            | "WHERE" | "HAVING"
                    )
            )
                || matches!(
                    token,
                    SqlToken::Symbol(sym)
                        if matches!(
                            sym.as_str(),
                            "," | "+" | "-" | "/" | "%" | "||" | "=" | "<" | ">"
                        ) || (sym == "*" && !prev_prev_is_select)
                )
        });
        let table_introducer_position = !introducer_starts_select_item
            && (allow_table_introducer
                || !Self::cursor_is_before_current_query_from_clause(tokens, introducer_idx + 1));
        if table_introducer_position && matches!(upper.as_str(), "JOIN" | "FROM") {
            return Some(SUBQUERY_START_KEYWORDS);
        }
        if upper == "EXISTS" {
            return Some(SUBQUERY_START_KEYWORDS);
        }
        if upper == "CURSOR" && !crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return Some(SUBQUERY_START_KEYWORDS);
        }
        if Self::quantified_comparison_keyword_at_meaningful_index(
            tokens,
            &meaningful,
            open_pos - 1,
        ) {
            return Some(SUBQUERY_START_KEYWORDS);
        }
        // `IN (` deliberately stays outside this slot: an expression list is valid
        // there, so column/value suggestions must remain available.
        None
    }

    /// A SQL/JSON `VALUE (<expr>)` accepts any expression, so it is not a
    /// subquery-only/identifier-suppressing slot. When the user has nevertheless
    /// started typing `SELECT` or `WITH`, offer that exact scalar-subquery head
    /// without enrolling the slot in the stricter subquery-only policy.
    fn expected_json_value_parenthesized_subquery_keyword_candidates(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<&'static [&'static str]> {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return None;
        }
        let meaningful = tokens
            .get(..end.min(tokens.len()))
            .unwrap_or(tokens)
            .iter()
            .enumerate()
            .filter(|(_, token)| !matches!(token, SqlToken::Comment(_)))
            .collect::<Vec<_>>();
        let [(value_idx, SqlToken::Word(value)), (open_idx, SqlToken::Symbol(open))] =
            meaningful.get(meaningful.len().saturating_sub(2)..)?
        else {
            return None;
        };
        if !value.eq_ignore_ascii_case("VALUE") || open != "(" || value_idx >= open_idx {
            return None;
        }
        let (enclosing, _) =
            Self::innermost_open_paren_preceding_word_and_index(tokens, *open_idx)?;
        matches!(
            enclosing.to_ascii_uppercase().as_str(),
            "JSON_OBJECT" | "JSON_OBJECTAGG"
        )
        .then_some(&["SELECT", "WITH"])
    }

    fn expected_subquery_start_keyword_candidates_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<&'static [&'static str]> {
        if !Self::phase_allows_expression_construct_open_paren(deep_ctx.phase) {
            return None;
        }
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::expected_subquery_start_keyword_candidates(
            tokens,
            end,
            db_type,
            deep_ctx.phase.is_table_context(),
        )
    }

    /// True when a table-source construct keyword has been written in a `FROM`
    /// clause and its next token must be `(`, not another relation name:
    /// `JSON_TABLE |`, Oracle `XMLTABLE |`, and Oracle `TABLE |`.
    fn table_source_construct_open_paren_position(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        let toks = Self::meaningful_tokens_before(tokens, end);
        let Some(SqlToken::Word(word)) = toks.last() else {
            return false;
        };
        if matches!(
            toks.get(toks.len().saturating_sub(2)),
            Some(SqlToken::Symbol(sym)) if sym == "."
        ) {
            return false;
        }
        let upper = word.to_ascii_uppercase();
        if !PARENTHESIZED_TABLE_SOURCE_CONSTRUCT_WORDS.contains(&upper.as_str()) {
            return false;
        }
        if matches!(upper.as_str(), "TABLE" | "XMLTABLE") {
            return !crate::sql_text::mysql_compatibility_for_sql("", db_type);
        }
        true
    }

    fn table_source_construct_open_paren_position_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if !matches!(deep_ctx.phase, intellisense_context::SqlPhase::FromClause) {
            return false;
        }
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::table_source_construct_open_paren_position(tokens, end, db_type)
    }

    fn cursor_is_inside_table_source_construct_argument(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        let toks = Self::meaningful_tokens_before(tokens, end);
        let mut depth = 0usize;
        for idx in (0..toks.len()).rev() {
            match toks[idx] {
                SqlToken::Symbol(sym) if sym == ")" => depth = depth.saturating_add(1),
                SqlToken::Symbol(sym) if sym == "(" => {
                    if depth > 0 {
                        depth = depth.saturating_sub(1);
                        continue;
                    }
                    let Some(SqlToken::Word(word)) = idx.checked_sub(1).and_then(|prev| toks.get(prev))
                    else {
                        return false;
                    };
                    let upper = word.to_ascii_uppercase();
                    if !PARENTHESIZED_TABLE_SOURCE_CONSTRUCT_WORDS.contains(&upper.as_str()) {
                        return false;
                    }
                    if matches!(upper.as_str(), "TABLE" | "XMLTABLE") {
                        return !crate::sql_text::mysql_compatibility_for_sql("", db_type);
                    }
                    return true;
                }
                _ => {}
            }
        }
        false
    }

    fn cursor_is_inside_table_source_construct_argument_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::cursor_is_inside_table_source_construct_argument(tokens, end, db_type)
    }

    fn cursor_follows_relation_name_introducer(tokens: &[SqlToken], end: usize) -> bool {
        matches!(
            Self::meaningful_tokens_before(tokens, end).last(),
            Some(SqlToken::Word(word))
                if matches!(
                    word.to_ascii_uppercase().as_str(),
                    "FROM"
                        | "JOIN"
                        | "UPDATE"
                        | "INTO"
                        | "REFERENCES"
                        | "USING"
                        | "TABLE"
                        | "VIEW"
                        | "ON"
                )
        )
    }

    fn token_introduces_xmltable_table_source(tokens: &[SqlToken], xmltable_idx: usize) -> bool {
        let meaningful = tokens
            .iter()
            .enumerate()
            .take(xmltable_idx)
            .filter_map(|(idx, token)| (!matches!(token, SqlToken::Comment(_))).then_some((idx, token)))
            .collect::<Vec<_>>();
        let mut head_pos = meaningful.len();
        while head_pos >= 2 {
            let dot_pos = head_pos - 1;
            let qualifier_pos = head_pos - 2;
            if !matches!(meaningful.get(dot_pos), Some((_, SqlToken::Symbol(sym))) if sym == ".")
                || !matches!(meaningful.get(qualifier_pos), Some((_, SqlToken::Word(_))))
            {
                break;
            }
            head_pos -= 2;
        }

        match head_pos.checked_sub(1).and_then(|idx| meaningful.get(idx)) {
            None => true,
            Some((_, SqlToken::Symbol(sym))) => matches!(sym.as_str(), "(" | ","),
            Some((_, SqlToken::Word(word))) => matches!(
                word.to_ascii_uppercase().as_str(),
                "FROM"
                    | "JOIN"
                    | "INNER"
                    | "LEFT"
                    | "RIGHT"
                    | "FULL"
                    | "CROSS"
                    | "NATURAL"
                    | "OUTER"
                    | "APPLY"
                    | "LATERAL"
                    | "STRAIGHT_JOIN"
            ),
            _ => false,
        }
    }

    fn cursor_is_inside_mysql_oracle_only_xmltable_slot(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if !crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return false;
        }
        let Some((word, open_idx)) = Self::innermost_open_paren_preceding_word_and_index(tokens, end)
        else {
            return false;
        };
        if !word.eq_ignore_ascii_case("XMLTABLE") {
            return false;
        }
        if tokens.get(open_idx..end).unwrap_or(&[]).iter().any(
            |token| matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("COLUMNS")),
        ) {
            return false;
        }
        let Some(xmltable_idx) = Self::previous_non_comment_token_index(tokens, open_idx) else {
            return false;
        };
        matches!(tokens.get(xmltable_idx), Some(SqlToken::Word(name)) if name.eq_ignore_ascii_case("XMLTABLE"))
            && Self::token_introduces_xmltable_table_source(tokens, xmltable_idx)
    }

    fn cursor_is_inside_mysql_oracle_only_xmltable_slot_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if !matches!(deep_ctx.phase, intellisense_context::SqlPhase::FromClause) {
            return false;
        }
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let context_end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::cursor_is_inside_mysql_oracle_only_xmltable_slot(tokens, context_end, db_type) || {
            let statement_tokens = deep_ctx.statement_tokens.as_ref();
            let statement_context_end = Self::expected_suggestion_context_end(
                statement_tokens,
                deep_ctx.cursor_token_len,
                exclude_current_identifier_chain,
            );
            Self::cursor_is_inside_mysql_oracle_only_xmltable_slot(
                statement_tokens,
                statement_context_end,
                db_type,
            )
        }
    }

    /// MySQL object types that accept `DROP <obj> [IF EXISTS] <name>`.
    fn is_mysql_droppable_object_type(word: &str) -> bool {
        matches!(
            word,
            "DATABASE"
                | "EVENT"
                | "FUNCTION"
                | "PROCEDURE"
                | "ROLE"
                | "SCHEMA"
                | "SERVER"
                | "TABLE"
                | "TRIGGER"
                | "USER"
                | "VIEW"
        )
    }

    /// `DROP [TEMPORARY] <object> |` — the object-name slot, where the structural
    /// candidates offer the optional `IF [EXISTS]` prefix but an existing object
    /// name is equally grammatical. Unlike a `CREATE <object> |` slot (a brand-new
    /// name), the catalog must stay available here, so this slot is excluded from
    /// the structural-keyword suppression. Only the bare name slot qualifies; past
    /// the name the DDL-tail handler suppresses, and `DROP <obj> IF EXISTS |` keeps
    /// the catalog on its own.
    fn cursor_is_at_mysql_drop_object_name_slot(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if !crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return false;
        }
        let tokens = deep_ctx.statement_tokens.as_ref();
        let end = Self::expected_suggestion_context_end(
            tokens,
            deep_ctx.cursor_token_len,
            exclude_current_identifier_chain,
        );
        let words = Self::words_for_keyword_slot(tokens, end);
        match words.as_slice() {
            [drop, object_type]
                if drop == "DROP" && Self::is_mysql_droppable_object_type(object_type) =>
            {
                true
            }
            [drop, temporary, object_type]
                if drop == "DROP"
                    && temporary == "TEMPORARY"
                    && Self::is_mysql_droppable_object_type(object_type) =>
            {
                true
            }
            [drop, object_type, if_kw, exists]
                if drop == "DROP"
                    && Self::is_mysql_droppable_object_type(object_type)
                    && if_kw == "IF"
                    && exists == "EXISTS" =>
            {
                true
            }
            [drop, temporary, object_type, if_kw, exists]
                if drop == "DROP"
                    && temporary == "TEMPORARY"
                    && Self::is_mysql_droppable_object_type(object_type)
                    && if_kw == "IF"
                    && exists == "EXISTS" =>
            {
                true
            }
            _ => false,
        }
    }

    /// `LOCK TABLES <tbl> …` / `FLUSH [LOCAL] TABLES <tbl> …` table-list slots,
    /// where a relation is named: right after the `TABLE(S)` keyword, after a comma
    /// (the next locked/flushed table) or after a schema dot. The structural
    /// candidates claim these slots (with an empty or `FOR`/`WITH` keyword set) to
    /// block keyword noise, but the table catalog must still be offered — unlike
    /// the alias (`… AS |`) or lock-type (`… emp |`→READ/WRITE) slots, which name no
    /// relation and stay suppressed.
    fn cursor_is_at_mysql_lock_or_flush_tables_relation_slot(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if !crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return false;
        }
        let tokens = deep_ctx.statement_tokens.as_ref();
        let end = Self::expected_suggestion_context_end(
            tokens,
            deep_ctx.cursor_token_len,
            exclude_current_identifier_chain,
        );
        let words = Self::words_for_keyword_slot(tokens, end);
        let is_lock_or_flush_tables = match words.first().map(String::as_str) {
            Some("LOCK") => words.get(1).map(String::as_str) == Some("TABLES"),
            Some("FLUSH") => words.iter().any(|word| word == "TABLE" || word == "TABLES"),
            _ => false,
        };
        if !is_lock_or_flush_tables {
            return false;
        }
        let last_token_is = |symbol: &str| {
            matches!(
                Self::meaningful_tokens_before(tokens, end).last(),
                Some(SqlToken::Symbol(sym)) if sym == symbol
            )
        };
        matches!(words.last().map(String::as_str), Some("TABLE" | "TABLES"))
            || last_token_is(",")
            || last_token_is(".")
    }

    /// MySQL prepared-statement commands name client-side statement handles and
    /// user-variable/string expressions, not schema objects. Keep the base catalog
    /// out of those slots while the structural keyword handler still supplies the
    /// fixed connectors (`FROM`, `PREPARE`, `USING`) where appropriate.
    fn cursor_is_at_mysql_prepared_statement_non_catalog_slot_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if !crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return false;
        }
        let tokens = deep_ctx.statement_tokens.as_ref();
        let end = Self::expected_suggestion_context_end(
            tokens,
            deep_ctx.cursor_token_len,
            exclude_current_identifier_chain,
        );
        let words = Self::words_for_keyword_slot(tokens, end);
        matches!(
            words.first().map(String::as_str),
            Some("PREPARE" | "DEALLOCATE" | "EXEC" | "EXECUTE")
        )
    }

    fn cursor_is_at_mysql_prepared_statement_handle_reference_slot(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if !crate::sql_text::mysql_compatibility_for_sql("", db_type)
            || Self::unclosed_paren_count(tokens, end) != 0
        {
            return false;
        }
        let start = Self::plsql_statement_slot_start(tokens, end);
        let words = tokens
            .get(start..end.min(tokens.len()))
            .unwrap_or(&[])
            .iter()
            .filter_map(|token| match token {
                SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
                _ => None,
            })
            .collect::<Vec<_>>();
        matches!(words.as_slice(), [execute] if execute == "EXECUTE")
            || matches!(
                words.as_slice(),
                [deallocate, prepare] if deallocate == "DEALLOCATE" && prepare == "PREPARE"
            )
    }

    fn cursor_is_at_mysql_prepared_statement_handle_reference_slot_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        let tokens = deep_ctx.statement_tokens.as_ref();
        let end = Self::expected_suggestion_context_end(
            tokens,
            deep_ctx.cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::cursor_is_at_mysql_prepared_statement_handle_reference_slot(tokens, end, db_type)
    }

    fn mysql_prepared_statement_handle_suggestions(
        deep_ctx: &intellisense_context::CursorContext,
        prefix: &str,
    ) -> Vec<String> {
        let prefix_upper = Self::local_identifier_lookup_upper(prefix);
        let tokens = deep_ctx.statement_tokens.as_ref();
        let end = Self::expected_suggestion_context_end(
            tokens,
            deep_ctx.cursor_token_len,
            !prefix.is_empty(),
        )
        .min(tokens.len());
        let mut seen = std::collections::HashSet::new();
        let mut handles = Vec::new();

        for (idx, token) in tokens.iter().take(end).enumerate() {
            if !matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("PREPARE")) {
                continue;
            }
            let Some(name_idx) = Self::next_non_comment_token_index(tokens, idx + 1) else {
                continue;
            };
            if name_idx >= end {
                continue;
            }
            let Some(name) = Self::token_word(&tokens[name_idx])
                .and_then(Self::local_identifier_suggestion_from_word)
            else {
                continue;
            };
            let upper = Self::local_identifier_lookup_upper(&name);
            if !Self::local_symbol_matches_prefix(&name, &upper, &prefix_upper) {
                continue;
            }
            if seen.insert(upper) {
                handles.push(name);
            }
        }

        handles
    }

    /// MySQL component/plugin commands take external component URNs, plugin
    /// identifiers, or SONAME string values; `HANDLER ... OPEN AS` takes a
    /// handler alias. None of those are schema objects, so the flat catalog must
    /// stay out even when the structural keyword source has no keyword to emit.
    fn cursor_is_at_mysql_component_plugin_or_handler_value_slot_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if !crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return false;
        }
        let tokens = deep_ctx.statement_tokens.as_ref();
        let end = Self::expected_suggestion_context_end(
            tokens,
            deep_ctx.cursor_token_len,
            exclude_current_identifier_chain,
        );
        let words = Self::words_for_keyword_slot(tokens, end);
        match words.as_slice() {
            [install, component, ..] if install == "INSTALL" && component == "COMPONENT" => true,
            [install, plugin, ..] if install == "INSTALL" && plugin == "PLUGIN" => true,
            [uninstall, component, ..] if uninstall == "UNINSTALL" && component == "COMPONENT" => {
                true
            }
            [uninstall, plugin, ..] if uninstall == "UNINSTALL" && plugin == "PLUGIN" => true,
            [handler, ..]
                if handler == "HANDLER"
                    && words.windows(2).any(
                        |window| matches!(window, [open, as_kw] if open == "OPEN" && as_kw == "AS"),
                    ) =>
            {
                true
            }
            [handler, ..] if handler == "HANDLER" => {
                Self::cursor_is_at_mysql_handler_read_value_slot(tokens, end)
            }
            _ => false,
        }
    }

