    fn mysql_named_value_suggestions_for_context(
        data: &mut IntellisenseData,
        prefix: &str,
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Vec<String> {
        if let Some(suggestions) = Self::mysql_charset_or_collation_values_for_context(
            prefix,
            deep_ctx,
            exclude_current_identifier_chain,
            db_type,
        ) {
            return suggestions;
        }

        if Self::cursor_is_at_mysql_use_database_slot_for_context(
            deep_ctx,
            exclude_current_identifier_chain,
            db_type,
        ) {
            return data.get_user_suggestions(prefix);
        }
        if Self::cursor_is_at_mysql_set_system_variable_name_slot_for_context(
            deep_ctx,
            exclude_current_identifier_chain,
            db_type,
        ) {
            return Self::filter_expected_candidates(prefix, MYSQL_SYSTEM_VARIABLE_NAME_SUGGESTIONS);
        }

        Vec::new()
    }

    fn mysql_system_variable_reference_suggestions_from_text(
        text_before_cursor: &str,
        prefix: &str,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Vec<String> {
        if !crate::sql_text::mysql_compatibility_for_sql("", db_type)
            || !text_before_cursor.ends_with(prefix)
        {
            return Vec::new();
        }
        let head = text_before_cursor
            .get(..text_before_cursor.len().saturating_sub(prefix.len()))
            .unwrap_or("")
            .trim_end();
        if head.ends_with("@@") {
            let mut suggestions = Self::filter_expected_candidates(
                prefix,
                &["GLOBAL", "LOCAL", "SESSION"],
            );
            suggestions.extend(Self::filter_expected_candidates(
                prefix,
                MYSQL_SYSTEM_VARIABLE_NAME_SUGGESTIONS,
            ));
            return suggestions;
        }
        let upper = head.to_ascii_uppercase();
        if ["@@GLOBAL.", "@@LOCAL.", "@@SESSION."]
            .iter()
            .any(|scope| upper.ends_with(scope))
        {
            return Self::filter_expected_candidates(
                prefix,
                MYSQL_SYSTEM_VARIABLE_NAME_SUGGESTIONS,
            );
        }
        Vec::new()
    }

