    fn alter_table_add_declared_column_suggestions_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        prefix: &str,
    ) -> Option<Vec<String>> {
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        let toks = Self::meaningful_tokens_before(tokens, end);
        if !matches!(
            toks.get(0..2),
            Some([SqlToken::Word(alter), SqlToken::Word(table)])
                if alter.eq_ignore_ascii_case("ALTER") && table.eq_ignore_ascii_case("TABLE")
        ) {
            return None;
        }
        let (_table, after_table) = Self::mysql_identifier_chain(&toks, 2)?;
        let tail = &toks[after_table..];
        let add_idx = tail.iter().position(
            |token| matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("ADD")),
        )?;
        let after_add = tail.get(add_idx + 1..).unwrap_or(&[]);
        let after_add = match after_add.first() {
            Some(SqlToken::Symbol(sym)) if sym == "(" => &after_add[1..],
            _ => after_add,
        };
        let column_name_from_alter_definition = |def: &[&SqlToken]| {
            let def = if matches!(
                def.first(),
                Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("COLUMN")
            ) {
                &def[1..]
            } else {
                def
            };
            Self::create_table_column_name_from_definition(def)
        };

        let mut segment_start = 0usize;
        let mut segment_depth = 0i32;
        let mut declared_columns = Vec::new();
        for (idx, token) in after_add.iter().enumerate() {
            match token {
                SqlToken::Symbol(sym) if sym == "(" || sym == "[" => segment_depth += 1,
                SqlToken::Symbol(sym) if sym == ")" || sym == "]" => {
                    segment_depth = (segment_depth - 1).max(0)
                }
                SqlToken::Symbol(sym) if sym == "," && segment_depth == 0 => {
                    if let Some(column) =
                        column_name_from_alter_definition(&after_add[segment_start..idx])
                    {
                        declared_columns.push(column);
                    }
                    segment_start = idx + 1;
                }
                _ => {}
            }
        }

        let current_def = Self::current_create_table_definition(&after_add[segment_start..]);
        let active_marker =
            Self::create_table_definition_active_column_reference_marker(current_def)?;
        if active_marker != "AS" {
            if let Some(column) = column_name_from_alter_definition(current_def) {
                declared_columns.push(column);
            }
        }

        Some(
            declared_columns
                .into_iter()
                .filter(|column| {
                    prefix.is_empty()
                        || column
                            .to_ascii_uppercase()
                            .starts_with(&prefix.to_ascii_uppercase())
                })
                .collect(),
        )
    }

    fn mysql_load_file_set_value_non_catalog_slot(tokens: &[SqlToken], end: usize) -> bool {
        let Some((_table, tail)) = Self::mysql_load_file_target_table_tail(tokens, end) else {
            return false;
        };
        let mut depth = 0i32;
        let mut in_load_set_clause = false;
        let mut segment_has_equals = false;
        let mut prev_top_level_word: Option<String> = None;

        for token in tail {
            match token {
                SqlToken::Symbol(symbol) if symbol == "(" => depth += 1,
                SqlToken::Symbol(symbol) if symbol == ")" => depth = (depth - 1).max(0),
                SqlToken::Symbol(symbol) if depth == 0 && symbol == "," => {
                    segment_has_equals = false;
                }
                SqlToken::Symbol(symbol) if depth == 0 && symbol == "=" => {
                    segment_has_equals = true;
                }
                SqlToken::Word(word) if depth == 0 => {
                    let upper = word.to_ascii_uppercase();
                    if upper == "SET" && prev_top_level_word.as_deref() != Some("CHARACTER") {
                        in_load_set_clause = true;
                        segment_has_equals = false;
                    }
                    prev_top_level_word = Some(upper);
                }
                _ => {}
            }
        }

        in_load_set_clause && segment_has_equals
    }

    fn mysql_load_file_column_list_tail_keyword_candidates(
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<&'static [&'static str]> {
        let (_table, tail) = Self::mysql_load_file_target_table_tail(tokens, end)?;
        if !matches!(tail.first(), Some(SqlToken::Symbol(symbol)) if symbol == "(") {
            return None;
        }

        let mut depth = 0i32;
        let mut saw_closed_outer_column_list = false;
        for token in tail {
            match token {
                SqlToken::Symbol(symbol) if symbol == "(" => {
                    depth += 1;
                }
                SqlToken::Symbol(symbol) if symbol == ")" => {
                    depth = (depth - 1).max(0);
                    if depth == 0 {
                        saw_closed_outer_column_list = true;
                    }
                }
                SqlToken::Word(word)
                    if saw_closed_outer_column_list
                        && depth == 0
                        && word.eq_ignore_ascii_case("SET") =>
                {
                    return None;
                }
                SqlToken::Symbol(symbol)
                    if saw_closed_outer_column_list && depth == 0 && symbol == "," =>
                {
                    return None;
                }
                SqlToken::Word(_) if saw_closed_outer_column_list && depth == 0 => {
                    return None;
                }
                _ => {}
            }
        }

        (saw_closed_outer_column_list && depth == 0).then_some(&["SET"])
    }

    fn mysql_select_into_file_tail(words: &[String]) -> Option<&[String]> {
        let into_idx = words.iter().rposition(|word| word == "INTO")?;
        if !words[..into_idx].iter().any(|word| word == "SELECT") {
            return None;
        }
        if matches!(
            words.first().map(String::as_str),
            Some("INSERT" | "LOAD" | "REPLACE")
        ) {
            return None;
        }
        Some(&words[into_idx + 1..])
    }

    fn mysql_select_into_file_is_pre_from(words: &[String]) -> bool {
        let Some(into_idx) = words.iter().rposition(|word| word == "INTO") else {
            return false;
        };
        !words[..into_idx].iter().any(|word| word == "FROM")
    }

    fn mysql_select_into_file_value_non_catalog_slot(words: &[String]) -> bool {
        let Some(tail) = Self::mysql_select_into_file_tail(words) else {
            return false;
        };
        match tail {
            [target] if matches!(target.as_str(), "DUMPFILE" | "OUTFILE") => true,
            [outfile, _file, character, set]
                if outfile == "OUTFILE" && character == "CHARACTER" && set == "SET" =>
            {
                true
            }
            [outfile, _file, fields, option, by]
                if outfile == "OUTFILE"
                    && fields == "FIELDS"
                    && matches!(option.as_str(), "ENCLOSED" | "ESCAPED" | "TERMINATED")
                    && by == "BY" =>
            {
                true
            }
            [outfile, _file, fields, optionally, enclosed, by]
                if outfile == "OUTFILE"
                    && fields == "FIELDS"
                    && optionally == "OPTIONALLY"
                    && enclosed == "ENCLOSED"
                    && by == "BY" =>
            {
                true
            }
            [outfile, _file, lines, option, by]
                if outfile == "OUTFILE"
                    && lines == "LINES"
                    && matches!(option.as_str(), "STARTING" | "TERMINATED")
                    && by == "BY" =>
            {
                true
            }
            _ => false,
        }
    }

    fn expected_mysql_select_into_file_keyword_candidates(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<&'static [&'static str]> {
        if !crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return None;
        }
        const TARGETS: &[&str] = &["DUMPFILE", "OUTFILE"];
        const OUTFILE_TAIL: &[&str] = &["CHARACTER", "FIELDS", "LINES"];
        const OUTFILE_TAIL_BEFORE_FROM: &[&str] = &["CHARACTER", "FIELDS", "FROM", "LINES"];
        const DUMPFILE_TAIL_BEFORE_FROM: &[&str] = &["FROM"];
        const FIELD_OPTIONS: &[&str] = &["ENCLOSED", "ESCAPED", "OPTIONALLY", "TERMINATED"];
        const LINE_OPTIONS: &[&str] = &["STARTING", "TERMINATED"];
        const AFTER_FIELD_VALUE: &[&str] =
            &["ENCLOSED", "ESCAPED", "LINES", "OPTIONALLY", "TERMINATED"];
        const AFTER_FIELD_VALUE_BEFORE_FROM: &[&str] = &[
            "ENCLOSED",
            "ESCAPED",
            "FROM",
            "LINES",
            "OPTIONALLY",
            "TERMINATED",
        ];
        const AFTER_LINE_VALUE_BEFORE_FROM: &[&str] = &["FROM"];

        let words = Self::meaningful_tokens_before(tokens, end)
            .into_iter()
            .filter_map(|token| match token {
                SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
                SqlToken::String(_) => Some("__VALUE__".to_string()),
                SqlToken::Symbol(_) | SqlToken::Comment(_) => None,
            })
            .collect::<Vec<_>>();
        let before_from = Self::mysql_select_into_file_is_pre_from(&words);
        let tail = Self::mysql_select_into_file_tail(&words)?;
        match tail {
            [] => Some(TARGETS),
            [target] if matches!(target.as_str(), "DUMPFILE" | "OUTFILE") => Some(&[]),
            [dumpfile, _file] if dumpfile == "DUMPFILE" => {
                before_from.then_some(DUMPFILE_TAIL_BEFORE_FROM)
            }
            [outfile, _file] if outfile == "OUTFILE" => Some(if before_from {
                OUTFILE_TAIL_BEFORE_FROM
            } else {
                OUTFILE_TAIL
            }),
            [outfile, _file, character] if outfile == "OUTFILE" && character == "CHARACTER" => {
                Some(&["SET"])
            }
            [outfile, _file, character, set]
                if outfile == "OUTFILE" && character == "CHARACTER" && set == "SET" =>
            {
                Some(&[])
            }
            [outfile, _file, character, set, _value]
                if outfile == "OUTFILE" && character == "CHARACTER" && set == "SET" =>
            {
                Some(if before_from {
                    &["FIELDS", "FROM", "LINES"][..]
                } else {
                    &["FIELDS", "LINES"][..]
                })
            }
            [outfile, _file, fields] if outfile == "OUTFILE" && fields == "FIELDS" => {
                Some(FIELD_OPTIONS)
            }
            [outfile, _file, fields, option]
                if outfile == "OUTFILE"
                    && fields == "FIELDS"
                    && matches!(option.as_str(), "ENCLOSED" | "ESCAPED" | "TERMINATED") =>
            {
                Some(&["BY"])
            }
            [outfile, _file, fields, optionally]
                if outfile == "OUTFILE" && fields == "FIELDS" && optionally == "OPTIONALLY" =>
            {
                Some(&["ENCLOSED"])
            }
            [outfile, _file, fields, optionally, enclosed]
                if outfile == "OUTFILE"
                    && fields == "FIELDS"
                    && optionally == "OPTIONALLY"
                    && enclosed == "ENCLOSED" =>
            {
                Some(&["BY"])
            }
            [outfile, _file, fields, option, by]
                if outfile == "OUTFILE"
                    && fields == "FIELDS"
                    && matches!(option.as_str(), "ENCLOSED" | "ESCAPED" | "TERMINATED")
                    && by == "BY" =>
            {
                Some(&[])
            }
            [outfile, _file, fields, optionally, enclosed, by]
                if outfile == "OUTFILE"
                    && fields == "FIELDS"
                    && optionally == "OPTIONALLY"
                    && enclosed == "ENCLOSED"
                    && by == "BY" =>
            {
                Some(&[])
            }
            [outfile, _file, fields, option, by, _value]
                if outfile == "OUTFILE"
                    && fields == "FIELDS"
                    && matches!(option.as_str(), "ENCLOSED" | "ESCAPED" | "TERMINATED")
                    && by == "BY" =>
            {
                Some(if before_from {
                    AFTER_FIELD_VALUE_BEFORE_FROM
                } else {
                    AFTER_FIELD_VALUE
                })
            }
            [outfile, _file, fields, optionally, enclosed, by, _value]
                if outfile == "OUTFILE"
                    && fields == "FIELDS"
                    && optionally == "OPTIONALLY"
                    && enclosed == "ENCLOSED"
                    && by == "BY" =>
            {
                Some(if before_from {
                    AFTER_FIELD_VALUE_BEFORE_FROM
                } else {
                    AFTER_FIELD_VALUE
                })
            }
            [outfile, _file, lines] if outfile == "OUTFILE" && lines == "LINES" => {
                Some(LINE_OPTIONS)
            }
            [outfile, _file, lines, option]
                if outfile == "OUTFILE"
                    && lines == "LINES"
                    && matches!(option.as_str(), "STARTING" | "TERMINATED") =>
            {
                Some(&["BY"])
            }
            [outfile, _file, lines, option, by]
                if outfile == "OUTFILE"
                    && lines == "LINES"
                    && matches!(option.as_str(), "STARTING" | "TERMINATED")
                    && by == "BY" =>
            {
                Some(&[])
            }
            [outfile, _file, lines, option, by, _value]
                if outfile == "OUTFILE"
                    && lines == "LINES"
                    && matches!(option.as_str(), "STARTING" | "TERMINATED")
                    && by == "BY" =>
            {
                before_from.then_some(AFTER_LINE_VALUE_BEFORE_FROM)
            }
            _ => None,
        }
    }

    fn mysql_select_into_file_keyword_slot_suppresses_identifiers(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if Self::expected_mysql_select_into_file_keyword_candidates(tokens, end, db_type).is_none()
        {
            return false;
        }
        let words = Self::meaningful_tokens_before(tokens, end)
            .into_iter()
            .filter_map(|token| match token {
                SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
                SqlToken::String(_) => Some("__VALUE__".to_string()),
                SqlToken::Symbol(_) | SqlToken::Comment(_) => None,
            })
            .collect::<Vec<_>>();
        Self::mysql_select_into_file_tail(&words).is_some_and(|tail| !tail.is_empty())
    }

    fn expected_mysql_select_into_file_keyword_candidates_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<&'static [&'static str]> {
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::expected_mysql_select_into_file_keyword_candidates(tokens, end, db_type)
    }

    /// Context wrapper enrolling the post-object statement-tail keyword slots
    /// (`DROP TABLE t |`→CASCADE/PURGE, `TRUNCATE TABLE t |`, `COMMENT ON |`,
    /// `ALTER TABLE t |`→ADD/DROP/…, `CREATE INDEX i |`→ON, …) in the
    /// identifier-suppression chokepoint. Every arm of the underlying handler sits
    /// *past* a complete object where a bare relation is no longer grammatical, so
    /// the base catalog must be suppressed; the object-name/target positions (a
    /// `CREATE INDEX i ON |` table, a `CREATE SYNONYM s FOR |` target) return `None`
    /// there and stay available.
    fn cursor_is_at_statement_tail_keyword_slot_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::expected_statement_tail_keyword_candidates(tokens, end, db_type).is_some()
    }

    /// Words that may sit between a `CREATE`/`DROP`/`ALTER` head verb and the
    /// object-type keyword without being the type (`CREATE OR REPLACE`, `CREATE
    /// GLOBAL TEMPORARY`, `CREATE UNIQUE INDEX`, `DROP PUBLIC SYNONYM`, …).
    fn is_ddl_object_type_modifier(word: &str) -> bool {
        matches!(
            word,
            "OR" | "REPLACE"
                | "GLOBAL"
                | "TEMPORARY"
                | "PRIVATE"
                | "UNIQUE"
                | "BITMAP"
                | "MULTIVALUE"
                | "PUBLIC"
                | "SHARED"
                | "BIGFILE"
                | "SMALLFILE"
                | "UNDO"
                | "FORCE"
                | "NO"
                | "NONEDITIONABLE"
                | "EDITIONABLE"
        )
    }

    /// The canonical object type a single-object `CREATE`/`DROP` operates on,
    /// found as the first object-type keyword after the head verb and its leading
    /// modifiers, paired with the number of words that follow the type phrase. The
    /// trailing count separates the bare object-name slot (`0`, the name is not
    /// yet written) from the option region (`>= 1`, the name and beyond). Picking
    /// the *leading* type means a later option keyword (the `TABLESPACE` of
    /// `CREATE TABLE … TABLESPACE`) is never mistaken for the object type.
    /// Multi-word types collapse to a single canonical token.
    fn leading_ddl_object_type(words: &[String]) -> Option<(&'static str, usize)> {
        const TYPES: &[&str] = &[
            "TABLE",
            "VIEW",
            "INDEX",
            "SEQUENCE",
            "SYNONYM",
            "PROCEDURE",
            "FUNCTION",
            "PACKAGE",
            "TYPE",
            "TRIGGER",
            "USER",
            "ROLE",
            "TABLESPACE",
            "PROFILE",
            "DIRECTORY",
            "JAVA",
            "CLUSTER",
            "DATABASE",
            "ROLLBACK",
            "SCHEMA",
            "EVENT",
            "SERVER",
            "CONTEXT",
            "DIMENSION",
            "OPERATOR",
            "INDEXTYPE",
            "EDITION",
            "LIBRARY",
            "MATERIALIZED",
        ];
        let mut idx = 1; // skip the head verb
        while words
            .get(idx)
            .is_some_and(|word| Self::is_ddl_object_type_modifier(word))
        {
            idx += 1;
        }
        let ty = TYPES
            .iter()
            .copied()
            .find(|ty| words.get(idx).map(String::as_str) == Some(*ty))?;
        let next_is = |word: &str| words.get(idx + 1).map(String::as_str) == Some(word);
        // A `MATERIALIZED VIEW LOG` is a distinct object with its own `ON <table>`
        // grammar (handled by the statement-structural candidates), so it is not a
        // completed materialized view here.
        if ty == "MATERIALIZED"
            && next_is("VIEW")
            && words.get(idx + 2).map(String::as_str) == Some("LOG")
        {
            return None;
        }
        let (canonical, phrase_end) = match ty {
            "MATERIALIZED" if next_is("VIEW") => ("MATERIALIZED VIEW", idx + 2),
            "PACKAGE" if next_is("BODY") => ("PACKAGE BODY", idx + 2),
            "TYPE" if next_is("BODY") => ("TYPE BODY", idx + 2),
            "DATABASE" if next_is("LINK") => ("DATABASE LINK", idx + 2),
            "ROLLBACK" if next_is("SEGMENT") => ("ROLLBACK SEGMENT", idx + 2),
            "JAVA" if next_is("SOURCE") => ("JAVA SOURCE", idx + 2),
            "JAVA" if next_is("CLASS") => ("JAVA CLASS", idx + 2),
            "JAVA" if next_is("RESOURCE") => ("JAVA RESOURCE", idx + 2),
            other => (other, idx + 1),
        };
        Some((canonical, words.len().saturating_sub(phrase_end)))
    }

    /// Whether a balanced parenthesised group has already been opened and closed
    /// at the top level before `end` (e.g. the column-definition list of a
    /// `CREATE TABLE`/`CREATE INDEX` has been completed).
    fn has_closed_top_level_paren(tokens: &[SqlToken], end: usize) -> bool {
        let mut depth: i32 = 0;
        for token in tokens.get(..end).unwrap_or(tokens) {
            if let SqlToken::Symbol(sym) = token {
                if sym == "(" {
                    depth += 1;
                } else if sym == ")" {
                    depth -= 1;
                    if depth <= 0 {
                        return true;
                    }
                }
            }
        }
        false
    }

    /// `DROP <object> <name> [options] |` — past the written object name a bare
    /// relation is no longer grammatical, so every recognised single-object drop
    /// returns a handled set (the object-specific options where unambiguous, an
    /// empty set otherwise) to suppress the catalog. `DROP TABLE …` physical
    /// options (CASCADE/PURGE) are produced by the caller's dedicated arms; the
    /// object-name slot itself (no name yet) returns `None` so objects stay
    /// available.
    fn expected_drop_object_tail_keywords(words: &[String]) -> Option<&'static [&'static str]> {
        if words.first().map(String::as_str) != Some("DROP") {
            return None;
        }
        let (ty, words_after_type) = Self::leading_ddl_object_type(words)?;
        if words_after_type == 0 {
            return None;
        }
        let has = |keyword: &str| words.iter().any(|word| word == keyword);
        Some(match ty {
            // `DROP TABLE [schema.]t [CASCADE [CONSTRAINTS]] [PURGE]`. Detected by
            // keyword presence (not position) so a schema-qualified name does not
            // shift the match, and the options are single-use.
            "TABLE" if has("PURGE") || has("CONSTRAINTS") => &[],
            "TABLE" if has("CASCADE") => &["CONSTRAINTS"],
            "TABLE" => &["CASCADE", "PURGE"],
            "USER" => &["CASCADE"],
            "TYPE" => &["FORCE", "VALIDATE"],
            "TABLESPACE" => &["INCLUDING CONTENTS", "CASCADE CONSTRAINTS"],
            "MATERIALIZED VIEW" => &["PRESERVE TABLE"],
            _ => &[],
        })
    }

    /// `CREATE <object> <name> … |` past the object name. The closed-definition
    /// tail of a `TABLE`/`INDEX` (column list balanced) offers the physical/storage
    /// options at the boundary and suppresses the catalog deeper in the region; a
    /// `VIEW` awaits its `AS`; the named-object option grammars we do not fully
    /// model (`USER`/`ROLE`/`TABLESPACE`/`PROFILE`/`DIRECTORY`) offer their first
    /// keyword and otherwise suppress. A `SELECT` marks a CTAS defining query whose
    /// column/relation slots belong to the query grammar, so it is excluded.
    fn expected_create_object_tail_keywords(
        words: &[String],
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<&'static [&'static str]> {
        if words.first().map(String::as_str) != Some("CREATE") {
            return None;
        }
        if Self::unclosed_paren_count(tokens, end) != 0 {
            return None; // inside the definition list: the column-def grammar runs
        }
        let (ty, words_after_type) = Self::leading_ddl_object_type(words)?;
        if words_after_type == 0 {
            return None; // object-name slot
        }
        if words.iter().any(|word| word == "SELECT") {
            return None; // CTAS defining query
        }
        let has_as = words.iter().any(|word| word == "AS");
        let closed_paren = Self::has_closed_top_level_paren(tokens, end);
        let toks = Self::meaningful_tokens_before(tokens, end);
        let last_is_close_paren = matches!(toks.last(), Some(SqlToken::Symbol(sym)) if sym == ")");

        match ty {
            "TABLE" if !has_as => Some(if last_is_close_paren {
                &[
                    "TABLESPACE",
                    "PCTFREE",
                    "STORAGE",
                    "LOGGING",
                    "NOLOGGING",
                    "COMPRESS",
                    "NOCOMPRESS",
                    "CACHE",
                    "NOCACHE",
                    "PARALLEL",
                    "NOPARALLEL",
                    "ORGANIZATION",
                    "PARTITION BY",
                    "ENABLE",
                    "DISABLE",
                ]
            } else if closed_paren {
                &[] // deeper in the physical-attributes region
            } else {
                &["AS", "OF"] // pre-definition slot (`CREATE TABLE t |`)
            }),
            "INDEX" if words.iter().any(|word| word == "ON") => {
                if last_is_close_paren {
                    Some(&[
                        "TABLESPACE",
                        "PCTFREE",
                        "STORAGE",
                        "LOGGING",
                        "NOLOGGING",
                        "COMPRESS",
                        "NOCOMPRESS",
                        "PARALLEL",
                        "NOPARALLEL",
                        "ONLINE",
                        "REVERSE",
                        "LOCAL",
                        "GLOBAL",
                    ])
                } else if closed_paren {
                    Some(&[])
                } else {
                    None // `CREATE INDEX i ON t |` still names columns/`(`
                }
            }
            "VIEW" => (!has_as).then_some(&["AS"][..]),
            "MATERIALIZED VIEW" => Self::expected_create_materialized_view_tail_keywords(words),
            // `CREATE SYNONYM s |` → `FOR` (the statement-structural candidates);
            // once `FOR <target>` is written the synonym is complete. The target
            // slot itself (`… FOR |`) keeps the catalog available.
            "SYNONYM" => (words.iter().any(|word| word == "FOR")
                && words.last().map(String::as_str) != Some("FOR"))
            .then_some(&[][..]),
            "DATABASE LINK" => Self::expected_create_database_link_tail_keywords(words),
            "LIBRARY" if words_after_type == 1 => Some(&["AS"]),
            "LIBRARY" => Some(&[]),
            "JAVA SOURCE" | "JAVA CLASS" | "JAVA RESOURCE" => {
                Self::expected_create_java_object_tail_keywords(words)
            }
            "CONTEXT" => Self::expected_create_context_tail_keywords(words),
            "DIMENSION" => Self::expected_create_dimension_tail_keywords(words),
            "OPERATOR" => Self::expected_create_operator_tail_keywords(words),
            "INDEXTYPE" => Self::expected_create_indextype_tail_keywords(words),
            "EDITION" => Self::expected_create_edition_tail_keywords(words),
            "USER" => Self::expected_oracle_user_tail_keywords(words, tokens, end, false),
            "ROLE" => Self::expected_oracle_role_tail_keywords(words, tokens, end),
            "TABLESPACE" => {
                Self::expected_oracle_create_tablespace_tail_keywords(words, tokens, end)
            }
            "PROFILE" => Self::expected_oracle_profile_tail_keywords(words),
            "ROLLBACK SEGMENT" if words_after_type == 1 => Some(&["TABLESPACE", "STORAGE"]),
            "ROLLBACK SEGMENT" => Some(&[]),
            "DIRECTORY" if words_after_type == 1 => Some(&["AS"]),
            "DIRECTORY" | "CLUSTER" => Some(&[]),
            _ => None,
        }
    }

