    fn object_tail_items_after_type_with_values(
        words: &[String],
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<Vec<String>> {
        let (ty, words_after_type) = Self::leading_ddl_object_type(words)?;
        if words_after_type == 0 {
            return None;
        }

        let mut seen_type = false;
        let mut skip_next_type_word = false;
        let mut tail = Vec::new();
        for token in Self::meaningful_tokens_before(tokens, end) {
            match token {
                SqlToken::Word(word) => {
                    let upper = word.to_ascii_uppercase();
                    if skip_next_type_word {
                        skip_next_type_word = false;
                        continue;
                    }
                    if !seen_type {
                        let starts_type = match ty {
                            "MATERIALIZED VIEW" => {
                                if upper == "MATERIALIZED" {
                                    skip_next_type_word = true;
                                    true
                                } else {
                                    false
                                }
                            }
                            "PACKAGE BODY" | "TYPE BODY" => {
                                if upper == ty.split_whitespace().next().unwrap_or(ty) {
                                    skip_next_type_word = true;
                                    true
                                } else {
                                    false
                                }
                            }
                            "DATABASE LINK" => {
                                if upper == "DATABASE" {
                                    skip_next_type_word = true;
                                    true
                                } else {
                                    false
                                }
                            }
                            "JAVA SOURCE" | "JAVA CLASS" | "JAVA RESOURCE" => {
                                if upper == "JAVA" {
                                    skip_next_type_word = true;
                                    true
                                } else {
                                    false
                                }
                            }
                            _ => upper == ty,
                        };
                        if starts_type {
                            seen_type = true;
                        }
                        continue;
                    }
                    tail.push(upper);
                }
                SqlToken::String(_) => tail.push("__VALUE__".to_string()),
                SqlToken::Symbol(symbol) if symbol == "." => tail.push(symbol.clone()),
                SqlToken::Symbol(_) | SqlToken::Comment(_) => {}
            }
        }

        if tail.is_empty() {
            None
        } else {
            Some(tail)
        }
    }

    fn expected_oracle_user_tail_keywords(
        words: &[String],
        tokens: &[SqlToken],
        end: usize,
        alter: bool,
    ) -> Option<&'static [&'static str]> {
        let tail = Self::object_tail_items_after_type_with_values(words, tokens, end)?;
        let options = Self::oracle_user_option_keywords(alter);
        let tail_refs = tail.iter().map(String::as_str).collect::<Vec<_>>();
        match tail_refs.as_slice() {
            [_name] => Some(options),
            [.., "IDENTIFIED"] => Some(&["BY", "EXTERNALLY", "GLOBALLY"]),
            [.., "IDENTIFIED", "BY"] => Some(&[]),
            [.., "IDENTIFIED", "BY", _value] => Some(options),
            [.., "IDENTIFIED", "EXTERNALLY"] | [.., "IDENTIFIED", "GLOBALLY"] => Some(&["AS"]),
            [.., "IDENTIFIED", "EXTERNALLY", "AS"] | [.., "IDENTIFIED", "GLOBALLY", "AS"] => {
                Some(&[])
            }
            [.., "IDENTIFIED", "EXTERNALLY", "AS", _value]
            | [.., "IDENTIFIED", "GLOBALLY", "AS", _value] => Some(options),
            [.., "DEFAULT"] => {
                if alter {
                    Some(&["TABLESPACE", "ROLE"])
                } else {
                    Some(&["TABLESPACE"])
                }
            }
            [.., "DEFAULT", "TABLESPACE"] | [.., "TEMPORARY", "TABLESPACE"] => Some(&[]),
            [.., "DEFAULT", "TABLESPACE", _value] | [.., "TEMPORARY", "TABLESPACE", _value] => {
                Some(options)
            }
            [.., "TEMPORARY"] => Some(&["TABLESPACE"]),
            [.., "QUOTA"] => Some(&["UNLIMITED"]),
            [.., "QUOTA", _amount] => Some(&["ON"]),
            [.., "QUOTA", _amount, "ON"] => Some(&[]),
            [.., "QUOTA", _amount, "ON", _tablespace] => Some(options),
            [.., "PROFILE"] => Some(&[]),
            [.., "PROFILE", _profile] => Some(options),
            [.., "PASSWORD"] => Some(&["EXPIRE"]),
            [.., "PASSWORD", "EXPIRE"] => Some(options),
            [.., "ACCOUNT"] => Some(&["LOCK", "UNLOCK"]),
            [.., "ACCOUNT", "LOCK" | "UNLOCK"] => Some(options),
            [.., "DEFAULT", "ROLE"] if alter => Some(&["ALL", "NONE"]),
            [.., "DEFAULT", "ROLE", _role] if alter => Some(options),
            _ => Some(&[]),
        }
    }

    fn drop_present_oracle_user_options(
        candidates: Vec<String>,
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Vec<String> {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type) || candidates.is_empty() {
            return candidates;
        }

        let words = Self::meaningful_tokens_before(tokens, end)
            .into_iter()
            .filter_map(|token| match token {
                SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
                SqlToken::String(_) => Some("__VALUE__".to_string()),
                SqlToken::Symbol(symbol) if symbol == "." => Some(symbol.clone()),
                SqlToken::Symbol(_) | SqlToken::Comment(_) => None,
            })
            .collect::<Vec<_>>();
        if !matches!(words.first().map(String::as_str), Some("CREATE" | "ALTER")) {
            return candidates;
        }
        let Some((ty, words_after_type)) = Self::leading_ddl_object_type(&words) else {
            return candidates;
        };
        if ty != "USER" || words_after_type == 0 {
            return candidates;
        }
        let tail_start = words.len().saturating_sub(words_after_type);
        let tail = &words[tail_start..];
        let completed = |option: &str| {
            match option {
            "IDENTIFIED" => tail.windows(3).any(
                |window| matches!(window, [identified, by, _value] if identified == "IDENTIFIED" && by == "BY"),
            ) || tail.windows(4).any(|window| {
                matches!(
                    window,
                    [identified, mode, as_kw, _value]
                        if identified == "IDENTIFIED"
                            && matches!(mode.as_str(), "EXTERNALLY" | "GLOBALLY")
                            && as_kw == "AS"
                )
            }),
            "DEFAULT TABLESPACE" => tail.windows(3).any(
                |window| matches!(window, [default, tablespace, _value] if default == "DEFAULT" && tablespace == "TABLESPACE"),
            ),
            "TEMPORARY TABLESPACE" => tail.windows(3).any(
                |window| matches!(window, [temporary, tablespace, _value] if temporary == "TEMPORARY" && tablespace == "TABLESPACE"),
            ),
            "PROFILE" => tail
                .windows(2)
                .any(|window| matches!(window, [profile, _value] if profile == "PROFILE")),
            "PASSWORD EXPIRE" => tail
                .windows(2)
                .any(|window| matches!(window, [password, expire] if password == "PASSWORD" && expire == "EXPIRE")),
            "ACCOUNT" => tail.windows(2).any(|window| {
                matches!(window, [account, state] if account == "ACCOUNT" && matches!(state.as_str(), "LOCK" | "UNLOCK"))
            }),
            "DEFAULT ROLE" => tail.windows(3).any(
                |window| matches!(window, [default, role, _value] if default == "DEFAULT" && role == "ROLE"),
            ),
            _ => false,
        }
        };

        candidates
            .into_iter()
            .filter(|candidate| !completed(&candidate.to_ascii_uppercase()))
            .collect()
    }

    fn expected_oracle_role_tail_keywords(
        words: &[String],
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<&'static [&'static str]> {
        let tail = Self::object_tail_items_after_type_with_values(words, tokens, end)?;
        let tail_refs = tail.iter().map(String::as_str).collect::<Vec<_>>();
        match tail_refs.as_slice() {
            [_name] => Some(&["IDENTIFIED", "NOT IDENTIFIED"]),
            [.., "NOT"] => Some(&["IDENTIFIED"]),
            [.., "NOT", "IDENTIFIED"] => Some(&[]),
            [.., "IDENTIFIED"] => Some(&["BY", "USING", "EXTERNALLY", "GLOBALLY"]),
            [.., "IDENTIFIED", "BY"] => Some(&[]),
            [.., "IDENTIFIED", "BY", _value] => Some(&[]),
            [.., "IDENTIFIED", "USING"] => None,
            [.., "IDENTIFIED", "USING", _package] => Some(&[]),
            [.., "IDENTIFIED", "EXTERNALLY"] => Some(&[]),
            [.., "IDENTIFIED", "GLOBALLY"] => Some(&["AS"]),
            [.., "IDENTIFIED", "GLOBALLY", "AS"] => Some(&[]),
            [.., "IDENTIFIED", "GLOBALLY", "AS", _value] => Some(&[]),
            _ => Some(&[]),
        }
    }

    fn expected_oracle_role_package_object_suggestion_kind(
        words: &[String],
    ) -> Option<ExpectedObjectSuggestionKind> {
        let first = words.first().map(String::as_str)?;
        if !matches!(first, "CREATE" | "ALTER") {
            return None;
        }
        let (ty, words_after_type) = Self::leading_ddl_object_type(words)?;
        if ty != "ROLE" {
            return None;
        }
        let tail = words
            .iter()
            .skip(words.len().saturating_sub(words_after_type))
            .map(String::as_str)
            .collect::<Vec<_>>();
        matches!(tail.as_slice(), [_name, "IDENTIFIED", "USING"])
            .then_some(ExpectedObjectSuggestionKind::Package)
    }

    fn expected_oracle_show_errors_object_suggestion_kind(
        words: &[String],
    ) -> Option<ExpectedObjectSuggestionKind> {
        let show_pos = words.iter().rposition(|word| word == "SHOW")?;
        let tail = &words[show_pos + 1..];
        match tail {
            [errors, object_type] if errors == "ERRORS" => match object_type.as_str() {
                "PROCEDURE" => Some(ExpectedObjectSuggestionKind::Procedure),
                "FUNCTION" => Some(ExpectedObjectSuggestionKind::Function),
                "PACKAGE" => Some(ExpectedObjectSuggestionKind::Package),
                "TYPE" => Some(ExpectedObjectSuggestionKind::Type),
                "TRIGGER" => Some(ExpectedObjectSuggestionKind::Trigger),
                "VIEW" => Some(ExpectedObjectSuggestionKind::View),
                _ => None,
            },
            [errors, object_type, body]
                if errors == "ERRORS"
                    && body == "BODY"
                    && matches!(object_type.as_str(), "PACKAGE" | "TYPE") =>
            {
                match object_type.as_str() {
                    "PACKAGE" => Some(ExpectedObjectSuggestionKind::Package),
                    "TYPE" => Some(ExpectedObjectSuggestionKind::Type),
                    _ => None,
                }
            }
            _ => None,
        }
    }

    fn current_identifier_extending_prefix_index(
        tokens: &[SqlToken],
        context_end: usize,
        prefix: &str,
    ) -> Option<usize> {
        if prefix.is_empty() {
            return None;
        }
        let extends_prefix = |token: Option<&SqlToken>| {
            let Some(SqlToken::Word(word)) = token else {
                return false;
            };
            word.len() > prefix.len()
                && !Self::token_is_language_keyword(&word.to_ascii_uppercase())
                && word
                    .get(..prefix.len())
                    .is_some_and(|head| head.eq_ignore_ascii_case(prefix))
        };
        [
            context_end.checked_sub(1),
            Some(context_end),
            context_end.checked_add(1),
            context_end.checked_add(2),
        ]
        .into_iter()
        .flatten()
        .find(|idx| extends_prefix(tokens.get(*idx)))
    }

