    fn expected_create_database_link_tail_keywords(
        words: &[String],
    ) -> Option<&'static [&'static str]> {
        let (_, words_after_type) = Self::leading_ddl_object_type(words)?;
        if words_after_type == 0 {
            return None;
        }
        let tail = words
            .iter()
            .skip(words.len().saturating_sub(words_after_type))
            .map(String::as_str)
            .collect::<Vec<_>>();
        match tail.as_slice() {
            [_name] => Some(&["CONNECT TO", "AUTHENTICATED BY", "USING"]),
            [.., "CONNECT"] => Some(&["TO"]),
            [.., "AUTHENTICATED"] => Some(&["BY"]),
            [.., "CONNECT", "TO", _user] | [.., "AUTHENTICATED", "BY", _user] => {
                Some(&["IDENTIFIED BY"])
            }
            [.., "IDENTIFIED"] => Some(&["BY"]),
            // Passwords and connect strings are literal values; once the cursor
            // reaches those slots (or the text after them), no schema object is
            // grammatical.
            [.., "BY"] | [.., "USING"] => Some(&[]),
            _ => {
                let has_using = tail.contains(&"USING");
                if has_using {
                    return Some(&[]);
                }
                let credential_completed = tail.windows(3).any(|window| {
                    matches!(window, ["IDENTIFIED", "BY", value] if !matches!(*value, "__VALUE__"))
                });
                if credential_completed {
                    if tail.contains(&"AUTHENTICATED") {
                        Some(&["USING"])
                    } else {
                        Some(&["AUTHENTICATED BY", "USING"])
                    }
                } else {
                    Some(&[])
                }
            }
        }
    }

    /// `ALTER <object> <name> … |` past the object name. `ALTER TABLE` keeps its
    /// dedicated `ADD/DROP/MODIFY/RENAME` arm (excluded here); the other alterable
    /// objects offer their primary action keywords at the immediate post-name slot
    /// and otherwise suppress the catalog (a bare relation is never grammatical in
    /// an `ALTER` body). The object-name slot itself returns `None` so the catalog
    /// stays available there.
    fn expected_alter_object_tail_keywords(
        words: &[String],
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<&'static [&'static str]> {
        if words.first().map(String::as_str) != Some("ALTER") {
            return None;
        }
        let (ty, words_after_type) = Self::leading_ddl_object_type(words)?;
        if words_after_type == 0 {
            return None;
        }
        match ty {
            "TABLE" => None, // dedicated ADD/DROP/MODIFY/RENAME arm
            "INDEX" if words_after_type == 1 => Some(&[
                "REBUILD",
                "RENAME",
                "COALESCE",
                "MODIFY",
                "MONITORING",
                "NOMONITORING",
                "UNUSABLE",
                "ENABLE",
                "DISABLE",
                "PARAMETERS",
            ]),
            "SEQUENCE" if words_after_type == 1 => Some(ORACLE_SEQUENCE_OPTION_KEYWORDS),
            "USER" => Self::expected_oracle_user_tail_keywords(words, tokens, end, true),
            "VIEW" if words_after_type == 1 => {
                Some(&["COMPILE", "READ", "ENABLE", "DISABLE", "MODIFY", "ADD"])
            }
            "MATERIALIZED VIEW" if words_after_type == 1 => Some(&[
                "COMPILE", "REFRESH", "REBUILD", "ENABLE", "DISABLE", "MODIFY",
            ]),
            "LIBRARY" | "DIMENSION" | "OPERATOR" | "INDEXTYPE" | "JAVA SOURCE" | "JAVA CLASS"
                if words_after_type == 1 =>
            {
                Some(&["COMPILE"])
            }
            "EDITION" if words_after_type == 1 => Some(&["USABLE", "UNUSABLE"]),
            "ROLLBACK SEGMENT" if words_after_type == 1 => Some(&["ONLINE", "OFFLINE", "SHRINK"]),
            "TYPE" if words_after_type == 1 => Some(&[
                "COMPILE",
                "ADD ATTRIBUTE",
                "ADD MEMBER",
                "ADD STATIC",
                "ADD MAP MEMBER",
                "ADD ORDER MEMBER",
                "ADD CONSTRUCTOR",
                "MODIFY ATTRIBUTE",
                "DROP ATTRIBUTE",
                "DROP MEMBER",
            ]),
            "TYPE" => Self::expected_alter_type_tail_keywords(words),
            "TYPE BODY" if words_after_type == 1 => Some(&["COMPILE"]),
            "PROCEDURE" | "FUNCTION" | "PACKAGE" | "PACKAGE BODY" | "TRIGGER"
                if words_after_type == 1 =>
            {
                Some(&["COMPILE", "ENABLE", "DISABLE"])
            }
            // Deeper option regions and the remaining alterable objects: suppress
            // the catalog without guessing the (large) option grammar.
            "INDEX" | "SEQUENCE" | "VIEW" | "MATERIALIZED VIEW" | "PROCEDURE" | "FUNCTION"
            | "PACKAGE" | "PACKAGE BODY" | "TRIGGER" | "TYPE BODY" | "DATABASE LINK"
            | "LIBRARY" | "CLUSTER" | "DIMENSION" | "OPERATOR" | "INDEXTYPE" | "EDITION"
            | "ROLLBACK SEGMENT" | "JAVA SOURCE" | "JAVA CLASS" => Some(&[]),
            "TABLESPACE" => {
                Self::expected_oracle_alter_tablespace_tail_keywords(words, tokens, end)
            }
            "ROLE" => Self::expected_oracle_role_tail_keywords(words, tokens, end),
            "PROFILE" => Self::expected_oracle_profile_tail_keywords(words),
            _ => None,
        }
    }

    fn expected_alter_type_tail_keywords(words: &[String]) -> Option<&'static [&'static str]> {
        let (_, words_after_type) = Self::leading_ddl_object_type(words)?;
        if words_after_type == 0 {
            return None;
        }
        let tail = words
            .iter()
            .skip(words.len().saturating_sub(words_after_type))
            .map(String::as_str)
            .collect::<Vec<_>>();
        match tail.as_slice() {
            [_name, "ADD"] => Some(&[
                "ATTRIBUTE",
                "MEMBER",
                "STATIC",
                "MAP MEMBER",
                "ORDER MEMBER",
                "CONSTRUCTOR",
            ]),
            [_name, "ADD", "MAP"] | [_name, "ADD", "ORDER"] => Some(&["MEMBER"]),
            [_name, "ADD", "MEMBER"] => Some(&["FUNCTION", "PROCEDURE"]),
            [_name, "ADD", "MAP", "MEMBER"] | [_name, "ADD", "ORDER", "MEMBER"] => {
                Some(&["FUNCTION"])
            }
            [_name, "ADD", "STATIC"] => Some(&["FUNCTION", "PROCEDURE"]),
            [_name, "ADD", "CONSTRUCTOR"] => Some(&["FUNCTION"]),
            [_name, "MODIFY"] | [_name, "DROP"] => Some(&["ATTRIBUTE", "MEMBER"]),
            _ => Some(&[]),
        }
    }

    /// Oracle non-query admin/utility statements (`ANALYZE`, `AUDIT`/`NOAUDIT`,
    /// `FLASHBACK`, `PURGE`, `CALL`). Once the object name is written a bare
    /// relation is no longer grammatical, so these suppress the catalog (offering
    /// the real continuation keywords where unambiguous). The object/identifier
    /// slots (`ANALYZE TABLE |`, `AUDIT … ON |`, `CALL |`/inside its argument list)
    /// return `None` and keep the catalog available.
    fn expected_oracle_admin_statement_tail_keywords(
        words: &[String],
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<&'static [&'static str]> {
        let first = words.first().map(String::as_str)?;
        let last = words.last().map(String::as_str);
        let has = |keyword: &str| words.iter().any(|word| word == keyword);
        match first {
            // `ANALYZE {TABLE|INDEX|CLUSTER} <name> |` → the analysis operations.
            "ANALYZE" if has("TABLE") || has("INDEX") || has("CLUSTER") => {
                if matches!(last, Some("TABLE" | "INDEX" | "CLUSTER")) {
                    return None; // object-name slot
                }
                if has("STATISTICS") || has("STRUCTURE") || has("ROWS") {
                    return Some(&[]); // operation chosen / complete
                }
                Some(&[
                    "COMPUTE STATISTICS",
                    "ESTIMATE STATISTICS",
                    "VALIDATE STRUCTURE",
                    "DELETE STATISTICS",
                    "LIST CHAINED ROWS",
                ])
            }
            // `AUDIT <privileges> [ON <obj>] [BY <user>|BY {ACCESS|SESSION}]
            // [WHENEVER …]`. The `ON` object slot and non-object `BY <user>` slot
            // keep their typed catalogs; the object-audit `BY` slot takes mode
            // keywords. Everywhere else only clause keywords are grammatical
            // (never the select-list `FROM`).
            "AUDIT" | "NOAUDIT" => match last {
                Some("ON") => None,
                Some("BY") if has("ON") => Some(&["ACCESS", "SESSION"]),
                Some("BY") => None,
                Some("WHENEVER") => Some(&["SUCCESSFUL", "NOT"]),
                Some("NOT") if has("WHENEVER") => Some(&["SUCCESSFUL"]),
                _ => Some(match (has("ON"), has("BY"), has("WHENEVER")) {
                    (false, false, false) => &["ON", "BY", "WHENEVER"],
                    (true, false, false) => &["BY", "WHENEVER"],
                    (_, true, false) => &["WHENEVER"],
                    _ => &[],
                }),
            },
            // `FLASHBACK TABLE <table> TO …` names a table only at the table slot.
            // `FLASHBACK DATABASE TO …` has no schema-object slot after DATABASE.
            "FLASHBACK" => {
                let word_refs = words.iter().map(String::as_str).collect::<Vec<_>>();
                match word_refs.as_slice() {
                    ["FLASHBACK"] => None,
                    ["FLASHBACK", "TABLE"] => None,
                    ["FLASHBACK", "TABLE", ..]
                        if !word_refs
                            .iter()
                            .skip(2)
                            .any(|word| matches!(*word, "TO" | "BEFORE" | "SCN" | "TIMESTAMP")) =>
                    {
                        Some(&[
                            "TO BEFORE DROP",
                            "TO SCN",
                            "TO TIMESTAMP",
                            "TO RESTORE POINT",
                        ])
                    }
                    ["FLASHBACK", "DATABASE"] => Some(&["TO"]),
                    ["FLASHBACK", "DATABASE", "TO"] => Some(&["SCN", "TIMESTAMP", "RESTORE POINT"]),
                    [.., "BEFORE", "DROP", "RENAME", "TO"] => Some(&[]),
                    [.., "TO"] => Some(&["BEFORE DROP", "SCN", "TIMESTAMP", "RESTORE POINT"]),
                    [.., "BEFORE"] => Some(&["DROP"]),
                    [.., "BEFORE", "DROP"] => Some(&["RENAME TO"]),
                    _ => Some(&[]),
                }
            }
            // `PURGE {TABLE|INDEX} <name>` / `PURGE RECYCLEBIN` — complete once the
            // object name is written.
            "PURGE" => {
                if matches!(last, Some("PURGE" | "TABLE" | "INDEX")) {
                    return None; // object-name slot
                }
                Some(&[])
            }
            // `CALL proc[(args)] [INTO :host] |` — a complete call; the procedure
            // name slot and the argument list keep the catalog available.
            "CALL" => {
                if words.len() <= 1 || Self::unclosed_paren_count(tokens, end) != 0 {
                    return None;
                }
                Some(&[])
            }
            // `ASSOCIATE STATISTICS WITH <objects> |` → `USING`; `DISASSOCIATE
            // STATISTICS FROM <objects> |` → complete. The object-kind keyword and
            // the comma-separated object list keep the catalog available.
            "ASSOCIATE" | "DISASSOCIATE" if has("STATISTICS") => {
                let last_is_comma = matches!(
                    Self::meaningful_tokens_before(tokens, end).last(),
                    Some(SqlToken::Symbol(sym)) if sym == ","
                );
                if last_is_comma
                    || matches!(
                        last,
                        Some(
                            "WITH"
                                | "FROM"
                                | "COLUMNS"
                                | "FUNCTIONS"
                                | "PACKAGES"
                                | "TYPES"
                                | "INDEXES"
                                | "INDEXTYPES"
                        )
                    )
                {
                    return None;
                }
                Some(if first == "ASSOCIATE" {
                    &["USING"]
                } else {
                    &[]
                })
            }
            _ => None,
        }
    }

    fn expected_statement_tail_keyword_candidates(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<&'static [&'static str]> {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return None;
        }

        let toks = Self::meaningful_tokens_before(tokens, end);
        let words = toks
            .iter()
            .filter_map(|token| match token {
                SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
                _ => None,
            })
            .collect::<Vec<_>>();

        let position_after = |keyword: &str| {
            words
                .iter()
                .rposition(|word| word == keyword)
                .map(|idx| words.len().saturating_sub(idx + 1))
        };

        match words.as_slice() {
            [comment, on] if comment == "COMMENT" && on == "ON" => {
                return Some(&[
                    "COLUMN",
                    "TABLE",
                    "VIEW",
                    "MATERIALIZED",
                    "EDITION",
                    "EDITIONING",
                    "MINING",
                    "OPERATOR",
                    "INDEXTYPE",
                ]);
            }
            // `COMMENT ON <object-type> <name> |` → `IS` (the comment text). While the
            // object *kind*/name is still being chosen the name follows (a relation/
            // column — keep it available, `None`); past the name `IS` introduces the
            // literal, and once `IS` is present nothing more is offered here.
            [comment, on, rest @ ..] if comment == "COMMENT" && on == "ON" && !rest.is_empty() => {
                if rest.iter().any(|word| word == "IS") {
                    // The comment text is a string literal — never a relation — so
                    // suppress the catalog rather than leaving the slot open.
                    return Some(&[]);
                }
                match rest.last().map(String::as_str) {
                    Some("MATERIALIZED") => return Some(&["VIEW"]),
                    Some("MINING") => return Some(&["MODEL"]),
                    Some(
                        "TABLE" | "COLUMN" | "VIEW" | "EDITION" | "EDITIONING" | "OPERATOR"
                        | "INDEXTYPE" | "MODEL",
                    ) => return None,
                    Some(_) => return Some(&["IS"]),
                    None => {}
                }
            }
            [alter, session] if alter == "ALTER" && session == "SESSION" => return Some(&["SET"]),
            [truncate] if truncate == "TRUNCATE" => return Some(&["TABLE"]),
            [.., truncate, table, _name] if truncate == "TRUNCATE" && table == "TABLE" => {
                return Some(&["DROP STORAGE", "REUSE STORAGE", "CASCADE"])
            }
            [.., truncate, table, _name, drop_or_reuse]
                if truncate == "TRUNCATE"
                    && table == "TABLE"
                    && matches!(drop_or_reuse.as_str(), "DROP" | "REUSE") =>
            {
                return Some(&["STORAGE"])
            }
            [.., drop, table, _name] if drop == "DROP" && table == "TABLE" => {
                return Some(&["CASCADE", "PURGE"])
            }
            [.., drop, table, _name, cascade]
                if drop == "DROP" && table == "TABLE" && cascade == "CASCADE" =>
            {
                return Some(&["CONSTRAINTS"])
            }
            _ => {}
        }

        if words.first().is_some_and(|word| word == "CREATE") {
            // Every `CREATE SEQUENCE …` option position (the option-list start, the
            // boundaries, the partial sub-keyword steps and the value slots) is
            // handled by `expected_create_sequence_option_keywords`, which runs
            // earlier in the chain and prunes already-present single-use options.
            if position_after("INDEX") == Some(1) {
                return Some(&["ON"]);
            }
            // `CREATE [OR REPLACE] [FORCE] VIEW v |` → `AS` (the defining query). A
            // materialized view has its own option grammar (BUILD/REFRESH/…), so it
            // is excluded here.
            if !words.iter().any(|word| word == "MATERIALIZED") && position_after("VIEW") == Some(1)
            {
                return Some(&["AS"]);
            }
            if position_after("SYNONYM") == Some(1) {
                return Some(&["FOR"]);
            }
            // `CREATE [OR REPLACE] TYPE ty AS |` → the type-spec kind. The downstream
            // grammars already complete from there (`AS TABLE OF |`→types, `AS OBJECT
            // (attrs)`/`AS VARRAY(n) OF |`→types, `AS REF CURSOR [RETURN …]`). A TYPE
            // *body* (`TYPE BODY ty AS |`) is the method-implementation grammar, so
            // it is excluded.
            if words.iter().any(|word| word == "TYPE")
                && !words.iter().any(|word| word == "BODY")
                && (position_after("AS") == Some(0) || position_after("IS") == Some(0))
            {
                return Some(&["OBJECT", "TABLE OF", "VARRAY", "REF CURSOR"]);
            }
            // `CREATE [OR REPLACE] TYPE ty IS/AS REF |` → `CURSOR`. Anchored on `REF`
            // directly following the spec-kind `IS`/`AS` (not, say, an object
            // attribute's `REF <other_type>`, which follows a column name/`OF`
            // instead) and outside the attribute-list parens.
            if words.iter().any(|word| word == "TYPE")
                && !words.iter().any(|word| word == "BODY")
                && Self::unclosed_paren_count(tokens, end) == 0
                && matches!(
                    words.as_slice(),
                    [.., is_or_as, ref_word]
                        if matches!(is_or_as.as_str(), "IS" | "AS") && ref_word == "REF"
                )
            {
                return Some(&["CURSOR"]);
            }
        }

        // Past the object name of a single-object `DROP`/`CREATE`, a bare relation
        // is no longer grammatical. These helpers identify the *leading* object
        // type (so a later option keyword like the `TABLESPACE` of `CREATE TABLE …
        // TABLESPACE` is never mistaken for the type) and return a handled set —
        // the real option keywords where the grammar is unambiguous, otherwise an
        // empty set — so the catalog is suppressed at the tail. The object-name
        // slot itself (`DROP VIEW |`) and the defining-query/relation slots
        // (`CREATE SYNONYM s FOR |`, `… AS SELECT … FROM |`) return `None` and keep
        // the catalog available.
        if let Some(candidates) = Self::expected_drop_object_tail_keywords(&words) {
            return Some(candidates);
        }
        if let Some(candidates) = Self::expected_create_object_tail_keywords(&words, tokens, end) {
            return Some(candidates);
        }
        if let Some(candidates) = Self::expected_alter_object_tail_keywords(&words, tokens, end) {
            return Some(candidates);
        }
        if let Some(candidates) =
            Self::expected_oracle_admin_statement_tail_keywords(&words, tokens, end)
        {
            return Some(candidates);
        }
        if let Some(candidates) = Self::expected_alter_table_tail_keywords(&words) {
            return Some(candidates);
        }
        // Option keywords that take a name from a catalog we do not model (a
        // tablespace) are followed by an identifier slot, never a relation; in a
        // `CREATE`/`ALTER` statement suppress the catalog there.
        if matches!(words.first().map(String::as_str), Some("CREATE" | "ALTER"))
            && Self::unclosed_paren_count(tokens, end) == 0
            && words.last().map(String::as_str) == Some("TABLESPACE")
        {
            return Some(&[]);
        }

        None
    }

    fn expected_alter_table_tail_keywords(words: &[String]) -> Option<&'static [&'static str]> {
        if !matches!(
            words,
            [alter, table, ..] if alter == "ALTER" && table == "TABLE"
        ) {
            return None;
        }
        let tail = words.get(2..)?;
        if tail.is_empty() {
            return None;
        }

        match tail.last().map(String::as_str) {
            Some("DROP") => Some(&["COLUMN", "CONSTRAINT", "PRIMARY KEY", "UNIQUE", "PARTITION"]),
            Some("RENAME") => Some(&["TO", "COLUMN", "CONSTRAINT", "PARTITION"]),
            _ if !tail
                .iter()
                .any(|word| matches!(word.as_str(), "ADD" | "DROP" | "MODIFY" | "RENAME")) =>
            {
                Some(&["ADD", "DROP", "MODIFY", "RENAME"])
            }
            _ => None,
        }
    }

    fn expected_transaction_and_dcl_keyword_candidates(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<&'static [&'static str]> {
        if Self::unclosed_paren_count(tokens, end) != 0 {
            return None;
        }

        let mysql = crate::sql_text::mysql_compatibility_for_sql("", db_type);
        // Inside a PL/SQL block every arm below anchors on the statement's
        // *leading* verb, which the block prefix (`BEGIN …;`) hides — rescope to
        // the statement containing the cursor (`BEGIN SAVEPOINT sp; ROLLBACK TO |`
        // → `[ROLLBACK, TO]`) and rerun. The rescoped slice contains no further
        // depth-0 boundary before the cursor, so the recursion takes this branch
        // at most once.
        if !mysql && Self::cursor_in_plsql_executable_block(tokens, end) {
            let start = Self::plsql_statement_slot_start(tokens, end);
            if start > 0 {
                let scoped = tokens.get(start..)?;
                return Self::expected_transaction_and_dcl_keyword_candidates(
                    scoped,
                    end.checked_sub(start)?,
                    db_type,
                );
            }
        }
        let toks = Self::meaningful_tokens_before(tokens, end);
        let visible_words = toks
            .iter()
            .filter_map(|token| match token {
                SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
                _ => None,
            })
            .collect::<Vec<_>>();
        let full_words = tokens
            .iter()
            .filter_map(|token| match token {
                SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
                _ => None,
            })
            .collect::<Vec<_>>();
        let words = if visible_words.is_empty()
            || (matches!(visible_words.as_slice(), [set] if set == "SET")
                && matches!(full_words.as_slice(), [set, transaction, ..] if set == "SET" && transaction == "TRANSACTION"))
        {
            full_words
        } else {
            visible_words
        };
        let current_word = tokens.get(end).and_then(|token| match token {
            SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
            _ => None,
        });
        let contains = |keyword: &str| words.iter().any(|word| word == keyword);
        let lock_statement = words.first().is_some_and(|word| word == "LOCK");
        let first_index = |keyword: &str| words.iter().position(|word| word == keyword);
        let last_index = |keyword: &str| words.iter().rposition(|word| word == keyword);
        let object_grant_on = || {
            let Some(on_idx) = first_index("ON") else {
                return false;
            };
            let boundary = first_index("TO")
                .or_else(|| first_index("FROM"))
                .unwrap_or(words.len());
            on_idx < boundary
        };
        let option_with_present = || {
            let Some(with_idx) = last_index("WITH") else {
                return false;
            };
            let Some(grantee_boundary) = first_index("TO").or_else(|| first_index("FROM")) else {
                return false;
            };
            if with_idx <= grantee_boundary {
                return false;
            }
            let prev = with_idx.checked_sub(1).and_then(|idx| words.get(idx));
            !prev.is_some_and(|word| word == "TO" || word == "FROM")
        };
        const ORACLE_SET_HEAD_KEYWORDS: &[&str] = &[
            "TRANSACTION",
            "AUTOCOMMIT",
            "COLSEP",
            "DEFINE",
            "ECHO",
            "ERRORCONTINUE",
            "FEEDBACK",
            "HEADING",
            "LINESIZE",
            "NULL",
            "PAGESIZE",
            "SCAN",
            "SERVEROUTPUT",
            "SQLBLANKLINES",
            "TAB",
            "TERMOUT",
            "TIMING",
            "TRIMOUT",
            "TRIMSPOOL",
            "VERIFY",
        ];

        if !mysql
            && matches!(words.as_slice(), [set] if set == "SET")
            && !matches!(current_word.as_deref(), Some("TRANSACTION"))
        {
            return Some(ORACLE_SET_HEAD_KEYWORDS);
        }
        if matches!(
            (words.as_slice(), current_word.as_deref()),
            ([set], Some("TRANSACTION")) if set == "SET"
        ) {
            return if mysql {
                Some(&["ISOLATION", "READ"])
            } else {
                Some(&["READ", "ISOLATION", "USE", "NAME"])
            };
        }
        if !mysql
            && matches!(words.as_slice(), [set, transaction, use_word] if set == "SET" && transaction == "TRANSACTION" && use_word == "USE")
        {
            return Some(&["ROLLBACK"]);
        }
        if !mysql
            && matches!(
            words.as_slice(),
            [set, transaction, use_word, rollback] if set == "SET"
                && transaction == "TRANSACTION"
                && use_word == "USE"
                && rollback == "ROLLBACK"
        )
        {
            return Some(&["SEGMENT"]);
        }
        if mysql {
            const MYSQL_SET_HEAD_KEYWORDS: &[&str] = &[
                "CHARACTER",
                "CHARSET",
                "DEFAULT",
                "GLOBAL",
                "NAMES",
                "PASSWORD",
                "PERSIST",
                "PERSIST_ONLY",
                "RESOURCE",
                "ROLE",
                "SESSION",
                "TRANSACTION",
            ];
            if matches!(words.as_slice(), [set] if set == "SET") {
                return Some(MYSQL_SET_HEAD_KEYWORDS);
            }
            if matches!(words.as_slice(), [set, scope] if set == "SET" && matches!(scope.as_str(), "GLOBAL" | "SESSION"))
            {
                return Some(&["TRANSACTION"]);
            }
            if matches!(
                words.as_slice(),
                [set, scope, transaction] if set == "SET"
                    && matches!(scope.as_str(), "GLOBAL" | "SESSION")
                    && transaction == "TRANSACTION"
            ) {
                return Some(&["ISOLATION", "READ"]);
            }
            if matches!(
                words.as_slice(),
                [set, scope, transaction, read] if set == "SET"
                    && matches!(scope.as_str(), "GLOBAL" | "SESSION")
                    && transaction == "TRANSACTION"
                    && read == "READ"
            ) {
                return Some(&["ONLY", "WRITE"]);
            }
            if matches!(
                words.as_slice(),
                [set, scope, transaction, isolation] if set == "SET"
                    && matches!(scope.as_str(), "GLOBAL" | "SESSION")
                    && transaction == "TRANSACTION"
                    && isolation == "ISOLATION"
            ) {
                return Some(&["LEVEL"]);
            }
            if matches!(
                words.as_slice(),
                [set, scope, transaction, isolation, level] if set == "SET"
                    && matches!(scope.as_str(), "GLOBAL" | "SESSION")
                    && transaction == "TRANSACTION"
                    && isolation == "ISOLATION"
                    && level == "LEVEL"
            ) {
                return Some(&[
                    "SERIALIZABLE",
                    "READ COMMITTED",
                    "READ UNCOMMITTED",
                    "REPEATABLE READ",
                ]);
            }
        }

        if mysql {
            match words.as_slice() {
                [flush, tables, with_kw]
                    if flush == "FLUSH"
                        && matches!(tables.as_str(), "TABLE" | "TABLES")
                        && with_kw == "WITH" =>
                {
                    return Some(&["READ"]);
                }
                [flush, tables, with_kw, read]
                    if flush == "FLUSH"
                        && matches!(tables.as_str(), "TABLE" | "TABLES")
                        && with_kw == "WITH"
                        && read == "READ" =>
                {
                    return Some(&["LOCK"]);
                }
                _ => {}
            }
        }

        if words.first().is_some_and(|word| word == "GRANT")
            && contains("ON")
            && !contains("TO")
            && words.last().is_some_and(|word| word != "ON")
        {
            return Some(&["TO"]);
        }
        if words.first().is_some_and(|word| word == "GRANT") && contains("TO") {
            // The `WITH {GRANT|ADMIN|HIERARCHY} OPTION` clause is single-use: once
            // its terminal `OPTION` is present the grant is complete. Return an empty
            // (handled) set rather than `None` so the privilege `SELECT` in `GRANT
            // SELECT …` cannot fall through and leak the select-list `FROM`.
            if contains("OPTION") {
                return Some(&[]);
            }
            // `WITH <kind> |` → the trailing `OPTION` keyword.
            if matches!(
                words.last().map(String::as_str),
                Some("GRANT") | Some("ADMIN") | Some("HIERARCHY")
            ) && words.iter().rev().nth(1).map(String::as_str) == Some("WITH")
            {
                return Some(&["OPTION"]);
            }
            // Object privileges (`… ON obj …`) end with `WITH GRANT OPTION`; system
            // privileges and roles with `WITH ADMIN OPTION`. Once `WITH` is typed,
            // only the option phrase remains (never the whole `WITH … OPTION`).
            return Some(match (object_grant_on(), option_with_present()) {
                (true, false) => &["WITH GRANT OPTION"],
                (true, true) => &["GRANT OPTION"],
                (false, false) => &["WITH ADMIN OPTION"],
                (false, true) => &["ADMIN OPTION"],
            });
        }
        if words.first().is_some_and(|word| word == "REVOKE")
            && contains("ON")
            && !contains("FROM")
            && words.last().is_some_and(|word| word != "ON")
        {
            return Some(&["FROM"]);
        }
        if words.first().is_some_and(|word| word == "REVOKE") && contains("FROM") {
            return Some(&[]);
        }

        match words.as_slice() {
            [commit] if commit == "COMMIT" && mysql => {
                Some(&["WORK", "AND", "CHAIN", "NO", "RELEASE"])
            }
            [commit] if commit == "COMMIT" => Some(&["WORK", "COMMENT", "WRITE", "FORCE"]),
            [.., commit, write] if !mysql && commit == "COMMIT" && write == "WRITE" => {
                Some(&["WAIT", "NOWAIT", "IMMEDIATE", "BATCH"])
            }
            [.., commit, write, wait_mode]
                if !mysql
                    && commit == "COMMIT"
                    && write == "WRITE"
                    && matches!(wait_mode.as_str(), "WAIT" | "NOWAIT") =>
            {
                Some(&["IMMEDIATE", "BATCH"])
            }
            [.., commit, write, logging_mode]
                if !mysql
                    && commit == "COMMIT"
                    && write == "WRITE"
                    && matches!(logging_mode.as_str(), "IMMEDIATE" | "BATCH") =>
            {
                Some(&["WAIT", "NOWAIT"])
            }
            [rollback] if rollback == "ROLLBACK" && mysql => Some(&[
                "WORK",
                "AND",
                "CHAIN",
                "NO",
                "RELEASE",
                "TO",
                "TO SAVEPOINT",
            ]),
            [rollback] if rollback == "ROLLBACK" => Some(&["WORK", "TO SAVEPOINT", "FORCE"]),
            [rollback, to] if rollback == "ROLLBACK" && to == "TO" => Some(&["SAVEPOINT"]),
            [set, transaction] if set == "SET" && transaction == "TRANSACTION" => {
                // `USE ROLLBACK SEGMENT` / `NAME` are Oracle-only.
                if mysql {
                    Some(&["ISOLATION", "READ"])
                } else {
                    Some(&["READ", "ISOLATION", "USE", "NAME"])
                }
            }
            [set, transaction, read]
                if set == "SET" && transaction == "TRANSACTION" && read == "READ" =>
            {
                Some(&["ONLY", "WRITE"])
            }
            [set, transaction, isolation]
                if set == "SET" && transaction == "TRANSACTION" && isolation == "ISOLATION" =>
            {
                Some(&["LEVEL"])
            }
            [set, transaction, isolation, level]
                if set == "SET"
                    && transaction == "TRANSACTION"
                    && isolation == "ISOLATION"
                    && level == "LEVEL" =>
            {
                // Oracle supports only SERIALIZABLE / READ COMMITTED; MySQL adds
                // REPEATABLE READ and READ UNCOMMITTED.
                if mysql {
                    Some(&[
                        "SERIALIZABLE",
                        "READ COMMITTED",
                        "REPEATABLE READ",
                        "READ UNCOMMITTED",
                    ])
                } else {
                    Some(&["SERIALIZABLE", "READ COMMITTED"])
                }
            }
            [start] if mysql && start == "START" => Some(&["TRANSACTION", "REPLICA", "SLAVE"]),
            [start, transaction] if mysql && start == "START" && transaction == "TRANSACTION" => {
                Some(&["READ", "WITH"])
            }
            [lock] if mysql && lock == "LOCK" => Some(&["TABLES", "INSTANCE"]),
            [lock] if lock == "LOCK" => Some(&["TABLE"]),
            [lock, table, _name] if !mysql && lock == "LOCK" && table == "TABLE" => Some(&["IN"]),
            [lock, table, _name, in_word]
                if !mysql && lock == "LOCK" && table == "TABLE" && in_word == "IN" =>
            {
                Some(&["ROW", "SHARE", "EXCLUSIVE"])
            }
            [.., in_word, row] if !mysql && lock_statement && in_word == "IN" && row == "ROW" => {
                Some(&["SHARE", "EXCLUSIVE"])
            }
            [.., in_word, share]
                if !mysql && lock_statement && in_word == "IN" && share == "SHARE" =>
            {
                Some(&["UPDATE", "ROW", "MODE"])
            }
            [.., last]
                if !mysql
                    && lock_statement
                    && contains("IN")
                    && matches!(last.as_str(), "EXCLUSIVE" | "UPDATE") =>
            {
                Some(&["MODE"])
            }
            [.., last] if !mysql && lock_statement && last == "MODE" => Some(&["NOWAIT", "WAIT"]),
            [lock, tables, _name] if mysql && lock == "LOCK" && tables == "TABLES" => {
                Some(&["AS", "READ", "WRITE", "LOW_PRIORITY WRITE"])
            }
            [unlock] if mysql && unlock == "UNLOCK" => Some(&["INSTANCE", "TABLES"]),
            _ => None,
        }
    }

    /// Token index where the PL/SQL statement containing the cursor begins —
    /// just past the last depth-0 statement boundary (`;`, or a body-opening
    /// `BEGIN`/`THEN`/`ELSE`/`LOOP`/`EXCEPTION`/`DECLARE` keyword). Boundary
    /// words inside parens are expression content (`CASE … THEN` in an embedded
    /// query), not statement boundaries, so depth is tracked.
    fn plsql_statement_slot_start(tokens: &[SqlToken], end: usize) -> usize {
        let visible_end = end.min(tokens.len());
        let mut depth = 0i32;
        let mut start = 0usize;
        for (idx, token) in tokens.iter().take(visible_end).enumerate() {
            match token {
                SqlToken::Symbol(sym) if sym == "(" || sym == "[" => depth += 1,
                SqlToken::Symbol(sym) if sym == ")" || sym == "]" => depth -= 1,
                SqlToken::Symbol(sym) if sym == ";" && depth <= 0 => start = idx + 1,
                SqlToken::Word(word) if depth <= 0 => {
                    if matches!(
                        word.to_ascii_uppercase().as_str(),
                        "BEGIN" | "THEN" | "ELSE" | "LOOP" | "EXCEPTION" | "DECLARE"
                    ) {
                        start = idx + 1;
                    }
                }
                _ => {}
            }
        }
        start
    }

    /// Uppercased words of the PL/SQL statement containing the cursor (scoped by
    /// [`Self::plsql_statement_slot_start`]), so a statement-tail scan can't latch
    /// onto keywords from an earlier statement in the same block.
    fn words_for_plsql_statement_slot(tokens: &[SqlToken], end: usize) -> Vec<String> {
        let start = Self::plsql_statement_slot_start(tokens, end);
        tokens
            .get(start..end.min(tokens.len()))
            .unwrap_or(&[])
            .iter()
            .filter_map(|token| match token {
                SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
                _ => None,
            })
            .collect()
    }

    fn words_for_keyword_slot(tokens: &[SqlToken], end: usize) -> Vec<String> {
        let visible_end = end.min(tokens.len());
        let visible_words = tokens
            .iter()
            .take(visible_end)
            .filter_map(|token| match token {
                SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
                _ => None,
            })
            .collect::<Vec<_>>();
        if visible_words.is_empty() {
            tokens
                .iter()
                .filter_map(|token| match token {
                    SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
                    _ => None,
                })
                .collect()
        } else {
            visible_words
        }
    }

    /// Keywords grammatical at a PL/SQL block *statement-start* position — a block
    /// body, a loop body, or an `IF`/statement-`CASE`/exception-handler branch body
    /// (`BEGIN |`, `; |`, `THEN |`, `ELSE |`, `LOOP |`). The position and the
    /// admissible continuations are resolved by the shared construct scan
    /// (`cursor_statement_start_context` → `PlsqlKeywordPolicy`), so this offers
    /// exactly the procedural statement verbs plus the enclosing construct's
    /// continuations (`ELSIF`/`ELSE`/`EXIT`/`CONTINUE`/`WHEN`/`EXCEPTION`/the
    /// precise `END …`). Non-statement positions — a condition/selector/value
    /// operand, or a value-expression `CASE` arm — yield `None` (the policy's
    /// `allow_statements` is off there), leaving the expression allowlist and the
    /// header/partial-construct source (`expected_plsql_and_routine_keyword_candidates`)
    /// to govern. Oracle-only; MySQL/MariaDB stored programs use a different grammar.
    fn expected_plsql_block_statement_keyword_candidates(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<Vec<&'static str>> {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return None;
        }
        let StatementStartContext::Plsql(policy) =
            Self::cursor_statement_start_context(tokens, end)?
        else {
            return None;
        };
        // Only genuine statement-start positions offer statement verbs. Most
        // construct-only tails (`CASE |`, `CASE ... THEN ... |`) are handled by
        // `expected_plsql_and_routine_keyword_candidates`, which carries richer
        // alternatives such as `ELSE`/`END CASE`; keep this source to statement
        // starts plus the exception-section opener.
        if !policy.allow_statements {
            let prev_word = Self::meaningful_tokens_before(tokens, end)
                .last()
                .and_then(|token| match token {
                    SqlToken::Word(word) => Some(word.as_str()),
                    _ => None,
                });
            if policy.allow_when
                && prev_word.is_some_and(|word| word.eq_ignore_ascii_case("EXCEPTION"))
            {
                return Some(vec!["WHEN"]);
            }
            // A value-expression `CASE` arm tail (`v := CASE WHEN a THEN 1 |`):
            // the policy carries the exact continuations, including the bare
            // `END` (not the statement form's `END CASE`). The selector-only
            // policy (`allow_when` without `allow_end`) stays with the richer
            // `expected_plsql_and_routine_keyword_candidates` source.
            if policy.allow_end {
                let mut candidates: Vec<&'static str> = Vec::new();
                if policy.allow_when {
                    candidates.push("WHEN");
                }
                if policy.allow_else {
                    candidates.push("ELSE");
                }
                if let Some(end_keyword) = policy.end_keyword {
                    candidates.push(end_keyword);
                }
                return Some(candidates);
            }
            return None;
        }

        let mut candidates: Vec<&'static str> = PLSQL_STATEMENT_KEYWORDS.to_vec();
        if policy.allow_exit_continue {
            candidates.push("EXIT");
            candidates.push("CONTINUE");
        }
        if policy.allow_elsif {
            candidates.push("ELSIF");
        }
        if policy.allow_else {
            candidates.push("ELSE");
        }
        if policy.allow_when {
            candidates.push("WHEN");
        }
        if policy.allow_exception {
            candidates.push("EXCEPTION");
        }
        if let Some(end_keyword) = policy.end_keyword.filter(|_| policy.allow_end) {
            candidates.push(end_keyword);
        }
        (!candidates.is_empty()).then_some(candidates)
    }

    /// Keyword tails of the PL/SQL cursor statements `OPEN <cur> FOR <query>` and
    /// `FETCH <cur> [BULK COLLECT] INTO <targets>`. Gated to an executable block so
    /// the cursor `FETCH <name>` is told apart from the SQL row-limiting
    /// `FETCH {FIRST|NEXT} …` (whose name token is a keyword, also excluded). After
    /// `… FOR` a query begins, so `SELECT`/`WITH` are offered; `FETCH <cur> |` opens
    /// the destination with `INTO` or `BULK COLLECT`. Oracle-only.
    fn expected_plsql_cursor_statement_keywords(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<&'static [&'static str]> {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return None;
        }
        if !Self::cursor_in_plsql_executable_block(tokens, end) {
            return None;
        }
        let words = Self::words_for_keyword_slot(tokens, end);
        let is_keyword = |word: &str| {
            crate::sql_text::is_sql_keyword_for_db(word, crate::db::DatabaseType::Oracle)
        };

        // `FORALL <idx> IN <bounds> [SAVE EXCEPTIONS] |` is followed by exactly one
        // bound DML statement. After the bound (a complete operand) the DML verbs are
        // offered — plus `SAVE EXCEPTIONS`, until it is present; once a DML verb has
        // begun, nothing is re-offered.
        if let Some(forall_idx) = words.iter().position(|word| word == "FORALL") {
            let after = &words[forall_idx..];
            let has_in = after.iter().any(|word| word == "IN");
            let has_dml = after.iter().any(|word| {
                matches!(
                    word.as_str(),
                    "INSERT" | "UPDATE" | "DELETE" | "MERGE" | "EXECUTE"
                )
            });
            if has_in && !has_dml {
                // The sparse-bound forms: `FORALL i IN INDICES |` / `VALUES |`
                // await their `OF <collection>`.
                if matches!(words.last().map(String::as_str), Some("INDICES" | "VALUES")) {
                    return Some(&["OF"]);
                }
                // `FORALL … SAVE |` awaits exactly `EXCEPTIONS`.
                if words.last().map(String::as_str) == Some("SAVE") {
                    return Some(&["EXCEPTIONS"]);
                }
                if words.last().map(String::as_str) == Some("EXCEPTIONS") {
                    return Some(&["INSERT", "UPDATE", "DELETE", "MERGE", "EXECUTE IMMEDIATE"]);
                }
                // The bound is complete only past its operand — not at the bound
                // keywords themselves (`IN |`, `INDICES |`, `INDICES OF |`).
                if !matches!(
                    words.last().map(String::as_str),
                    Some("IN" | "OF" | "INDICES" | "VALUES")
                ) && Self::cursor_immediately_follows_complete_operand(tokens, end)
                {
                    return Some(&[
                        "INSERT",
                        "UPDATE",
                        "DELETE",
                        "MERGE",
                        "EXECUTE IMMEDIATE",
                        "SAVE EXCEPTIONS",
                    ]);
                }
            }
        }

        // `OPEN <cur> FOR <dynamic-sql-expr> |` — once the dynamic-SQL string
        // expression is complete, an optional `USING <binds>` follows. A static
        // embedded query (`FOR SELECT|WITH ...`) never takes `USING` here (its
        // predicates hold literal/bound values directly), so this is scoped to
        // a `FOR` target that is not itself a query.
        if let Some(open_idx) = words.iter().position(|word| word == "OPEN") {
            if let Some(for_idx) = words[open_idx..]
                .iter()
                .position(|word| word == "FOR")
                .map(|idx| open_idx + idx)
            {
                let after_for = &words[for_idx + 1..];
                if !after_for.is_empty()
                    && !matches!(after_for[0].as_str(), "SELECT" | "WITH")
                    && !after_for.iter().any(|word| word == "USING")
                    && Self::cursor_immediately_follows_complete_operand(tokens, end)
                {
                    return Some(&["USING"]);
                }
            }
        }

        // Statement-scoped tails: these anchor on the statement's *leading* verb,
        // so they scan only the words of the statement containing the cursor —
        // an earlier `EXECUTE IMMEDIATE …;` in the same block must not leak its
        // tail into the next statement.
        let stmt_words = Self::words_for_plsql_statement_slot(tokens, end);
        let stmt_last = stmt_words.last().map(String::as_str);

        // `PIPE |` → `ROW` (pipelined-function emission).
        if stmt_words.len() == 1 && stmt_words[0] == "PIPE" {
            return Some(&["ROW"]);
        }

        // `EXECUTE IMMEDIATE <sql-expr> |` — the result/bind clauses follow the
        // complete dynamic-SQL expression: `INTO`/`USING`/`BULK COLLECT INTO`,
        // then `USING` after the `INTO` targets.
        if stmt_words.first().map(String::as_str) == Some("EXECUTE")
            && stmt_words.get(1).map(String::as_str) == Some("IMMEDIATE")
            && !stmt_words.iter().any(|word| word == "USING")
        {
            let has_into = stmt_words.iter().any(|word| word == "INTO");
            if stmt_last == Some("BULK") {
                return Some(&["COLLECT"]);
            }
            if stmt_last == Some("COLLECT") {
                return Some(&["INTO"]);
            }
            // The word list drops literals, so "the operand is complete" is a
            // token question: the dynamic-SQL string right after `IMMEDIATE`
            // (`EXECUTE IMMEDIATE 'x' |`) is a `String` token invisible above.
            // A trailing keyword (`IMMEDIATE |`, `INTO |`) still awaits its
            // operand/targets, so those slots stay with the operand path.
            let prev_awaits_operand = matches!(
                Self::meaningful_tokens_before(tokens, end).last(),
                Some(SqlToken::Word(word))
                    if matches!(word.to_ascii_uppercase().as_str(), "IMMEDIATE" | "INTO")
            );
            if !prev_awaits_operand
                && Self::cursor_immediately_follows_complete_operand(tokens, end)
            {
                if has_into {
                    return Some(&["USING"]);
                }
                return Some(&["INTO", "USING", "BULK COLLECT INTO"]);
            }
        }

        // `FETCH <cur> BULK COLLECT INTO <targets> |` → the optional `LIMIT`.
        if stmt_words.first().map(String::as_str) == Some("FETCH")
            && stmt_words.iter().any(|word| word == "BULK")
            && stmt_words.iter().any(|word| word == "COLLECT")
            && stmt_words.iter().any(|word| word == "INTO")
            && !stmt_words.iter().any(|word| word == "LIMIT")
            && stmt_last != Some("INTO")
            && Self::cursor_immediately_follows_complete_operand(tokens, end)
        {
            return Some(&["LIMIT"]);
        }

        match words.as_slice() {
            // `FOR <index> IN (|` — a cursor-FOR loop query begins. Numeric
            // loops do not parenthesize their bounds, so this shape is the
            // embedded-query form.
            [.., for_word, index, in_word]
                if for_word == "FOR"
                    && in_word == "IN"
                    && !is_keyword(index)
                    && matches!(
                        Self::meaningful_tokens_before(tokens, end).last(),
                        Some(SqlToken::Symbol(symbol)) if symbol == "("
                    ) =>
            {
                Some(&["SELECT", "WITH"])
            }
            // `OPEN <cur> |` — the query opener follows.
            [.., open, name] if open == "OPEN" && !is_keyword(name) => Some(&["FOR"]),
            // `OPEN <cur> FOR |` — a query expression follows.
            [.., open, name, for_word]
                if open == "OPEN" && for_word == "FOR" && !is_keyword(name) =>
            {
                Some(&["SELECT", "WITH"])
            }
            // `FETCH <cur> BULK COLLECT |` → `INTO`.
            [.., fetch, name, bulk, collect]
                if fetch == "FETCH"
                    && bulk == "BULK"
                    && collect == "COLLECT"
                    && !is_keyword(name) =>
            {
                Some(&["INTO"])
            }
            // `FETCH <cur> BULK |` → `COLLECT`.
            [.., fetch, name, bulk] if fetch == "FETCH" && bulk == "BULK" && !is_keyword(name) => {
                Some(&["COLLECT"])
            }
            // `FETCH <cur> |` — the destination opener.
            [.., fetch, name] if fetch == "FETCH" && !is_keyword(name) => {
                Some(&["INTO", "BULK COLLECT"])
            }
            // `EXIT |` / `CONTINUE |` — the optional `WHEN <condition>` guard (a bare
            // `EXIT;` or `EXIT <label>;` is also valid, so this is additive, not a
            // required slot).
            [.., last] if matches!(last.as_str(), "EXIT" | "CONTINUE") => Some(&["WHEN"]),
            // `EXIT <label> |` / `CONTINUE <label> |` — the optional guard may
            // still follow the label; the label itself is not a catalog name.
            [.., exit_or_continue, label]
                if matches!(exit_or_continue.as_str(), "EXIT" | "CONTINUE")
                    && !is_keyword(label) =>
            {
                Some(&["WHEN"])
            }
            _ => None,
        }
    }

    /// The query/dynamic-SQL source slot of `OPEN <cursor> FOR |`. The slot's
    /// keywords (`SELECT`/`WITH`) make it identifier-suppressing, yet a local
    /// variable holding dynamic SQL is equally grammatical there
    /// (`OPEN rc FOR v_sql`), so the local-symbol source is re-admitted via
    /// `at_name_only_local_symbol_slot` while the object catalog stays out.
    fn cursor_is_at_plsql_open_for_source_slot(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type)
            || !Self::cursor_in_plsql_executable_block(tokens, end)
        {
            return false;
        }
        let words = Self::words_for_keyword_slot(tokens, end);
        let is_keyword = |word: &str| {
            crate::sql_text::is_sql_keyword_for_db(word, crate::db::DatabaseType::Oracle)
        };
        matches!(
            words.as_slice(),
            [.., open, name, for_word]
                if open == "OPEN" && for_word == "FOR" && !is_keyword(name)
        )
    }

    fn cursor_is_at_plsql_open_for_source_slot_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let context_end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        if Self::cursor_is_at_plsql_open_for_source_slot(tokens, context_end, db_type) {
            return true;
        }

        let statement_tokens = deep_ctx.statement_tokens.as_ref();
        let statement_end = Self::expected_suggestion_context_end(
            statement_tokens,
            deep_ctx.cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::cursor_is_at_plsql_open_for_source_slot(statement_tokens, statement_end, db_type)
    }

    fn cursor_is_at_plsql_goto_label_slot(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type)
            || !Self::cursor_in_plsql_executable_block(tokens, end)
        {
            return false;
        }

        let toks = Self::meaningful_tokens_before(tokens, end);
        let is_label_word = |token: &SqlToken| match token {
            SqlToken::Word(word) => {
                !crate::sql_text::is_sql_keyword_for_db(word, crate::db::DatabaseType::Oracle)
            }
            _ => false,
        };

        matches!(
            toks.as_slice(),
            [.., SqlToken::Word(goto)] if goto.eq_ignore_ascii_case("GOTO")
        ) || matches!(
            toks.as_slice(),
            [.., SqlToken::Word(goto), label]
                if goto.eq_ignore_ascii_case("GOTO") && is_label_word(label)
        )
    }

    /// Label names declared as `<<label>>` anywhere in the current block, offered at
    /// a `GOTO |` target slot. The tokenizer emits a whole `<<label>>` marker as one
    /// `Word`, so strip the `<<`/`>>` fence and keep the inner identifier. Filtered by
    /// the typed prefix; duplicates collapsed.
    fn plsql_block_label_suggestions(
        deep_ctx: &intellisense_context::CursorContext,
        prefix: &str,
    ) -> Vec<String> {
        let prefix_upper = prefix.to_ascii_uppercase();
        let mut seen = std::collections::HashSet::new();
        let mut labels = Vec::new();
        for token in deep_ctx.statement_tokens.as_ref() {
            let SqlToken::Word(word) = token else {
                continue;
            };
            let trimmed = word.trim();
            let Some(inner) = trimmed
                .strip_prefix("<<")
                .and_then(|rest| rest.strip_suffix(">>"))
                .map(str::trim)
                .filter(|inner| !inner.is_empty())
            else {
                continue;
            };
            if !inner.to_ascii_uppercase().starts_with(&prefix_upper) {
                continue;
            }
            if seen.insert(inner.to_ascii_uppercase()) {
                labels.push(inner.to_string());
            }
        }
        labels
    }

    fn cursor_is_at_mysql_leave_iterate_label_slot(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if !crate::sql_text::mysql_compatibility_for_sql("", db_type)
            || Self::unclosed_paren_count(tokens, end) != 0
        {
            return false;
        }
        let start = Self::plsql_statement_slot_start(tokens, end);
        let words = tokens
            .get(start..end.min(tokens.len()))
            .unwrap_or(&[])
            .iter()
            .filter_map(|token| match token {
                SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
                _ => None,
            })
            .collect::<Vec<_>>();
        matches!(
            words.as_slice(),
            [.., keyword] if matches!(keyword.as_str(), "LEAVE" | "ITERATE")
        )
    }

    fn cursor_is_at_mysql_leave_iterate_label_slot_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        let tokens = deep_ctx.statement_tokens.as_ref();
        let end = Self::expected_suggestion_context_end(
            tokens,
            deep_ctx.cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::cursor_is_at_mysql_leave_iterate_label_slot(tokens, end, db_type)
    }

    fn cursor_is_at_mysql_end_label_slot_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if !crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return false;
        }
        let tokens = deep_ctx.statement_tokens.as_ref();
        let end = Self::expected_suggestion_context_end(
            tokens,
            deep_ctx.cursor_token_len,
            exclude_current_identifier_chain,
        );
        let words = Self::previous_meaningful_words_upper(tokens, end, 2);
        matches!(words.as_slice(), [.., end_kw] if end_kw == "END")
            || matches!(words.as_slice(), [.., end_kw, loop_kw] if end_kw == "END" && loop_kw == "LOOP")
    }

    fn mysql_expected_end_label_suggestions(
        deep_ctx: &intellisense_context::CursorContext,
        prefix: &str,
    ) -> Vec<String> {
        let tokens = deep_ctx.statement_tokens.as_ref();
        let end = Self::expected_suggestion_context_end(
            tokens,
            deep_ctx.cursor_token_len,
            !prefix.is_empty(),
        );
        Self::mysql_expected_end_label_suggestions_from_tokens(tokens, end, prefix)
    }

    fn mysql_expected_end_label_suggestions_from_tokens(
        tokens: &[SqlToken],
        end: usize,
        prefix: &str,
    ) -> Vec<String> {
        #[derive(Clone, Copy, PartialEq, Eq)]
        enum FrameKind {
            Begin,
            Loop,
            While,
            Repeat,
            If,
            Case,
        }

        let end = end.min(tokens.len());
        let meaningful = tokens
            .get(..end)
            .unwrap_or(&[])
            .iter()
            .enumerate()
            .filter(|(_, token)| !matches!(token, SqlToken::Comment(_)))
            .collect::<Vec<_>>();
        let closes_loop = matches!(
            meaningful.as_slice(),
            [.., (_, SqlToken::Word(end_kw)), (_, SqlToken::Word(loop_kw))]
                if end_kw.eq_ignore_ascii_case("END") && loop_kw.eq_ignore_ascii_case("LOOP")
        );
        let closing_token_count = if closes_loop { 2 } else { 1 };
        let scan_len = meaningful.len().saturating_sub(closing_token_count);
        let mut frames = Vec::<(FrameKind, Option<String>)>::new();
        let mut pending_label = None::<String>;
        let mut idx = 0usize;

        while idx < scan_len {
            let (_, token) = meaningful[idx];
            if let SqlToken::Word(word) = token {
                if idx + 1 < scan_len
                    && matches!(meaningful[idx + 1].1, SqlToken::Symbol(symbol) if symbol == ":")
                {
                    pending_label = Self::local_identifier_suggestion_from_word(word);
                    idx += 2;
                    continue;
                }

                let upper = word.to_ascii_uppercase();
                let previous_is_end = idx > 0
                    && matches!(meaningful[idx - 1].1, SqlToken::Word(previous) if previous.eq_ignore_ascii_case("END"));
                match upper.as_str() {
                    "BEGIN" if !previous_is_end => {
                        frames.push((FrameKind::Begin, pending_label.take()));
                    }
                    "LOOP" if !previous_is_end => {
                        frames.push((FrameKind::Loop, pending_label.take()));
                    }
                    "WHILE" if !previous_is_end => {
                        frames.push((FrameKind::While, pending_label.take()));
                    }
                    "REPEAT" if !previous_is_end => {
                        frames.push((FrameKind::Repeat, pending_label.take()));
                    }
                    "IF" if !previous_is_end => frames.push((FrameKind::If, None)),
                    "CASE" if !previous_is_end => frames.push((FrameKind::Case, None)),
                    "END" => {
                        let suffix = meaningful.get(idx + 1).and_then(|(_, token)| {
                            Self::token_word(token).map(str::to_ascii_uppercase)
                        });
                        let kind = match suffix.as_deref() {
                            Some("LOOP") => Some(FrameKind::Loop),
                            Some("FOR") => Some(FrameKind::Loop),
                            Some("WHILE") => Some(FrameKind::While),
                            Some("REPEAT") => Some(FrameKind::Repeat),
                            Some("IF") => Some(FrameKind::If),
                            Some("CASE") => Some(FrameKind::Case),
                            _ if frames
                                .last()
                                .is_some_and(|(kind, _)| *kind == FrameKind::Case) =>
                            {
                                Some(FrameKind::Case)
                            }
                            _ => Some(FrameKind::Begin),
                        };
                        if let Some(kind) = kind {
                            if let Some(frame_idx) = frames
                                .iter()
                                .rposition(|(frame_kind, _)| *frame_kind == kind)
                            {
                                frames.truncate(frame_idx);
                            }
                        }
                        if suffix.is_some() {
                            idx += 1;
                        }
                    }
                    _ => {}
                }
            }
            idx += 1;
        }

        let expected_kind = if closes_loop {
            FrameKind::Loop
        } else {
            FrameKind::Begin
        };
        let prefix_upper = Self::local_identifier_lookup_upper(prefix);
        let Some(label) = frames
            .iter()
            .rev()
            .find(|(kind, _)| *kind == expected_kind)
            .and_then(|(_, label)| label.as_ref())
        else {
            return Vec::new();
        };
        let upper = Self::local_identifier_lookup_upper(label);
        if Self::local_symbol_matches_prefix(label, &upper, &prefix_upper) {
            vec![label.clone()]
        } else {
            Vec::new()
        }
    }

    fn mysql_expected_end_label_suggestions_from_statement_text(
        statement_text: &str,
        cursor_in_statement: usize,
        prefix: &str,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Vec<String> {
        if !crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return Vec::new();
        }
        let cursor = cursor_in_statement.min(statement_text.len());
        let prefix_start = cursor.saturating_sub(prefix.len());
        if !Self::text_before_cursor_ends_with_plsql_end_label_slot(
            statement_text.get(..cursor).unwrap_or(statement_text),
            prefix,
        ) {
            return Vec::new();
        }
        let spans = super::query_text::tokenize_sql_spanned(statement_text);
        let end = spans.partition_point(|span| span.end <= prefix_start);
        let tokens = spans
            .into_iter()
            .map(|span| span.token)
            .collect::<Vec<_>>();
        Self::mysql_expected_end_label_suggestions_from_tokens(&tokens, end, prefix)
    }

    fn mysql_block_label_suggestions(
        deep_ctx: &intellisense_context::CursorContext,
        prefix: &str,
    ) -> Vec<String> {
        let prefix_upper = Self::local_identifier_lookup_upper(prefix);
        let tokens = deep_ctx.statement_tokens.as_ref();
        let end = Self::expected_suggestion_context_end(
            tokens,
            deep_ctx.cursor_token_len,
            !prefix.is_empty(),
        )
        .min(tokens.len());
        let mut seen = std::collections::HashSet::new();
        let mut labels = Vec::new();

        for idx in 0..end.saturating_sub(1) {
            let Some(name) =
                Self::token_word(&tokens[idx]).and_then(Self::local_identifier_suggestion_from_word)
            else {
                continue;
            };
            if !matches!(tokens.get(idx + 1), Some(SqlToken::Symbol(symbol)) if symbol == ":") {
                continue;
            }
            let upper = Self::local_identifier_lookup_upper(&name);
            if !Self::local_symbol_matches_prefix(&name, &upper, &prefix_upper) {
                continue;
            }
            if seen.insert(upper) {
                labels.push(name);
            }
        }

        labels
    }

    fn plsql_savepoint_suggestions(
        deep_ctx: &intellisense_context::CursorContext,
        prefix: &str,
    ) -> Vec<String> {
        let prefix_upper = Self::local_identifier_lookup_upper(prefix);
        let tokens = deep_ctx.statement_tokens.as_ref();
        let end = Self::expected_suggestion_context_end(
            tokens,
            deep_ctx.cursor_token_len,
            !prefix.is_empty(),
        )
        .min(tokens.len());
        let mut seen = std::collections::HashSet::new();
        let mut savepoints = Vec::new();

        for (idx, token) in tokens.iter().take(end).enumerate() {
            let SqlToken::Word(word) = token else {
                continue;
            };
            if !word.eq_ignore_ascii_case("SAVEPOINT") {
                continue;
            }
            let statement_start = Self::plsql_statement_slot_start(tokens, idx);
            if Self::next_non_comment_token_index(tokens, statement_start) != Some(idx) {
                continue;
            }
            let Some(name_idx) = Self::next_non_comment_token_index(tokens, idx + 1) else {
                continue;
            };
            if name_idx >= end {
                continue;
            }
            let Some(name) = Self::token_word(&tokens[name_idx])
                .and_then(Self::local_identifier_suggestion_from_word)
            else {
                continue;
            };
            let upper = Self::local_identifier_lookup_upper(&name);
            if !Self::local_symbol_matches_prefix(&name, &upper, &prefix_upper) {
                continue;
            }
            if seen.insert(upper) {
                savepoints.push(name);
            }
        }

        savepoints
    }

    /// The enclosing named PL/SQL object (`PACKAGE [BODY]`, `PROCEDURE`,
    /// `FUNCTION`, `TYPE BODY`) whose closing `END` admits repeating the name —
    /// `END <name>;` — found by scanning the statement's construct stack up to
    /// the cursor. Anonymous constructs (`IF`/`LOOP`/`CASE`, a bare/`DECLARE`d
    /// `BEGIN…END` block, and `TRIGGER`, whose body Oracle never lets you name
    /// after `END`) push a nameless frame so a name surfaces only at the exact
    /// `END` that closes a genuinely named object — not at every `END` in the
    /// statement.
    fn expected_plsql_named_end_target(tokens: &[SqlToken], end: usize) -> Option<String> {
        #[derive(Clone)]
        enum Frame {
            Named(String, bool),
            Anonymous(bool),
        }
        let toks = tokens.get(..end.min(tokens.len()))?;
        if !matches!(toks.last(), Some(SqlToken::Word(w)) if w.eq_ignore_ascii_case("END")) {
            return None;
        }
        let mut stack: Vec<Frame> = Vec::new();
        let mut last_popped_name: Option<String> = None;
        let mut idx = 0usize;
        while idx < toks.len() {
            let SqlToken::Word(word) = &toks[idx] else {
                idx += 1;
                continue;
            };
            let upper = word.to_ascii_uppercase();
            match upper.as_str() {
                "PACKAGE" => {
                    let mut j = idx + 1;
                    if matches!(toks.get(j), Some(SqlToken::Word(w)) if w.eq_ignore_ascii_case("BODY"))
                    {
                        j += 1;
                    }
                    if let Some((name, after_name)) =
                        Self::plsql_qualified_identifier_last_segment(toks, j)
                    {
                        stack.push(Frame::Named(name, true));
                        idx = after_name;
                        continue;
                    }
                }
                "PROCEDURE" | "FUNCTION" => {
                    if let Some((name, after_name)) =
                        Self::plsql_qualified_identifier_last_segment(toks, idx + 1)
                    {
                        // A package-spec/standalone-forward declaration
                        // (`PROCEDURE p(...);`) has no body and thus no
                        // matching `END` — only a full definition (`IS`/`AS`
                        // reached before the declaration's own `;`) does. Look
                        // ahead past the parameter list to tell them apart so
                        // a spec-only declaration never pushes a stray frame
                        // that would misalign a later, unrelated `END`.
                        let mut j = after_name;
                        let mut paren_depth: i32 = 0;
                        let mut found_body = false;
                        while j < toks.len() {
                            match &toks[j] {
                                SqlToken::Symbol(sym) if sym == "(" => paren_depth += 1,
                                SqlToken::Symbol(sym) if sym == ")" => paren_depth -= 1,
                                SqlToken::Symbol(sym) if sym == ";" && paren_depth <= 0 => break,
                                SqlToken::Word(w)
                                    if paren_depth <= 0
                                        && matches!(w.to_ascii_uppercase().as_str(), "IS" | "AS") =>
                                {
                                    found_body = true;
                                    break;
                                }
                                _ => {}
                            }
                            j += 1;
                        }
                        if found_body {
                            stack.push(Frame::Named(name, true));
                        }
                        idx = j + 1;
                        continue;
                    }
                }
                "TYPE" => {
                    // `TYPE BODY name IS …` (a body, needs its own `END`) vs a
                    // plain `TYPE name IS …` local/spec declaration (RECORD,
                    // collection, or object-type spec — none take an `END`).
                    let is_body = matches!(
                        toks.get(idx + 1),
                        Some(SqlToken::Word(w)) if w.eq_ignore_ascii_case("BODY")
                    );
                    let name_idx = if is_body { idx + 2 } else { idx + 1 };
                    if let Some((name, after_name)) =
                        Self::plsql_qualified_identifier_last_segment(toks, name_idx)
                    {
                        if is_body {
                            stack.push(Frame::Named(name, true));
                        }
                        idx = after_name;
                        continue;
                    }
                }
                "DECLARE" | "TRIGGER" => stack.push(Frame::Anonymous(true)),
                "IF" | "LOOP" | "CASE" => stack.push(Frame::Anonymous(false)),
                "BEGIN" => {
                    let consumed_existing = match stack.last_mut() {
                        Some(Frame::Named(_, awaiting) | Frame::Anonymous(awaiting))
                            if *awaiting =>
                        {
                            *awaiting = false;
                            true
                        }
                        _ => false,
                    };
                    if !consumed_existing {
                        stack.push(Frame::Anonymous(false));
                    }
                }
                "END" => {
                    last_popped_name = match stack.pop() {
                        Some(Frame::Named(name, _)) => Some(name),
                        _ => None,
                    };
                    let mut j = idx + 1;
                    while j < toks.len() {
                        match &toks[j] {
                            SqlToken::Comment(_) => j += 1,
                            SqlToken::Symbol(sym) if sym == ";" => {
                                j += 1;
                                break;
                            }
                            SqlToken::Word(_) | SqlToken::String(_) => j += 1,
                            SqlToken::Symbol(sym) if sym == "." => j += 1,
                            _ => break,
                        }
                    }
                    idx = j;
                    continue;
                }
                _ => {}
            }
            idx += 1;
        }
        last_popped_name
    }

    fn plsql_qualified_identifier_last_segment(
        tokens: &[SqlToken],
        start: usize,
    ) -> Option<(String, usize)> {
        let first_idx = Self::next_non_comment_token_index(tokens, start)?;
        let mut current_idx = first_idx;
        let mut name = Self::plsql_identifier_segment_name(tokens.get(current_idx))?;
        let mut after_name = current_idx + 1;

        loop {
            let Some(dot_idx) = Self::next_non_comment_token_index(tokens, after_name) else {
                break;
            };
            if !matches!(tokens.get(dot_idx), Some(SqlToken::Symbol(sym)) if sym == ".") {
                break;
            }
            let Some(next_idx) = Self::next_non_comment_token_index(tokens, dot_idx + 1) else {
                break;
            };
            let Some(next_name) = Self::plsql_identifier_segment_name(tokens.get(next_idx)) else {
                break;
            };
            current_idx = next_idx;
            name = next_name;
            after_name = current_idx + 1;
        }

        Some((name, after_name))
    }

    fn plsql_identifier_segment_name(token: Option<&SqlToken>) -> Option<String> {
        match token {
            Some(SqlToken::Word(word)) if !Self::is_plsql_non_type_keyword(word) => {
                Some(Self::strip_identifier_quotes(word))
            }
            Some(SqlToken::String(value)) if crate::sql_text::is_quoted_identifier(value) => {
                Some(Self::strip_identifier_quotes(value))
            }
            _ => None,
        }
    }

    fn cursor_is_at_plsql_named_end_target_slot(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return false;
        }
        Self::expected_plsql_named_end_target(tokens, end).is_some()
    }

    /// Cheap pre-check for the `END `-space auto-trigger: the characters right
    /// before the cursor, past any whitespace, form the bare word `END`.
    fn cursor_follows_end_keyword_word_in_text(text: &str, cursor: usize) -> bool {
        let head = match text.get(..cursor.min(text.len())) {
            Some(head) => head,
            None => return false,
        };
        let trimmed = head.trim_end();
        let word_start = trimmed
            .rfind(|ch: char| !crate::sql_text::is_identifier_char(ch))
            .map(|idx| idx + 1)
            .unwrap_or(0);
        trimmed
            .get(word_start..)
            .is_some_and(|word| word.eq_ignore_ascii_case("END"))
    }

    /// Whether typing a space after `END` should auto-open the popup: the slot
    /// has a *known* completion — the enclosing named object (`END my_proc`) or
    /// the enclosing construct's qualifier (`END IF`/`LOOP`/`CASE`). An `END`
    /// with nothing to offer (anonymous block, SQL `CASE … END`) stays quiet, so
    /// this never turns every space into a popup. The bounded statement scan
    /// only runs after the cheap "previous word is END" text check.
    fn plsql_end_auto_trigger_applies_in_text(
        full_text: &str,
        cursor: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type)
            || !Self::cursor_follows_end_keyword_word_in_text(full_text, cursor)
        {
            return false;
        }
        let bounded = Self::bounded_intellisense_parse_text_from_text(full_text, cursor);
        let expanded = Self::expanded_statement_window_in_bounded_text_for_db_type(&bounded, db_type);
        let spans = super::query_text::tokenize_sql_spanned(&expanded.text);
        let mut tokens = Vec::with_capacity(spans.len());
        let mut token_ends = Vec::with_capacity(spans.len());
        for span in spans {
            token_ends.push(span.end);
            tokens.push(span.token);
        }
        let end_idx = token_ends.partition_point(|end| *end <= expanded.cursor_in_statement);
        Self::expected_plsql_named_end_target(&tokens, end_idx).is_some()
            || Self::expected_plsql_end_qualifier_keywords(&tokens, end_idx, db_type).is_some()
    }

    const PLSQL_EXECUTE_IMMEDIATE_TAIL_AUTO_TRIGGER_LOOKBEHIND_BYTES: usize = 16 * 1024;

    fn plsql_execute_immediate_tail_auto_trigger_prefix(
        full_text: &str,
        cursor: usize,
    ) -> Option<&str> {
        let cursor = Self::clamp_to_char_boundary_local(full_text, cursor.min(full_text.len()));
        let start = Self::clamp_to_char_boundary_local(
            full_text,
            cursor.saturating_sub(
                Self::PLSQL_EXECUTE_IMMEDIATE_TAIL_AUTO_TRIGGER_LOOKBEHIND_BYTES,
            ),
        );
        full_text.get(start..cursor)
    }

    /// Whether typing a space in an `EXECUTE IMMEDIATE` statement should
    /// auto-open the popup for a known tail keyword such as `USING` after
    /// `INTO <target>`. This intentionally stays scoped to `EXECUTE IMMEDIATE`
    /// so ordinary PL/SQL spaces do not become popup triggers.
    fn plsql_execute_immediate_tail_auto_trigger_applies_in_text(
        full_text: &str,
        cursor: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return false;
        }
        let head = match Self::plsql_execute_immediate_tail_auto_trigger_prefix(full_text, cursor) {
            Some(head) => head,
            None => return false,
        };
        if !head.chars().last().is_some_and(char::is_whitespace) {
            return false;
        }

        let spans = super::query_text::tokenize_sql_spanned(head);
        let mut tokens = Vec::with_capacity(spans.len());
        for span in spans {
            tokens.push(span.token);
        }
        let end_idx = tokens.len();
        let stmt_words = Self::words_for_plsql_statement_slot(&tokens, end_idx);
        if stmt_words.first().map(String::as_str) != Some("EXECUTE")
            || stmt_words.get(1).map(String::as_str) != Some("IMMEDIATE")
        {
            return false;
        }

        Self::expected_plsql_cursor_statement_keywords(&tokens, end_idx, db_type).is_some()
    }

    fn cursor_is_at_plsql_named_end_target_slot_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let context_end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        if Self::cursor_is_at_plsql_named_end_target_slot(tokens, context_end, db_type) {
            return true;
        }

        let statement_tokens = deep_ctx.statement_tokens.as_ref();
        let statement_end = Self::expected_suggestion_context_end(
            statement_tokens,
            deep_ctx.cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::cursor_is_at_plsql_named_end_target_slot(statement_tokens, statement_end, db_type)
    }

    fn cursor_is_after_plsql_end_keyword(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return false;
        }
        let Some(end_idx) = Self::previous_non_comment_token_index(tokens, end) else {
            return false;
        };
        matches!(tokens.get(end_idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("END"))
    }

    fn cursor_is_after_plsql_end_keyword_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let context_end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        if Self::cursor_is_after_plsql_end_keyword(tokens, context_end, db_type) {
            return true;
        }

        let statement_tokens = deep_ctx.statement_tokens.as_ref();
        let statement_end = Self::expected_suggestion_context_end(
            statement_tokens,
            deep_ctx.cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::cursor_is_after_plsql_end_keyword(statement_tokens, statement_end, db_type)
    }

    /// The suggestion(s) at a named-object `END |` slot: just the one enclosing
    /// name, filtered by the typed prefix.
    fn plsql_named_end_target_suggestions(
        deep_ctx: &intellisense_context::CursorContext,
        prefix: &str,
    ) -> Vec<String> {
        let exclude_current_identifier_chain = !prefix.is_empty();
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let context_end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        let name = Self::expected_plsql_named_end_target(tokens, context_end).or_else(|| {
            let statement_tokens = deep_ctx.statement_tokens.as_ref();
            let statement_end = Self::expected_suggestion_context_end(
                statement_tokens,
                deep_ctx.cursor_token_len,
                exclude_current_identifier_chain,
            );
            Self::expected_plsql_named_end_target(statement_tokens, statement_end)
        });
        match name {
            Some(name) if name.to_ascii_uppercase().starts_with(&prefix.to_ascii_uppercase()) => {
                vec![name]
            }
            _ => Vec::new(),
        }
    }

    fn plsql_named_end_target_suggestions_from_statement_text(
        statement_text: &str,
        cursor_in_statement: usize,
        prefix: &str,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Vec<String> {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return Vec::new();
        }
        let cursor = cursor_in_statement.min(statement_text.len());
        let scan_cursor = if !prefix.is_empty()
            && statement_text
                .get(..cursor)
                .is_some_and(|head| head.ends_with(prefix))
        {
            cursor.saturating_sub(prefix.len())
        } else {
            cursor
        };
        let spans = super::query_text::tokenize_sql_spanned(statement_text);
        let mut tokens = Vec::with_capacity(spans.len());
        let mut token_ends = Vec::with_capacity(spans.len());
        for span in spans {
            token_ends.push(span.end);
            tokens.push(span.token);
        }
        let end = token_ends.partition_point(|token_end| *token_end <= scan_cursor);
        let name = Self::expected_plsql_named_end_target(&tokens, end).or_else(|| {
            (!prefix.is_empty()).then(|| {
                Self::infer_typed_plsql_named_end_target(&tokens, end, prefix)
            })?
        });
        let Some(name) = name else {
            return Vec::new();
        };
        if name.to_ascii_uppercase().starts_with(&prefix.to_ascii_uppercase()) {
            vec![name]
        } else {
            Vec::new()
        }
    }

    fn infer_typed_plsql_named_end_target(
        tokens: &[SqlToken],
        end: usize,
        prefix: &str,
    ) -> Option<String> {
        let tokens = tokens.get(..end.min(tokens.len()))?;
        if !matches!(tokens.last(), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("END"))
        {
            return None;
        }
        let matches_prefix = |name: &str| {
            Self::completion_suggestion_matches_prefix(name, prefix)
        };
        let compound_trigger = tokens.iter().any(
            |token| matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("COMPOUND")),
        );
        if compound_trigger {
            for idx in 0..tokens.len() {
                if !matches!(tokens.get(idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("TRIGGER"))
                {
                    continue;
                }
                let name_idx = Self::next_non_comment_token_index(tokens, idx + 1)?;
                let name = Self::token_word(tokens.get(name_idx)?)?;
                if matches_prefix(name) {
                    return Some(name.to_string());
                }
            }
        }

        for idx in (0..tokens.len()).rev() {
            if !matches!(tokens.get(idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("PROCEDURE") || word.eq_ignore_ascii_case("FUNCTION"))
            {
                continue;
            }
            let Some(name_idx) = Self::next_non_comment_token_index(tokens, idx + 1) else {
                continue;
            };
            let Some(name) = Self::token_word(tokens.get(name_idx)?) else {
                continue;
            };
            if matches_prefix(name) {
                return Some(name.to_string());
            }
        }
        None
    }

    fn local_schema_type_member_suggestions(
        data: &mut crate::ui::intellisense::IntellisenseData,
        qualifier: &str,
        prefix: &str,
        cursor_in_statement: usize,
        raw_qualifier: Option<&str>,
        analysis: &IntellisenseAnalysis,
    ) -> Vec<String> {
        let Some((type_name, indexed)) = Self::local_schema_type_source_for_qualifier(
            qualifier,
            cursor_in_statement,
            raw_qualifier,
            analysis,
        ) else {
            return Vec::new();
        };

        if indexed {
            let Some(element_type) = data.collection_element_type_for_type(&type_name) else {
                return Vec::new();
            };
            let element_type = element_type.to_string();
            return data.get_member_suggestions(&element_type, prefix, false);
        }

        let mut suggestions = data.get_member_suggestions(&type_name, prefix, false);
        if data.collection_element_type_for_type(&type_name).is_some() {
            suggestions = Self::prepend_local_symbol_suggestions(
                suggestions,
                Self::plsql_collection_method_suggestions(prefix),
            );
        }
        suggestions
    }

    fn own_oracle_type_body_member_suggestions(
        data: &mut crate::ui::intellisense::IntellisenseData,
        prefix: &str,
        deep_ctx: &intellisense_context::CursorContext,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Vec<String> {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return Vec::new();
        }
        let tokens = deep_ctx.statement_tokens.as_ref();
        let end = Self::expected_suggestion_context_end(
            tokens,
            deep_ctx.cursor_token_len,
            !prefix.is_empty(),
        );
        let meaningful = Self::meaningful_tokens_before(tokens, end);
        let type_name = meaningful.windows(3).find_map(|window| match window {
            [SqlToken::Word(type_kw), SqlToken::Word(body), SqlToken::Word(name)]
                if type_kw.eq_ignore_ascii_case("TYPE")
                    && body.eq_ignore_ascii_case("BODY") =>
            {
                Some(name.trim_matches('"').to_string())
            }
            _ => None,
        });
        let Some(type_name) = type_name else {
            return Vec::new();
        };
        let Some(routine_idx) = meaningful.iter().rposition(|token| {
            matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("FUNCTION") || word.eq_ignore_ascii_case("PROCEDURE"))
        }) else {
            return Vec::new();
        };
        if !matches!(
            meaningful.get(routine_idx.saturating_sub(1)),
            Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("MEMBER")
        ) {
            return Vec::new();
        }

        data.get_member_suggestions(&type_name, prefix, false)
    }

    fn mariadb_cursor_parameter_suggestions_from_statement_text(
        statement_text: &str,
        cursor_in_statement: usize,
        prefix: &str,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Vec<String> {
        if !completion_db_type_is_mariadb(db_type) {
            return Vec::new();
        }

        let cursor = cursor_in_statement.min(statement_text.len());
        let spans = super::query_text::tokenize_sql_spanned(statement_text);
        let tokens: Vec<SqlToken> = spans.iter().map(|span| span.token.clone()).collect();
        let prefix_upper = prefix.to_ascii_uppercase();
        let mut suggestions = Vec::new();
        let mut seen = HashSet::new();

        for cursor_keyword_idx in 0..tokens.len() {
            if !matches!(
                tokens.get(cursor_keyword_idx),
                Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("CURSOR")
            ) {
                continue;
            }
            let Some(open_idx) =
                Self::next_non_comment_token_index(&tokens, cursor_keyword_idx + 1)
            else {
                continue;
            };
            if !matches!(tokens.get(open_idx), Some(SqlToken::Symbol(symbol)) if symbol == "(") {
                continue;
            }
            let Some(close_idx) = Self::matching_symbol_token_index(&tokens, open_idx, "(", ")")
            else {
                continue;
            };
            let Some(for_idx) = Self::next_non_comment_token_index(&tokens, close_idx + 1) else {
                continue;
            };
            if !matches!(tokens.get(for_idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("FOR"))
            {
                continue;
            }
            let item_end_idx = Self::cursor_declaration_item_end_token_index(&tokens, for_idx + 1);
            let item_end = item_end_idx
                .and_then(|idx| spans.get(idx).map(|span| span.start))
                .unwrap_or(statement_text.len());
            if cursor <= spans.get(for_idx).map_or(0, |span| span.end) || cursor > item_end {
                continue;
            }
            Self::append_plsql_cursor_parameter_suggestions(
                &tokens,
                open_idx + 1,
                close_idx,
                &prefix_upper,
                &mut suggestions,
                &mut seen,
            );
        }

        suggestions
    }

    fn plsql_cursor_parameter_suggestions_from_statement_text(
        statement_text: &str,
        cursor_in_statement: usize,
        prefix: &str,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Vec<String> {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return Vec::new();
        }

        let cursor = cursor_in_statement.min(statement_text.len());
        let spans = super::query_text::tokenize_sql_spanned(statement_text);
        let tokens: Vec<SqlToken> = spans.iter().map(|span| span.token.clone()).collect();
        let token_ends: Vec<usize> = spans.iter().map(|span| span.end).collect();
        let end = token_ends.partition_point(|token_end| *token_end <= cursor);
        let prefix_upper = prefix.to_ascii_uppercase();
        let mut suggestions = Vec::new();
        let mut seen = HashSet::new();

        let mut idx = 0usize;
        while idx < end {
            if !matches!(tokens.get(idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("CURSOR"))
            {
                idx += 1;
                continue;
            }

            let Some(name_idx) = Self::next_non_comment_token_index(&tokens, idx + 1) else {
                break;
            };
            let Some(open_idx) = Self::next_non_comment_token_index(&tokens, name_idx + 1) else {
                idx += 1;
                continue;
            };
            if !matches!(tokens.get(open_idx), Some(SqlToken::Symbol(symbol)) if symbol == "(") {
                idx += 1;
                continue;
            }

            let Some(close_idx) = Self::matching_symbol_token_index(&tokens, open_idx, "(", ")")
            else {
                idx += 1;
                continue;
            };
            let Some(is_idx) = Self::cursor_declaration_query_is_token_index(&tokens, close_idx + 1)
            else {
                idx = close_idx.saturating_add(1);
                continue;
            };
            let item_end_idx = Self::cursor_declaration_item_end_token_index(&tokens, is_idx + 1);
            let item_end = item_end_idx
                .and_then(|idx| spans.get(idx).map(|span| span.start))
                .unwrap_or(statement_text.len());
            if cursor <= spans.get(is_idx).map_or(0, |span| span.end) || cursor > item_end {
                idx = item_end_idx.unwrap_or(close_idx.saturating_add(1));
                continue;
            }

            Self::append_plsql_cursor_parameter_suggestions(
                &tokens,
                open_idx + 1,
                close_idx,
                &prefix_upper,
                &mut suggestions,
                &mut seen,
            );
            idx = item_end_idx.unwrap_or(close_idx.saturating_add(1));
        }

        suggestions
    }

    fn matching_symbol_token_index(
        tokens: &[SqlToken],
        open_idx: usize,
        open_symbol: &str,
        close_symbol: &str,
    ) -> Option<usize> {
        if !matches!(tokens.get(open_idx), Some(SqlToken::Symbol(symbol)) if symbol == open_symbol) {
            return None;
        }

        let mut depth = 0usize;
        for (idx, token) in tokens.iter().enumerate().skip(open_idx) {
            match token {
                SqlToken::Symbol(symbol) if symbol == open_symbol => {
                    depth = depth.saturating_add(1);
                }
                SqlToken::Symbol(symbol) if symbol == close_symbol => {
                    depth = depth.saturating_sub(1);
                    if depth == 0 {
                        return Some(idx);
                    }
                }
                _ => {}
            }
        }

        None
    }

    fn cursor_declaration_query_is_token_index(tokens: &[SqlToken], start: usize) -> Option<usize> {
        let mut depth = 0usize;
        let mut idx = start;
        while idx < tokens.len() {
            match &tokens[idx] {
                SqlToken::Comment(_) => {}
                SqlToken::Symbol(symbol) if symbol == "(" => depth = depth.saturating_add(1),
                SqlToken::Symbol(symbol) if symbol == ")" => depth = depth.saturating_sub(1),
                SqlToken::Symbol(symbol) if symbol == ";" && depth == 0 => return None,
                SqlToken::Word(word)
                    if depth == 0
                        && (word.eq_ignore_ascii_case("IS")
                            || word.eq_ignore_ascii_case("AS")) =>
                {
                    return Some(idx);
                }
                _ => {}
            }
            idx += 1;
        }

        None
    }

    fn cursor_declaration_item_end_token_index(tokens: &[SqlToken], start: usize) -> Option<usize> {
        let mut depth = 0usize;
        for (idx, token) in tokens.iter().enumerate().skip(start) {
            match token {
                SqlToken::Comment(_) => {}
                SqlToken::Symbol(symbol) if symbol == "(" => depth = depth.saturating_add(1),
                SqlToken::Symbol(symbol) if symbol == ")" => depth = depth.saturating_sub(1),
                SqlToken::Symbol(symbol) if symbol == ";" && depth == 0 => return Some(idx),
                _ => {}
            }
        }

        None
    }

    fn append_plsql_cursor_parameter_suggestions(
        tokens: &[SqlToken],
        start: usize,
        end: usize,
        prefix_upper: &str,
        suggestions: &mut Vec<String>,
        seen: &mut HashSet<String>,
    ) {
        let mut item_start = start;
        let mut depth = 0usize;
        let mut idx = start;
        while idx <= end {
            let at_item_end = idx == end;
            let at_top_level_comma = !at_item_end
                && depth == 0
                && matches!(tokens.get(idx), Some(SqlToken::Symbol(symbol)) if symbol == ",");
            if at_item_end || at_top_level_comma {
                if let Some(name) =
                    Self::plsql_cursor_parameter_name_from_tokens(tokens, item_start, idx)
                {
                    let upper = Self::local_identifier_lookup_upper(&name);
                    if Self::local_symbol_matches_prefix(&name, &upper, prefix_upper)
                        && seen.insert(upper)
                    {
                        suggestions.push(name);
                    }
                }
                item_start = idx.saturating_add(1);
            } else {
                match tokens.get(idx) {
                    Some(SqlToken::Symbol(symbol)) if symbol == "(" => {
                        depth = depth.saturating_add(1);
                    }
                    Some(SqlToken::Symbol(symbol)) if symbol == ")" => {
                        depth = depth.saturating_sub(1);
                    }
                    _ => {}
                }
            }
            idx += 1;
        }
    }

    fn plsql_cursor_parameter_name_from_tokens(
        tokens: &[SqlToken],
        start: usize,
        end: usize,
    ) -> Option<String> {
        tokens
            .get(start..end)?
            .iter()
            .find_map(|token| Self::token_word(token).and_then(Self::local_identifier_suggestion_from_word))
    }

    fn plsql_outer_cursor_for_loop_record_member_suggestions_from_text(
        text_before_cursor: &str,
        qualifier: &str,
        prefix: &str,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<Vec<String>> {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return None;
        }

        let spans = super::query_text::tokenize_sql_spanned(text_before_cursor);
        let tokens: Vec<SqlToken> = spans.into_iter().map(|span| span.token).collect();
        let qualifier_upper = Self::local_identifier_lookup_upper(qualifier);
        if qualifier_upper.is_empty() {
            return None;
        }

        let mut loop_stack = Vec::<Option<(String, Vec<String>)>>::new();
        let mut idx = 0usize;
        while idx < tokens.len() {
            match tokens.get(idx) {
                Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("FOR") => {
                    if let Some((name, members, loop_idx)) =
                        Self::plsql_cursor_for_loop_projection_from_tokens(&tokens, idx)
                    {
                        loop_stack.push(Some((name, members)));
                        idx = loop_idx.saturating_add(1);
                        continue;
                    }
                }
                Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("LOOP") => {
                    if !Self::previous_meaningful_word_is_token(&tokens, idx, "END") {
                        loop_stack.push(None);
                    }
                }
                Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("END") => {
                    if Self::next_meaningful_word_is_token(&tokens, idx + 1, "LOOP") {
                        loop_stack.pop();
                    }
                }
                _ => {}
            }
            idx += 1;
        }

        loop_stack
            .iter()
            .rev()
            .filter_map(Option::as_ref)
            .find_map(|(name, members)| {
                (Self::local_identifier_lookup_upper(name) == qualifier_upper).then(|| {
                    let prefix_upper = Self::local_identifier_lookup_upper(prefix);
                    members
                        .iter()
                        .filter(|member| {
                            let upper = Self::local_identifier_lookup_upper(member);
                            Self::local_symbol_matches_prefix(member, &upper, &prefix_upper)
                        })
                        .cloned()
                        .collect::<Vec<_>>()
                })
            })
    }

    fn qualifier_before_prefix_at_text_end(text_before_cursor: &str, prefix: &str) -> Option<String> {
        let word_start_from_prefix = text_before_cursor.len().checked_sub(prefix.len());
        if let Some(word_start) = word_start_from_prefix {
            if let Some(qualifier) = Self::qualifier_before_word_in_text(text_before_cursor, word_start)
            {
                return Some(qualifier);
            }
        }

        let word_start = word_start_from_prefix.unwrap_or_else(|| {
            let mut word_start = text_before_cursor.len();
            for (idx, ch) in text_before_cursor.char_indices().rev() {
                if ch.is_ascii_alphanumeric() || matches!(ch, '_' | '$' | '#') {
                    word_start = idx;
                } else {
                    break;
                }
            }
            word_start
        });
        Self::simple_unquoted_qualifier_before_word_start(text_before_cursor, word_start)
    }

    fn simple_unquoted_qualifier_before_word_start(text: &str, word_start: usize) -> Option<String> {
        if word_start == 0 || text.as_bytes().get(word_start - 1) != Some(&b'.') {
            return None;
        }
        let dot_idx = word_start - 1;
        let mut qualifier_start = dot_idx;
        while qualifier_start > 0 {
            let byte = text.as_bytes()[qualifier_start - 1];
            if byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'$' | b'#') {
                qualifier_start -= 1;
            } else {
                break;
            }
        }
        (qualifier_start < dot_idx).then(|| text[qualifier_start..dot_idx].to_string())
    }

    fn plsql_cursor_for_loop_projection_from_tokens(
        tokens: &[SqlToken],
        for_idx: usize,
    ) -> Option<(String, Vec<String>, usize)> {
        let name_idx = Self::next_non_comment_token_index(tokens, for_idx + 1)?;
        let name = Self::token_word(tokens.get(name_idx)?)
            .and_then(Self::local_identifier_suggestion_from_word)?;
        let in_idx = Self::next_non_comment_token_index(tokens, name_idx + 1)?;
        if !matches!(tokens.get(in_idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("IN"))
        {
            return None;
        }
        let open_idx = Self::next_non_comment_token_index(tokens, in_idx + 1)?;
        if !matches!(tokens.get(open_idx), Some(SqlToken::Symbol(symbol)) if symbol == "(") {
            return None;
        }
        let close_idx = Self::matching_symbol_token_index(tokens, open_idx, "(", ")")?;
        let loop_idx = Self::next_non_comment_token_index(tokens, close_idx + 1)?;
        if !matches!(tokens.get(loop_idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("LOOP"))
        {
            return None;
        }

        let body_tokens = tokens.get(open_idx + 1..close_idx).unwrap_or(&[]);
        let (mut members, _) = Self::extract_select_projection_members_and_source(body_tokens);
        Self::dedup_column_names_case_insensitive(&mut members);
        Some((name, members, loop_idx))
    }

    fn previous_meaningful_word_is_token(
        tokens: &[SqlToken],
        idx: usize,
        expected: &str,
    ) -> bool {
        Self::previous_non_comment_token_index(tokens, idx)
            .and_then(|idx| Self::token_word(tokens.get(idx)?))
            .is_some_and(|word| word.eq_ignore_ascii_case(expected))
    }

    fn next_meaningful_word_is_token(tokens: &[SqlToken], idx: usize, expected: &str) -> bool {
        Self::next_non_comment_token_index(tokens, idx)
            .and_then(|idx| Self::token_word(tokens.get(idx)?))
            .is_some_and(|word| word.eq_ignore_ascii_case(expected))
    }

    /// Exception names declared in the current block as `name EXCEPTION;`, offered at
    /// an exception-name slot (`RAISE |`, `EXCEPTION WHEN |`). These are declaration
    /// symbols the value-symbol table intentionally leaves out of exception slots, so
    /// scan the block tokens directly for the `<ident> EXCEPTION ;` shape (the section
    /// keyword `EXCEPTION` is preceded by a statement/`;`, never an identifier + `;`).
    fn plsql_block_exception_declarations(
        deep_ctx: &intellisense_context::CursorContext,
        prefix: &str,
    ) -> Vec<String> {
        let prefix_upper = prefix.to_ascii_uppercase();
        let meaningful: Vec<&SqlToken> = deep_ctx
            .statement_tokens
            .as_ref()
            .iter()
            .filter(|token| !matches!(token, SqlToken::Comment(_)))
            .collect();
        let mut seen = std::collections::HashSet::new();
        let mut names: Vec<String> = Vec::new();
        for window in meaningful.windows(3) {
            let [name_token, exception_token, terminator] = window else {
                continue;
            };
            let (SqlToken::Word(name), SqlToken::Word(keyword)) = (name_token, exception_token)
            else {
                continue;
            };
            if !keyword.eq_ignore_ascii_case("EXCEPTION")
                || !matches!(terminator, SqlToken::Symbol(sym) if sym == ";")
                || crate::sql_text::is_sql_keyword_for_db(name, crate::db::DatabaseType::Oracle)
            {
                continue;
            }
            if !name.to_ascii_uppercase().starts_with(&prefix_upper) {
                continue;
            }
            if seen.insert(name.to_ascii_uppercase()) {
                names.push(name.clone());
            }
        }
        names
    }

    fn cursor_is_at_plsql_exception_name_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
    ) -> bool {
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let context_end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        if Self::cursor_is_at_plsql_exception_name(tokens, context_end) {
            return true;
        }
        let statement_tokens = deep_ctx.statement_tokens.as_ref();
        let statement_end = Self::expected_suggestion_context_end(
            statement_tokens,
            deep_ctx.cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::cursor_is_at_plsql_exception_name(statement_tokens, statement_end)
    }

    fn cursor_is_at_rollback_to_savepoint_name_slot(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if Self::unclosed_paren_count(tokens, end) != 0 {
            return false;
        }

        let mysql = crate::sql_text::mysql_compatibility_for_sql("", db_type);
        let words = if !mysql && Self::cursor_in_plsql_executable_block(tokens, end) {
            Self::words_for_plsql_statement_slot(tokens, end)
        } else {
            Self::words_for_keyword_slot(tokens, end)
        };

        matches!(
            words.as_slice(),
            [rollback, to]
                if rollback == "ROLLBACK" && to == "TO"
        ) || matches!(
            words.as_slice(),
            [rollback, to, savepoint]
                if rollback == "ROLLBACK" && to == "TO" && savepoint == "SAVEPOINT"
        ) || matches!(
            words.as_slice(),
            [release, savepoint]
                if release == "RELEASE" && savepoint == "SAVEPOINT"
        )
    }

    fn cursor_is_at_rollback_to_savepoint_name_slot_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let context_end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        if Self::cursor_is_at_rollback_to_savepoint_name_slot(tokens, context_end, db_type) {
            return true;
        }

        let statement_tokens = deep_ctx.statement_tokens.as_ref();
        let statement_end = Self::expected_suggestion_context_end(
            statement_tokens,
            deep_ctx.cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::cursor_is_at_rollback_to_savepoint_name_slot(
            statement_tokens,
            statement_end,
            db_type,
        )
    }

