    fn cursor_is_at_plsql_for_loop_index_slot(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type)
            || !Self::cursor_in_plsql_executable_block(tokens, end)
        {
            return false;
        }

        let visible_end = end.min(tokens.len());
        let next_word = tokens
            .iter()
            .skip(visible_end)
            .find(|token| !matches!(token, SqlToken::Comment(_)))
            .and_then(|token| match token {
                SqlToken::Word(word) => Some(word.as_str()),
                _ => None,
            });
        if !next_word.is_some_and(|word| word.eq_ignore_ascii_case("IN")) {
            return false;
        }

        let toks = Self::meaningful_tokens_before(tokens, visible_end);
        let is_loop_index_word = |token: &SqlToken| match token {
            SqlToken::Word(word) => {
                !crate::sql_text::is_sql_keyword_for_db(word, crate::db::DatabaseType::Oracle)
            }
            _ => false,
        };

        let is_for_loop_head =
            |word: &str| matches!(word.to_ascii_uppercase().as_str(), "FOR" | "FORALL");

        matches!(
            toks.as_slice(),
            [.., SqlToken::Word(for_word)] if is_for_loop_head(for_word)
        ) || matches!(
            toks.as_slice(),
            [.., SqlToken::Word(for_word), index]
                if is_for_loop_head(for_word) && is_loop_index_word(index)
        )
    }

    fn cursor_is_at_plsql_for_loop_index_slot_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let context_end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        if Self::cursor_is_at_plsql_for_loop_index_slot(tokens, context_end, db_type) {
            return true;
        }

        let statement_tokens = deep_ctx.statement_tokens.as_ref();
        let statement_end = Self::expected_suggestion_context_end(
            statement_tokens,
            deep_ctx.cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::cursor_is_at_plsql_for_loop_index_slot(statement_tokens, statement_end, db_type)
    }

    fn plsql_forall_index_suggestions_for_context(
        prefix: &str,
        deep_ctx: &intellisense_context::CursorContext,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Vec<String> {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return Vec::new();
        }
        let tokens = deep_ctx.statement_tokens.as_ref();
        let end = Self::expected_suggestion_context_end(tokens, deep_ctx.cursor_token_len, true)
            .min(tokens.len());
        let segment_start = tokens
            .get(..end)
            .unwrap_or(tokens)
            .iter()
            .rposition(|token| matches!(token, SqlToken::Symbol(symbol) if symbol == ";"))
            .map_or(0, |idx| idx + 1);
        let segment = Self::meaningful_tokens_before(
            tokens.get(segment_start..end).unwrap_or(&[]),
            end.saturating_sub(segment_start),
        );
        let Some(forall_idx) = segment.iter().position(
            |token| matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("FORALL")),
        ) else {
            return Vec::new();
        };
        let Some(SqlToken::Word(index_name)) = segment.get(forall_idx + 1).copied() else {
            return Vec::new();
        };
        if !matches!(
            segment.get(forall_idx + 2),
            Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("IN")
        ) || !segment.get(forall_idx + 3..).unwrap_or(&[]).iter().any(|token| {
            matches!(
                token,
                SqlToken::Word(word)
                    if matches!(
                        word.to_ascii_uppercase().as_str(),
                        "INSERT" | "UPDATE" | "DELETE" | "MERGE" | "EXECUTE"
                    )
            )
        }) || !Self::completion_suggestion_matches_prefix(index_name, prefix)
        {
            return Vec::new();
        }
        vec![index_name.clone()]
    }

    /// PL/SQL declaration-region `TYPE <name> IS|AS |` — the local type-spec
    /// kind. Unlike a schema-level `CREATE TYPE`, a local type can never be an
    /// `OBJECT` (object types are SQL-only), so this is a distinct list from
    /// `CREATE TYPE`'s. `RECORD`/`TABLE OF`/`VARRAY` already complete downstream
    /// from there; `REF CURSOR [RETURN …]` needs its own `REF |` → `CURSOR` step.
    fn expected_plsql_local_type_spec_kind_keyword_candidates(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<&'static [&'static str]> {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type)
            || !Self::cursor_is_in_plsql_declaration_region(tokens, end)
        {
            return None;
        }
        let toks = Self::meaningful_tokens_before(tokens, end);
        let last = toks.len().checked_sub(1)?;
        let is_word = |idx: usize, kw: &str| {
            matches!(toks.get(idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case(kw))
        };
        let is_plain_identifier = |idx: usize| {
            matches!(toks.get(idx), Some(SqlToken::Word(word)) if !Self::is_plsql_non_type_keyword(word))
        };

        if (is_word(last, "IS") || is_word(last, "AS"))
            && last >= 2
            && is_plain_identifier(last - 1)
            && is_word(last - 2, "TYPE")
        {
            return Some(&["RECORD", "TABLE OF", "VARRAY", "REF CURSOR"]);
        }
        if is_word(last, "REF")
            && last >= 3
            && (is_word(last - 1, "IS") || is_word(last - 1, "AS"))
            && is_plain_identifier(last - 2)
            && is_word(last - 3, "TYPE")
        {
            return Some(&["CURSOR"]);
        }
        None
    }

    fn expected_plsql_local_type_spec_kind_keyword_candidates_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<&'static [&'static str]> {
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let context_end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::expected_plsql_local_type_spec_kind_keyword_candidates(tokens, context_end, db_type)
            .or_else(|| {
                let statement_tokens = deep_ctx.statement_tokens.as_ref();
                let statement_end = Self::expected_suggestion_context_end(
                    statement_tokens,
                    deep_ctx.cursor_token_len,
                    exclude_current_identifier_chain,
                );
                Self::expected_plsql_local_type_spec_kind_keyword_candidates(
                    statement_tokens,
                    statement_end,
                    db_type,
                )
            })
    }

    /// Keyword tails of the PL/SQL declaration-item grammars that a bare
    /// word-position scan can't classify — the `CURSOR`/collection-`TYPE`
    /// sub-grammars and the variable `NOT NULL` constraint:
    /// `CURSOR c |`→`IS`/`RETURN`, `CURSOR c IS |`→`SELECT`/`WITH`,
    /// `TYPE t IS TABLE |`→`OF`, `… TABLE OF <type> |`→`INDEX BY`/`NOT NULL`,
    /// `… INDEX BY |`→ the index types, `… VARRAY(n) |`/`REF CURSOR |` tails,
    /// and `v <type> NOT [NULL] |`. Scoped to the declaration *item* containing
    /// the cursor so a keyword from an earlier item (or the enclosing routine
    /// header) can't leak in.
    fn expected_plsql_declaration_tail_keyword_candidates(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<&'static [&'static str]> {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return None;
        }
        let in_declaration_region = Self::cursor_is_in_plsql_declaration_region(tokens, end);
        // The current declaration item: tokens since the last `;`, `DECLARE`, or
        // a routine-header `IS`/`AS` (a `TYPE t IS …`/`CURSOR c IS …` item keeps
        // its own `IS`, so only the `IS`/`AS` completing a pending
        // `FUNCTION`/`PROCEDURE`/`PACKAGE` header is a boundary).
        let visible_end = end.min(tokens.len());
        let mut item_start = 0usize;
        let mut pending_routine_header = false;
        for (idx, token) in tokens.iter().take(visible_end).enumerate() {
            match token {
                SqlToken::Symbol(sym) if sym == ";" => {
                    item_start = idx + 1;
                    pending_routine_header = false;
                }
                SqlToken::Word(word) => match word.to_ascii_uppercase().as_str() {
                    "FUNCTION" | "PROCEDURE" | "PACKAGE" => pending_routine_header = true,
                    "DECLARE" | "BEGIN" => {
                        item_start = idx + 1;
                        pending_routine_header = false;
                    }
                    "IS" | "AS" if pending_routine_header => {
                        item_start = idx + 1;
                        pending_routine_header = false;
                    }
                    _ => {}
                },
                _ => {}
            }
        }
        let item: Vec<String> = tokens
            .get(item_start..visible_end)
            .unwrap_or(&[])
            .iter()
            .filter_map(|token| match token {
                SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
                _ => None,
            })
            .collect();
        if !in_declaration_region
            && !matches!(
                item.first().map(String::as_str),
                Some("TYPE" | "SUBTYPE" | "CURSOR")
            )
        {
            return None;
        }
        let last = item.last().map(String::as_str);
        let has = |keyword: &str| item.iter().any(|word| word == keyword);
        let prev_token_is_close_paren = matches!(
            Self::meaningful_tokens_before(tokens, end).last(),
            Some(SqlToken::Symbol(sym)) if sym == ")"
        );
        let is_keyword = |word: &str| {
            crate::sql_text::is_sql_keyword_for_db(word, crate::db::DatabaseType::Oracle)
        };

        // ---- collection/ref-cursor TYPE sub-grammar ----
        if has("TYPE") || has("SUBTYPE") {
            if matches!(item.as_slice(), [.., ref_word, cur] if ref_word == "REF" && cur == "CURSOR")
            {
                return Some(&["RETURN"]);
            }
            if matches!(item.as_slice(), [.., is_word, table] if is_word == "IS" && table == "TABLE")
            {
                return Some(&["OF"]);
            }
            // `VARRAY(10) |` — the size literal is itself a word token, so
            // anchor on the closing paren with `VARRAY` present and its `OF`
            // still missing.
            if prev_token_is_close_paren && has("VARRAY") && !has("OF") {
                return Some(&["OF"]);
            }
            if last == Some("INDEX") && has("TABLE") && has("OF") {
                return Some(&["BY"]);
            }
            if matches!(item.as_slice(), [.., index, by] if index == "INDEX" && by == "BY") {
                return Some(&["PLS_INTEGER", "BINARY_INTEGER", "VARCHAR2"]);
            }
            // `TABLE OF <type> |` / `VARRAY(n) OF <type> |` — the optional
            // element-constraint / organization tails after a complete type.
            if has("OF")
                && !has("INDEX")
                && !has("NOT")
                && !matches!(last, Some("OF" | "TABLE" | "VARRAY" | "IS" | "AS"))
                && Self::cursor_immediately_follows_complete_operand(tokens, end)
            {
                if has("TABLE") {
                    return Some(&["INDEX BY", "NOT NULL"]);
                }
                if has("VARRAY") {
                    return Some(&["NOT NULL"]);
                }
            }
            if last == Some("NOT") {
                return Some(&["NULL"]);
            }
            if has("INDEX") || has("NOT") {
                return Some(&[]);
            }
            return None;
        }

        // ---- CURSOR declaration sub-grammar (not the `REF CURSOR` type) ----
        if item.first().is_some_and(|head| head == "CURSOR") {
            let after = &item[1..];
            let past_is = after.iter().any(|word| word == "IS");
            match after {
                // `CURSOR c [(params)] [RETURN t] IS |` — the query begins.
                [name, .., is_word] if !is_keyword(name) && is_word == "IS" => {
                    return Some(&["SELECT", "WITH"])
                }
                // `CURSOR c |` (or `CURSOR c (params) |`) — the spec tail. Once
                // `IS` is present the item is inside its query, whose parens
                // must not re-offer the spec keywords.
                [name] if !is_keyword(name) => return Some(&["IS", "RETURN"]),
                [name, ..] if !is_keyword(name) && !past_is && prev_token_is_close_paren => {
                    return Some(&["IS", "RETURN"])
                }
                _ => return None,
            }
        }

        // ---- plain variable/constant item: `v <type> NOT [NULL] |` ----
        if item
            .first()
            .is_some_and(|head| !is_keyword(head))
            && item.len() >= 2
            && !has("PRAGMA")
        {
            if last == Some("NOT") {
                return Some(&["NULL"]);
            }
            if matches!(item.as_slice(), [.., not, null] if not == "NOT" && null == "NULL") {
                return Some(&["DEFAULT"]);
            }
        }
        None
    }

