    fn expected_query_clause_continuation_keywords_for_any_complete_phase(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> &'static [&'static str] {
        use intellisense_context::SqlPhase;

        let visible_end = end.min(tokens.len());
        let visible_tokens = &tokens[..visible_end];
        let toks = Self::meaningful_tokens_before(visible_tokens, visible_end);
        let mut phase = None;
        let mut idx = 0;
        while idx < toks.len() {
            if let SqlToken::Word(word) = &toks[idx] {
                let upper = word.to_ascii_uppercase();
                let next_upper = toks.get(idx + 1).and_then(|token| match token {
                    SqlToken::Word(next) => Some(next.to_ascii_uppercase()),
                    _ => None,
                });
                match upper.as_str() {
                    "FROM" | "JOIN" | "ON" | "USING" => phase = Some(SqlPhase::FromClause),
                    "WHERE" => phase = Some(SqlPhase::WhereClause),
                    "HAVING" => phase = Some(SqlPhase::HavingClause),
                    "GROUP" if next_upper.as_deref() == Some("BY") => {
                        phase = Some(SqlPhase::GroupByClause);
                        idx += 1;
                    }
                    "ORDER" if next_upper.as_deref() == Some("BY") => {
                        phase = Some(SqlPhase::OrderByClause);
                        idx += 1;
                    }
                    "CONNECT" if next_upper.as_deref() == Some("BY") => {
                        phase = Some(SqlPhase::ConnectByClause);
                        idx += 1;
                    }
                    "START" if next_upper.as_deref() == Some("WITH") => {
                        phase = Some(SqlPhase::StartWithClause);
                        idx += 1;
                    }
                    _ => {}
                }
            }
            idx += 1;
        }

        phase
            .map(|phase| {
                Self::expected_query_clause_continuation_keywords(
                    visible_tokens,
                    visible_end,
                    phase,
                    db_type,
                )
            })
            .unwrap_or(&[])
    }

    fn expected_common_predicate_keyword_candidates(
        tokens: &[SqlToken],
        end: usize,
        phase: intellisense_context::SqlPhase,
        db_type: Option<crate::db::DatabaseType>,
        expr_keyword_ctx: Option<ExpressionKeywordContext>,
    ) -> &'static [&'static str] {
        let mysql = crate::sql_text::mysql_compatibility_for_sql("", db_type);
        if !matches!(
            phase,
            intellisense_context::SqlPhase::WhereClause
                | intellisense_context::SqlPhase::JoinCondition
                | intellisense_context::SqlPhase::HavingClause
                | intellisense_context::SqlPhase::ConnectByClause
                | intellisense_context::SqlPhase::StartWithClause
        ) {
            return &[];
        }
        if mysql
            && matches!(
                phase,
                intellisense_context::SqlPhase::ConnectByClause
                    | intellisense_context::SqlPhase::StartWithClause
            )
        {
            return &[];
        }

        let toks = Self::meaningful_tokens_before(tokens, end);
        if matches!(toks.last(), Some(SqlToken::Symbol(sym)) if sym == "(") {
            let prev_word = toks.iter().rev().skip(1).find_map(|token| match token {
                SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
                _ => None,
            });
            if matches!(
                prev_word.as_deref(),
                Some("IN" | "EXISTS" | "ANY" | "SOME" | "ALL")
            ) {
                return &["SELECT", "WITH"];
            }
        }

        if expr_keyword_ctx.is_some_and(|ctx| ctx.follows_like_pattern) {
            return &["ESCAPE", "AND", "OR"];
        }

        let words = Self::previous_meaningful_words_upper(tokens, end, 3);
        if matches!(words.as_slice(), [.., order, siblings] if order == "ORDER" && siblings == "SIBLINGS")
        {
            return &[];
        }

        if Self::cursor_follows_complete_predicate(tokens, end) {
            return &["AND", "OR"];
        }

        if matches!(
            words.last().map(String::as_str),
            Some("MEMBER" | "SUBMULTISET")
        ) {
            return &["OF"];
        }

        let follows_comparison_operator = toks
            .last()
            .is_some_and(|token| matches!(token, SqlToken::Symbol(sym) if matches!(sym.as_str(), "=" | ">" | "<" | ">=" | "<=" | "<>" | "!=")));

        const AFTER_OPERAND_PREDICATE_KEYWORDS: &[&str] = &[
            "IS",
            "IN",
            "LIKE",
            "BETWEEN",
            "NOT",
            "MEMBER OF",
            "SUBMULTISET OF",
        ];
        const AFTER_OPERAND_PREDICATE_KEYWORDS_NO_COLLECTION: &[&str] =
            &["IS", "IN", "LIKE", "BETWEEN", "NOT", "MEMBER OF"];
        const MYSQL_AFTER_OPERAND_PREDICATE_KEYWORDS: &[&str] =
            &["IS", "IN", "LIKE", "BETWEEN", "NOT"];
        const MYSQL_AFTER_COMPARISON_OPERATOR_KEYWORDS: &[&str] = &[
            "ALL",
            "ANY",
            "SOME",
            "CASE",
            "CAST",
            "EXISTS",
            "NOT",
            "NULL",
            "TRUE",
            "FALSE",
            "UNKNOWN",
            "INTERVAL",
            "DATE",
            "TIMESTAMP",
            "TIME",
        ];
        const MYSQL_OPERAND_START_KEYWORDS: &[&str] = &[
            "CASE",
            "CAST",
            "EXISTS",
            "NOT",
            "NULL",
            "TRUE",
            "FALSE",
            "UNKNOWN",
            "INTERVAL",
            "DATE",
            "TIMESTAMP",
            "TIME",
        ];

        match expr_keyword_ctx.and_then(|ctx| ctx.follows_operand) {
            Some(true) if mysql => MYSQL_AFTER_OPERAND_PREDICATE_KEYWORDS,
            Some(true) => match expr_keyword_ctx
                .map(|ctx| ctx.prev_operand_type)
                .unwrap_or(PrecedingOperandType::Unknown)
            {
                PrecedingOperandType::Collection | PrecedingOperandType::Unknown => {
                    AFTER_OPERAND_PREDICATE_KEYWORDS
                }
                _ => AFTER_OPERAND_PREDICATE_KEYWORDS_NO_COLLECTION,
            },
            Some(false)
                if phase == intellisense_context::SqlPhase::ConnectByClause
                    && matches!(words.as_slice(), [.., connect, by] if connect == "CONNECT" && by == "BY") =>
            {
                &[
                    "NOCYCLE",
                    "PRIOR",
                    "LEVEL",
                    "CONNECT_BY_ROOT",
                    "CONNECT_BY_ISCYCLE",
                    "CONNECT_BY_ISLEAF",
                    "CASE",
                    "CAST",
                    "EXISTS",
                    "NOT",
                    "NULL",
                    "TRUE",
                    "FALSE",
                    "UNKNOWN",
                    "INTERVAL",
                    "DATE",
                    "TIMESTAMP",
                    "TIME",
                    "ROWNUM",
                    "ROWID",
                ]
            }
            Some(false) if phase == intellisense_context::SqlPhase::ConnectByClause => &[
                "PRIOR",
                "LEVEL",
                "CONNECT_BY_ROOT",
                "CONNECT_BY_ISCYCLE",
                "CONNECT_BY_ISLEAF",
                "CASE",
                "CAST",
                "EXISTS",
                "NOT",
                "NULL",
                "TRUE",
                "FALSE",
                "UNKNOWN",
                "INTERVAL",
                "DATE",
                "TIMESTAMP",
                "TIME",
                "ROWNUM",
                "ROWID",
            ],
            Some(false) if mysql && follows_comparison_operator => {
                MYSQL_AFTER_COMPARISON_OPERATOR_KEYWORDS
            }
            Some(false) if follows_comparison_operator => &[
                "ALL",
                "ANY",
                "SOME",
                "CASE",
                "CAST",
                "EXISTS",
                "NOT",
                "NULL",
                "TRUE",
                "FALSE",
                "UNKNOWN",
                "INTERVAL",
                "DATE",
                "TIMESTAMP",
                "TIME",
                "ROWNUM",
                "ROWID",
            ],
            Some(false) if mysql => MYSQL_OPERAND_START_KEYWORDS,
            Some(false) => &[
                "CASE",
                "CAST",
                "EXISTS",
                "NOT",
                "NULL",
                "TRUE",
                "FALSE",
                "UNKNOWN",
                "INTERVAL",
                "DATE",
                "TIMESTAMP",
                "TIME",
                "ROWNUM",
                "ROWID",
            ],
            None => &[],
        }
    }

    /// A table-clause construct whose *result is the table source* — `… PIVOT
    /// (…)`, `… UNPIVOT (…)`, `… MATCH_RECOGNIZE (…)` — is a complete FROM relation
    /// once its body paren closes (the relation no longer ends in an identifier).
    /// Detected by matching the trailing `)` to its `(` and checking the
    /// introducing keyword, so an `ON (…)`/`IN (…)`/grouping paren is not mistaken.
    fn cursor_follows_complete_table_clause_construct(toks: &[&SqlToken]) -> bool {
        if !matches!(toks.last(), Some(SqlToken::Symbol(sym)) if *sym == ")") {
            return false;
        }
        let mut depth = 0i32;
        let mut open_idx = None;
        for (idx, token) in toks.iter().enumerate().rev() {
            match token {
                SqlToken::Symbol(sym) if sym == ")" => depth += 1,
                SqlToken::Symbol(sym) if sym == "(" => {
                    depth -= 1;
                    if depth == 0 {
                        open_idx = Some(idx);
                        break;
                    }
                }
                _ => {}
            }
        }
        matches!(
            open_idx
                .and_then(|idx| idx.checked_sub(1))
                .and_then(|idx| toks.get(idx)),
            Some(SqlToken::Word(word))
                if matches!(
                    word.to_ascii_uppercase().as_str(),
                    "PIVOT" | "UNPIVOT" | "MATCH_RECOGNIZE"
                )
        )
    }

    /// Whether the token at `idx` (or the boundary `None`) is a FROM-list slot
    /// introducer — the position where a fresh table source begins: the `FROM`
    /// keyword, a `,`, a JOIN keyword, `APPLY`/`LATERAL`, the start of input, or an
    /// enclosing `(`.
    fn token_introduces_from_list_source(toks: &[&SqlToken], idx: Option<usize>) -> bool {
        match idx.and_then(|i| toks.get(i)) {
            None => true,
            Some(SqlToken::Symbol(sym)) => matches!(sym.as_str(), "(" | ","),
            Some(SqlToken::Word(word)) => matches!(
                word.to_ascii_uppercase().as_str(),
                "FROM"
                    | "JOIN"
                    | "INNER"
                    | "LEFT"
                    | "RIGHT"
                    | "FULL"
                    | "CROSS"
                    | "NATURAL"
                    | "OUTER"
                    | "APPLY"
                    | "LATERAL"
                    | "STRAIGHT_JOIN"
            ),
            _ => false,
        }
    }

    /// Whether the `)` at `close_idx` in `toks` closes a parenthesised table source
    /// at a FROM-list position — a derived table `(SELECT …)`, a parenthesised
    /// join / table reference, or a table function (`TABLE(coll)`, `XMLTABLE(…)`,
    /// `JSON_TABLE(…)`, a pipelined UDF `pkg.f(x)`). Identified by the matching `(`
    /// sitting directly at a FROM-list slot (derived/parenthesised source) or being
    /// the argument list of a (possibly dotted) function name that itself sits at a
    /// FROM-list slot. Since the caller is already in the FROM-clause phase, this is
    /// what distinguishes such a source from a post-table modifier (`t SAMPLE(n)`,
    /// `t PARTITION(p)` — the name follows the *table*, not a FROM-list slot) or a
    /// predicate / grouping paren.
    fn paren_closes_from_list_table_source(toks: &[&SqlToken], close_idx: usize) -> bool {
        if !matches!(toks.get(close_idx), Some(SqlToken::Symbol(sym)) if *sym == ")") {
            return false;
        }
        let mut depth = 0i32;
        let mut open_idx = None;
        for idx in (0..=close_idx).rev() {
            match toks[idx] {
                SqlToken::Symbol(sym) if sym == ")" => depth += 1,
                SqlToken::Symbol(sym) if sym == "(" => {
                    depth -= 1;
                    if depth == 0 {
                        open_idx = Some(idx);
                        break;
                    }
                }
                _ => {}
            }
        }
        let Some(open_idx) = open_idx else {
            return false;
        };
        let before = open_idx.checked_sub(1);
        // Derived table / parenthesised source: the `(` is directly at a FROM-list slot.
        if Self::token_introduces_from_list_source(toks, before) {
            return true;
        }
        // Table function: the `(` is the argument list of a (possibly dotted) name
        // whose head sits at a FROM-list slot. Walk back over `name (. name)*`.
        let mut idx = match before {
            Some(idx) if matches!(toks.get(idx), Some(SqlToken::Word(_))) => idx,
            _ => return false,
        };
        loop {
            match idx.checked_sub(1).and_then(|i| toks.get(i)) {
                Some(SqlToken::Symbol(sym)) if sym == "." => {
                    // Skip the dot and its qualifier word, then continue.
                    let Some(q) = idx.checked_sub(2) else {
                        return false;
                    };
                    if !matches!(toks.get(q), Some(SqlToken::Word(_))) {
                        return false;
                    }
                    idx = q;
                }
                other => {
                    let _ = other;
                    return Self::token_introduces_from_list_source(toks, idx.checked_sub(1));
                }
            }
        }
    }

    /// Whether the `)` at `close_idx` closes a *post-table modifier* — Oracle's
    /// partition-extension (`PARTITION (…)`, `SUBPARTITION (…)`, optionally `… FOR
    /// (…)`) or row-sampling (`SAMPLE [BLOCK] (…)`, `TABLESAMPLE [method] (…)`)
    /// clause. Such a clause attaches to a table reference *without* introducing a
    /// new FROM-list source, so the relation is just as complete as the bare `FROM t
    /// |` — the same continuation follows. Identified by the modifier keyword that
    /// introduces the paren being preceded by a table reference (an identifier word,
    /// or another stacked modifier). A table-function call (`FROM sample(10)`) has a
    /// FROM-list introducer there instead of a name, so it is not mistaken for one.
    fn paren_closes_post_table_modifier(toks: &[&SqlToken], close_idx: usize) -> bool {
        let mut close_idx = close_idx;
        loop {
            if !matches!(toks.get(close_idx), Some(SqlToken::Symbol(sym)) if *sym == ")") {
                return false;
            }
            // Match the trailing `)` to its `(`.
            let mut depth = 0i32;
            let mut open_idx = None;
            for idx in (0..=close_idx).rev() {
                match toks[idx] {
                    SqlToken::Symbol(sym) if sym == ")" => depth += 1,
                    SqlToken::Symbol(sym) if sym == "(" => {
                        depth -= 1;
                        if depth == 0 {
                            open_idx = Some(idx);
                            break;
                        }
                    }
                    _ => {}
                }
            }
            let Some(open_idx) = open_idx else {
                return false;
            };
            // Identify the modifier's lead keyword (the first token of the construct that
            // owns this paren). `None` means the paren is not a post-table modifier.
            let Some(lead_idx) = Self::post_table_modifier_lead(toks, open_idx) else {
                return false;
            };
            // The modifier must attach to a table reference: the preceding token is an
            // identifier word (the table name / its dotted tail) or another stacked
            // post-table modifier — not a FROM-list introducer (which would make the
            // paren a table-function argument list, e.g. `FROM sample(10)`).
            let Some(name_idx) = lead_idx.checked_sub(1) else {
                return false;
            };
            match toks.get(name_idx) {
                Some(SqlToken::Word(w)) => {
                    return !Self::word_breaks_from_relation_tail(&w.to_ascii_uppercase())
                }
                Some(SqlToken::Symbol(sym)) if sym == ")" => close_idx = name_idx,
                _ => return false,
            }
        }
    }

    /// Given the index of a post-table modifier's opening `(`, return the index of
    /// the construct's lead keyword (so the caller can verify it attaches to a table
    /// reference), or `None` if the paren is not a recognised post-table modifier.
    /// Covers the Oracle/ANSI sampling & partition modifiers (`PARTITION (…)`,
    /// `SAMPLE [BLOCK] (…)`, `TABLESAMPLE BERNOULLI (…)`, `PARTITION FOR (…)`) and
    /// the MySQL index hint (`{USE|IGNORE|FORCE} {INDEX|KEY} [FOR {JOIN | ORDER BY |
    /// GROUP BY}] (index_list)`) — its closing `)` likewise leaves the relation
    /// complete, so the query continuation follows.
    fn post_table_modifier_lead(toks: &[&SqlToken], open_idx: usize) -> Option<usize> {
        let word_at = |i: usize| match toks.get(i) {
            Some(SqlToken::Word(w)) => Some(w.to_ascii_uppercase()),
            _ => None,
        };
        let cur = open_idx.checked_sub(1)?;
        let w = word_at(cur)?;
        let is_lead =
            |w: &str| matches!(w, "PARTITION" | "SUBPARTITION" | "SAMPLE" | "TABLESAMPLE");
        // Oracle/ANSI modifier: the lead keyword directly, or one method/`FOR` filler
        // (`SAMPLE BLOCK (…)`, `TABLESAMPLE BERNOULLI (…)`, `PARTITION FOR (…)`).
        if is_lead(&w) {
            return Some(cur);
        }
        if matches!(w.as_str(), "FOR" | "BLOCK" | "BERNOULLI" | "SYSTEM") {
            if let Some(prev) = cur.checked_sub(1) {
                if word_at(prev).is_some_and(|pw| is_lead(&pw)) {
                    return Some(prev);
                }
            }
        }
        // MySQL index hint: walk back from the word before `(` over an optional `FOR
        // {JOIN | ORDER BY | GROUP BY}` purpose, then the mandatory `INDEX`/`KEY`, to
        // the `USE`/`IGNORE`/`FORCE` lead.
        let nb = |d: usize| open_idx.checked_sub(d).and_then(word_at);
        let is_hint_lead =
            |w: &Option<String>| matches!(w.as_deref(), Some("USE" | "IGNORE" | "FORCE"));
        let is_index = |w: &Option<String>| matches!(w.as_deref(), Some("INDEX" | "KEY"));
        let (w1, w2, w3, w4, w5) = (nb(1), nb(2), nb(3), nb(4), nb(5));
        if is_index(&w1) && is_hint_lead(&w2) {
            return open_idx.checked_sub(2); // `{USE|…} {INDEX|KEY} (`
        }
        if w1.as_deref() == Some("JOIN")
            && w2.as_deref() == Some("FOR")
            && is_index(&w3)
            && is_hint_lead(&w4)
        {
            return open_idx.checked_sub(4); // `… INDEX FOR JOIN (`
        }
        if w1.as_deref() == Some("BY")
            && matches!(w2.as_deref(), Some("ORDER" | "GROUP"))
            && w3.as_deref() == Some("FOR")
            && is_index(&w4)
            && is_hint_lead(&w5)
        {
            return open_idx.checked_sub(5); // `… INDEX FOR ORDER|GROUP BY (`
        }
        None
    }

    fn cursor_is_inside_post_table_modifier_value_slot_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
    ) -> bool {
        let tokens = deep_ctx.statement_tokens.as_ref();
        let end = Self::expected_suggestion_context_end(
            tokens,
            deep_ctx.cursor_token_len,
            exclude_current_identifier_chain,
        );
        let toks = Self::meaningful_tokens_before(tokens, end);
        let mut stack = Vec::new();
        for (idx, token) in toks.iter().enumerate() {
            match token {
                SqlToken::Symbol(sym) if sym == "(" => stack.push(idx),
                SqlToken::Symbol(sym) if sym == ")" => {
                    stack.pop();
                }
                _ => {}
            }
        }
        let Some(open_idx) = stack.last().copied() else {
            return false;
        };
        let Some(lead_idx) = Self::post_table_modifier_lead(&toks, open_idx) else {
            return false;
        };
        let Some(name_idx) = lead_idx.checked_sub(1) else {
            return false;
        };
        match toks.get(name_idx) {
            Some(SqlToken::Word(word)) => {
                !Self::word_breaks_from_relation_tail(&word.to_ascii_uppercase())
            }
            Some(SqlToken::Symbol(sym)) if sym == ")" => {
                Self::paren_closes_post_table_modifier(&toks, name_idx)
            }
            _ => false,
        }
    }

    fn cursor_is_after_complete_from_relation(tokens: &[SqlToken], end: usize) -> bool {
        let toks = Self::meaningful_tokens_before(tokens, end);
        // A closed table-clause construct (`… PIVOT (…) |`, `… MATCH_RECOGNIZE
        // (…) |`) completes the relation even though it ends in `)` rather than an
        // identifier — so the query continuation (`WHERE`/`JOIN`/…) follows it.
        if Self::cursor_follows_complete_table_clause_construct(&toks) {
            return true;
        }
        // `MODEL` is a table clause too, but unlike the single-body constructs
        // above it closes through its terminal `RULES (...)` sub-clause.
        if Self::table_clause_construct_has_table_source_anchor(tokens, end, "MODEL")
            && Self::construct_top_level_parenthesized_clause_is_complete(
                tokens, end, "MODEL", "RULES",
            )
        {
            return true;
        }
        // A parenthesised table source with no trailing alias (`FROM (SELECT …) |`,
        // `FROM TABLE(coll) |`) ends in `)` — it is just as complete as a named
        // relation, so the same continuation follows.
        if Self::paren_closes_from_list_table_source(&toks, toks.len().wrapping_sub(1)) {
            return true;
        }
        // A post-table modifier (`FROM t PARTITION (p) |`, `FROM t SAMPLE (10) |`)
        // also ends in `)` but leaves the relation complete — same continuation.
        if Self::paren_closes_post_table_modifier(&toks, toks.len().wrapping_sub(1)) {
            return true;
        }
        // The reference (or its implicit alias) must be complete: the last token
        // is a plain identifier word, never a separator or a clause keyword.
        let Some(SqlToken::Word(last)) = toks.last() else {
            return false;
        };
        if Self::word_breaks_from_relation_tail(last) {
            return false;
        }
        // Walk back over the reference's own words / dotted-name separators to the
        // structural token that introduces the list slot: `FROM` or a `,` means a
        // complete comma-list reference; a `)` means an aliased parenthesised source
        // (`FROM (SELECT …) v |`, `FROM (SELECT …) AS v |`); anything else (a
        // `(`, an operator) belongs to another slot and is left untouched.
        let mut idx = toks.len() - 1;
        while idx > 0 {
            idx -= 1;
            match &toks[idx] {
                SqlToken::Word(word) if word.eq_ignore_ascii_case("FROM") => return true,
                SqlToken::Symbol(sym) if sym == "," => return true,
                SqlToken::Symbol(sym) if sym == ")" => {
                    return Self::paren_closes_from_list_table_source(&toks, idx)
                        || Self::paren_closes_post_table_modifier(&toks, idx)
                }
                SqlToken::Word(_) => {} // part of the table name or its implicit alias
                SqlToken::Symbol(sym) if sym == "." => {} // dotted-name separator
                _ => return false,
            }
        }
        false
    }

    fn word_breaks_from_relation_tail(word: &str) -> bool {
        matches!(
            word.to_ascii_uppercase().as_str(),
            "FROM"
                | "WHERE"
                | "GROUP"
                | "HAVING"
                | "ORDER"
                | "CONNECT"
                | "START"
                | "JOIN"
                | "INTO"
                | "INNER"
                | "LEFT"
                | "RIGHT"
                | "FULL"
                | "CROSS"
                | "NATURAL"
                | "STRAIGHT_JOIN"
                | "OUTER"
                | "ON"
                | "USING"
                | "FOR"
                | "OFFSET"
                | "FETCH"
                | "LIMIT"
                | "UNION"
                | "INTERSECT"
                | "MINUS"
                | "EXCEPT"
                | "APPLY"
                | "LATERAL"
                | "AS"
        )
    }

    fn cursor_is_after_complete_from_relation_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
    ) -> bool {
        if !matches!(deep_ctx.phase, intellisense_context::SqlPhase::FromClause) {
            return false;
        }
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::cursor_is_after_complete_from_relation(tokens, end)
    }

    /// True when the cursor sits right after the *complete* target name of an
    /// `ALTER TABLE <name> |` statement (including a qualified `schema.name`). The
    /// table name is already given, so what follows is an alteration clause
    /// (`ADD`/`MODIFY`/`DROP`/`RENAME`/…), never another relation; the phase
    /// machine leaves the cursor in the `ALTER TABLE` target phase (`IntoClause`),
    /// where the relation list would otherwise be offered a second time. Anchored
    /// on a leading `ALTER TABLE` so the name slot itself (`ALTER TABLE |`, last
    /// token `TABLE`) still completes relations, and so the `IntoClause` of an
    /// `INSERT`/`CREATE TABLE AS`/`COMMENT ON` is untouched.
    fn cursor_is_after_complete_alter_table_target(tokens: &[SqlToken], end: usize) -> bool {
        let toks = Self::meaningful_tokens_before(tokens, end);
        let Some(SqlToken::Word(last)) = toks.last() else {
            return false;
        };
        if Self::token_is_language_keyword(&last.to_ascii_uppercase()) {
            return false;
        }
        // Walk back over the (possibly dotted) target name to the `TABLE` keyword,
        // which must itself be introduced by `ALTER`.
        let mut idx = toks.len() - 1;
        while idx > 0 {
            idx -= 1;
            match &toks[idx] {
                SqlToken::Word(word) if word.eq_ignore_ascii_case("TABLE") => {
                    return idx > 0
                        && matches!(
                            toks.get(idx - 1),
                            Some(SqlToken::Word(head)) if head.eq_ignore_ascii_case("ALTER")
                        );
                }
                SqlToken::Word(_) => {} // part of the target name
                SqlToken::Symbol(sym) if sym == "." => {} // dotted-name separator
                _ => return false,
            }
        }
        false
    }

    fn alter_table_tail_words_after_target(tokens: &[SqlToken], end: usize) -> Option<Vec<String>> {
        let toks = Self::meaningful_tokens_before(tokens, end);
        if !matches!(toks.first(), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("ALTER"))
            || !matches!(toks.get(1), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("TABLE"))
        {
            return None;
        }

        let mut idx = 2;
        if !matches!(toks.get(idx), Some(SqlToken::Word(_))) {
            return None;
        }
        idx += 1;

        while idx + 1 < toks.len()
            && matches!(toks.get(idx), Some(SqlToken::Symbol(sym)) if sym == ".")
            && matches!(toks.get(idx + 1), Some(SqlToken::Word(_)))
        {
            idx += 2;
        }

        let mut depth = 0i32;
        let mut words = Vec::new();
        for token in toks.get(idx..).unwrap_or(&[]) {
            match token {
                SqlToken::Symbol(sym) if sym == "(" || sym == "[" => depth += 1,
                SqlToken::Symbol(sym) if sym == ")" || sym == "]" => depth = (depth - 1).max(0),
                SqlToken::Symbol(sym) if depth == 0 && sym == "," => words.clear(),
                SqlToken::Word(word) => words.push(word.to_ascii_uppercase()),
                _ => {}
            }
        }
        Some(words)
    }

    fn create_index_tail_tokens_after_name(
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<Vec<&SqlToken>> {
        let toks = Self::meaningful_tokens_before(tokens, end);
        if !matches!(toks.first(), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("CREATE"))
        {
            return None;
        }

        let index_idx = toks.iter().position(
            |token| matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("INDEX")),
        )?;
        let mut idx = index_idx + 1;
        if matches!(
            toks.get(idx..idx + 3),
            Some([SqlToken::Word(if_kw), SqlToken::Word(not_kw), SqlToken::Word(exists_kw)])
                if if_kw.eq_ignore_ascii_case("IF")
                    && not_kw.eq_ignore_ascii_case("NOT")
                    && exists_kw.eq_ignore_ascii_case("EXISTS")
        ) {
            idx += 3;
        }
        if !matches!(toks.get(idx), Some(SqlToken::Word(_))) {
            return None;
        }
        idx += 1;
        while idx + 1 < toks.len()
            && matches!(toks.get(idx), Some(SqlToken::Symbol(sym)) if sym == ".")
            && matches!(toks.get(idx + 1), Some(SqlToken::Word(_)))
        {
            idx += 2;
        }
        Some(toks.get(idx..).unwrap_or(&[]).to_vec())
    }

    fn cursor_is_after_create_index_on_target_before_column_list(
        tokens: &[SqlToken],
        end: usize,
    ) -> bool {
        let Some(tail) = Self::create_index_tail_tokens_after_name(tokens, end) else {
            return false;
        };
        let mut depth = 0i32;
        let mut on_idx = None;
        for (idx, token) in tail.iter().enumerate() {
            match token {
                SqlToken::Symbol(sym) if sym == "(" || sym == "[" => depth += 1,
                SqlToken::Symbol(sym) if sym == ")" || sym == "]" => depth = (depth - 1).max(0),
                SqlToken::Word(word) if depth == 0 && word.eq_ignore_ascii_case("ON") => {
                    on_idx = Some(idx);
                }
                _ => {}
            }
        }
        let Some(on_idx) = on_idx else {
            return false;
        };
        let after_on = tail.get(on_idx + 1..).unwrap_or(&[]);
        if after_on.is_empty() {
            return false;
        }

        let mut expect_word = true;
        let mut saw_word = false;
        for token in after_on {
            match token {
                SqlToken::Word(_) if expect_word => {
                    saw_word = true;
                    expect_word = false;
                }
                SqlToken::Symbol(sym) if !expect_word && sym == "." => expect_word = true,
                _ => return false,
            }
        }
        saw_word && !expect_word
    }

    fn create_table_tail_tokens_after_name(
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<Vec<&SqlToken>> {
        let toks = Self::meaningful_tokens_before(tokens, end);
        if !matches!(toks.first(), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("CREATE"))
        {
            return None;
        }

        let table_idx = toks.iter().position(
            |token| matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("TABLE")),
        )?;
        let mut idx = table_idx + 1;
        if matches!(
            toks.get(idx..idx + 3),
            Some([SqlToken::Word(if_kw), SqlToken::Word(not_kw), SqlToken::Word(exists_kw)])
                if if_kw.eq_ignore_ascii_case("IF")
                    && not_kw.eq_ignore_ascii_case("NOT")
                    && exists_kw.eq_ignore_ascii_case("EXISTS")
        ) {
            idx += 3;
        }
        if !matches!(toks.get(idx), Some(SqlToken::Word(_))) {
            return None;
        }
        idx += 1;
        while idx + 1 < toks.len()
            && matches!(toks.get(idx), Some(SqlToken::Symbol(sym)) if sym == ".")
            && matches!(toks.get(idx + 1), Some(SqlToken::Word(_)))
        {
            idx += 2;
        }
        Some(toks.get(idx..).unwrap_or(&[]).to_vec())
    }

    fn tail_has_closed_top_level_paren(tokens: &[&SqlToken]) -> bool {
        let mut depth = 0i32;
        for token in tokens {
            match token {
                SqlToken::Symbol(sym) if sym == "(" || sym == "[" => depth += 1,
                SqlToken::Symbol(sym) if sym == ")" || sym == "]" => {
                    depth = (depth - 1).max(0);
                    if depth == 0 {
                        return true;
                    }
                }
                _ => {}
            }
        }
        false
    }

    fn cursor_is_after_complete_alter_table_target_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
    ) -> bool {
        if !matches!(deep_ctx.phase, intellisense_context::SqlPhase::IntoClause) {
            return false;
        }
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::cursor_is_after_complete_alter_table_target(tokens, end)
    }

    /// True when the cursor is at the type slot of a column definition in
    /// `CREATE TABLE (... col |)` or `ALTER TABLE ... ADD|MODIFY|CHANGE ... col |`.
    fn cursor_is_at_ddl_column_type(tokens: &[SqlToken], end: usize) -> bool {
        let toks = Self::meaningful_tokens_before(tokens, end);
        if toks.len() < 3 {
            return false;
        }
        let word_upper = |idx: usize| match toks.get(idx) {
            Some(SqlToken::Word(word)) => Some(word.to_ascii_uppercase()),
            _ => None,
        };
        let is_symbol = |idx: usize, sym: &str| matches!(toks.get(idx), Some(SqlToken::Symbol(value)) if value == sym);
        let any_word = |kw: &str| {
            toks.iter()
                .any(|token| matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case(kw)))
        };

        // The cursor must follow a plain column-name identifier.
        let last = toks.len() - 1;
        let last_is_plain_identifier = matches!(toks.get(last), Some(SqlToken::Word(word)) if !Self::is_ddl_structural_keyword(word));
        if !last_is_plain_identifier {
            return false;
        }

        let starts_with = |kw: &str| word_upper(0).as_deref() == Some(kw);

        if starts_with("ALTER") && any_word("TABLE") {
            // `ADD col |`, `MODIFY col |`, `ADD|MODIFY|CHANGE COLUMN col |`,
            // `CHANGE old new |`.
            let w2 = word_upper(last - 1);
            let w3 = word_upper(last - 2);
            if matches!(w2.as_deref(), Some("ADD") | Some("MODIFY")) {
                return true;
            }
            if w2.as_deref() == Some("COLUMN")
                && matches!(w3.as_deref(), Some("ADD") | Some("MODIFY") | Some("CHANGE"))
            {
                return true;
            }
            if w3.as_deref() == Some("CHANGE") {
                return true;
            }
            // Oracle parenthesized form: `ADD (col |)`, `MODIFY (c1 NUMBER, c2 |)`.
            // The enclosing paren must directly follow `ADD`/`MODIFY` so that
            // `ADD CHECK (...)` / `ADD CONSTRAINT ... (...)` are not mistaken.
            if is_symbol(last - 1, "(") || is_symbol(last - 1, ",") {
                if let Some(word) = Self::innermost_open_paren_preceding_word(tokens, end) {
                    if matches!(word.to_ascii_uppercase().as_str(), "ADD" | "MODIFY") {
                        return true;
                    }
                }
            }
            return false;
        }

        if starts_with("CREATE") && any_word("TABLE") && !any_word("SELECT") {
            // Inside the column-definition list, a column name begins after `(` or
            // `,`. Exclude CTAS column lists (handled by the `SELECT` guard above).
            if is_symbol(last - 1, "(") || is_symbol(last - 1, ",") {
                let open_parens = toks
                    .iter()
                    .filter(|token| matches!(token, SqlToken::Symbol(sym) if sym == "("))
                    .count();
                let close_parens = toks
                    .iter()
                    .filter(|token| matches!(token, SqlToken::Symbol(sym) if sym == ")"))
                    .count();
                // A column-name slot lives directly in the table-definition list
                // (paren depth 1). A deeper position is a nested construct — a
                // `REFERENCES p (col …)` list, a `CHECK (…)` predicate, or a type's
                // own precision `NUMBER(…)` — where an identifier is not a new
                // column awaiting a type, so it is not a data-type slot.
                return open_parens == close_parens + 1;
            }
        }

        false
    }

    /// Whether the cursor in `deep_ctx` is at a data-type position (used to both
    /// emit type suggestions and suppress column suggestions there).
    fn data_type_position_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
    ) -> Option<DataTypePosition> {
        Self::data_type_position_for_context_for_db(
            deep_ctx,
            exclude_current_identifier_chain,
            None,
        )
    }

    fn data_type_position_for_context_for_db(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<DataTypePosition> {
        // A `FOR UPDATE OF |` locking column list is always a column position,
        // even when it sits inside a PL/SQL cursor declaration whose surrounding
        // tokens would otherwise scan as a declaration type slot.
        if matches!(
            deep_ctx.phase,
            intellisense_context::SqlPhase::LockingColumnList
        ) {
            return None;
        }
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        // `v_name oqt_|.ename%TYPE` — the word being typed is the *owner* of a
        // `.column%TYPE/%ROWTYPE` attribute (a relation qualifier head), never a
        // type name, even though the surrounding declaration would otherwise
        // scan as a type slot.
        if Self::cursor_is_at_oracle_type_attribute_relation_owner_slot(tokens, end, db_type) {
            return None;
        }
        let current_context_blocks_type_inference =
            Self::expected_create_type_object_member_keyword_candidates(tokens, end, db_type)
                .or_else(|| {
                    Self::expected_routine_completed_signature_tail_keyword_candidates(
                        tokens, end, db_type,
                    )
                })
                .or_else(|| {
                    Self::expected_package_declaration_tail_keyword_candidates(tokens, end, db_type)
                })
                .is_some();
        let position = Self::data_type_position_for_db(tokens, end, db_type).or_else(|| {
            (!current_context_blocks_type_inference && exclude_current_identifier_chain)
                .then(|| {
                    Self::data_type_position_for_db(
                        tokens,
                        Self::context_end_before_current_word(tokens, cursor_token_len)?,
                        db_type,
                    )
                })
                .flatten()
        });
        if let Some(position) = position {
            return Self::data_type_position_allowed_for_db(position, db_type).then_some(position);
        }
        if Self::current_routine_body_statement_range(deep_ctx).is_some() {
            return None;
        }
        let statement_tokens = deep_ctx.statement_tokens.as_ref();
        let statement_end = Self::expected_suggestion_context_end(
            statement_tokens,
            deep_ctx.cursor_token_len,
            exclude_current_identifier_chain,
        );
        let statement_context_blocks_type_inference =
            Self::expected_create_type_object_member_keyword_candidates(
                statement_tokens,
                statement_end,
                db_type,
            )
            .or_else(|| {
                Self::expected_routine_completed_signature_tail_keyword_candidates(
                    statement_tokens,
                    statement_end,
                    db_type,
                )
            })
            .or_else(|| {
                Self::expected_package_declaration_tail_keyword_candidates(
                    statement_tokens,
                    statement_end,
                    db_type,
                )
            })
            .is_some();
        let statement_position =
            Self::data_type_position_for_db(statement_tokens, statement_end, db_type).or_else(
                || {
                    (!statement_context_blocks_type_inference
                        && exclude_current_identifier_chain)
                        .then(|| {
                            Self::data_type_position_for_db(
                                statement_tokens,
                                Self::context_end_before_current_word(
                                    statement_tokens,
                                    deep_ctx.cursor_token_len,
                                )?,
                                db_type,
                            )
                        })
                        .flatten()
                },
            );
        if let Some(position) = statement_position {
            return Self::data_type_position_allowed_for_db(position, db_type).then_some(position);
        }
        None
    }

    fn context_end_before_current_word(
        tokens: &[SqlToken],
        cursor_token_len: usize,
    ) -> Option<usize> {
        let end = cursor_token_len.min(tokens.len());
        end.checked_sub(1).filter(|idx| {
            matches!(
                tokens.get(*idx),
                Some(SqlToken::Word(_) | SqlToken::String(_))
            )
        })
    }

    fn data_type_position_allowed_for_db(
        position: DataTypePosition,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        match position {
            DataTypePosition::TypeObject | DataTypePosition::ToolVariable => {
                !crate::sql_text::mysql_compatibility_for_sql("", db_type)
            }
            DataTypePosition::Cast | DataTypePosition::ColumnDef | DataTypePosition::Plsql => true,
        }
    }

    fn data_type_position_allows_user_type_objects(
        position: DataTypePosition,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        !crate::sql_text::mysql_compatibility_for_sql("", db_type)
            && !matches!(position, DataTypePosition::ToolVariable)
    }

    fn expected_plsql_routine_parameter_mode_keyword_candidates(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<&'static [&'static str]> {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type)
            || !Self::cursor_is_inside_routine_param_list(tokens, end)
        {
            return None;
        }

        let visible_end = end.min(tokens.len());
        let open_idx = Self::nearest_unclosed_open_paren_before(tokens, visible_end)?;
        let mut segment_start = open_idx + 1;
        let mut depth = 0i32;
        for (idx, token) in tokens
            .iter()
            .enumerate()
            .take(visible_end)
            .skip(open_idx + 1)
        {
            match token {
                SqlToken::Symbol(sym) if sym == "(" || sym == "[" => depth += 1,
                SqlToken::Symbol(sym) if sym == ")" || sym == "]" => depth = (depth - 1).max(0),
                SqlToken::Symbol(sym) if sym == "," && depth == 0 => segment_start = idx + 1,
                _ => {}
            }
        }

        let segment = tokens
            .get(segment_start..visible_end)
            .unwrap_or(&[])
            .iter()
            .filter(|token| !matches!(token, SqlToken::Comment(_)))
            .collect::<Vec<_>>();
        let plain_parameter_name = |token: &SqlToken| {
            matches!(token, SqlToken::Word(word) if !Self::is_plsql_non_type_keyword(word))
        };
        let word_is = |idx: usize, keyword: &str| {
            matches!(segment.get(idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case(keyword))
        };

        match segment.as_slice() {
            [name] if plain_parameter_name(name) => Some(&["IN", "OUT", "IN OUT"]),
            [name, _in_kw] if plain_parameter_name(name) && word_is(1, "IN") => Some(&["OUT"]),
            [name, _out_kw] if plain_parameter_name(name) && word_is(1, "OUT") => Some(&["NOCOPY"]),
            [name, _in_kw, _out_kw]
                if plain_parameter_name(name) && word_is(1, "IN") && word_is(2, "OUT") =>
            {
                Some(&["NOCOPY"])
            }
            _ => None,
        }
    }

    fn expected_mysql_routine_parameter_mode_keyword_candidates(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<&'static [&'static str]> {
        if !crate::sql_text::mysql_compatibility_for_sql("", db_type)
            || !Self::cursor_is_inside_routine_param_list(tokens, end)
        {
            return None;
        }

        let visible_end = end.min(tokens.len());
        let open_idx = Self::nearest_unclosed_open_paren_before(tokens, visible_end)?;
        if !Self::routine_param_open_keyword(tokens, open_idx)?
            .eq_ignore_ascii_case("PROCEDURE")
        {
            return None;
        }

        Self::routine_parameter_segment(tokens, open_idx, visible_end)
            .is_empty()
            .then_some(&["IN", "OUT", "INOUT"])
    }

    fn cursor_is_at_mysql_routine_parameter_type(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if !crate::sql_text::mysql_compatibility_for_sql("", db_type)
            || !Self::cursor_is_inside_routine_param_list(tokens, end)
        {
            return false;
        }

        let visible_end = end.min(tokens.len());
        let Some(open_idx) = Self::nearest_unclosed_open_paren_before(tokens, visible_end) else {
            return false;
        };
        if Self::routine_param_open_keyword(tokens, open_idx).is_none() {
            return false;
        }

        let segment = Self::routine_parameter_segment(tokens, open_idx, visible_end);
        match segment.as_slice() {
            [name] => Self::token_is_mysql_routine_parameter_name(name),
            [mode, name]
                if Self::token_is_mysql_routine_parameter_mode(mode)
                    && Self::token_is_mysql_routine_parameter_name(name) =>
            {
                true
            }
            _ => false,
        }
    }

    fn routine_parameter_segment(
        tokens: &[SqlToken],
        open_idx: usize,
        visible_end: usize,
    ) -> Vec<&SqlToken> {
        let mut segment_start = open_idx + 1;
        let mut depth = 0i32;
        for (idx, token) in tokens
            .iter()
            .enumerate()
            .take(visible_end)
            .skip(open_idx + 1)
        {
            match token {
                SqlToken::Symbol(sym) if sym == "(" || sym == "[" => depth += 1,
                SqlToken::Symbol(sym) if sym == ")" || sym == "]" => depth = (depth - 1).max(0),
                SqlToken::Symbol(sym) if sym == "," && depth == 0 => segment_start = idx + 1,
                _ => {}
            }
        }

        tokens
            .get(segment_start..visible_end)
            .unwrap_or(&[])
            .iter()
            .filter(|token| !matches!(token, SqlToken::Comment(_)))
            .collect()
    }

    fn routine_param_open_keyword(tokens: &[SqlToken], open_idx: usize) -> Option<&str> {
        let name_idx = Self::previous_non_comment_token_index(tokens, open_idx)?;
        if !Self::token_is_plsql_routine_name_segment(tokens.get(name_idx)) {
            return None;
        }

        let mut chain_start_idx = name_idx;
        loop {
            let prev_idx = Self::previous_non_comment_token_index(tokens, chain_start_idx)?;
            if !matches!(tokens.get(prev_idx), Some(SqlToken::Symbol(sym)) if sym == ".") {
                return match tokens.get(prev_idx) {
                    Some(SqlToken::Word(word))
                        if matches!(
                            word.to_ascii_uppercase().as_str(),
                            "FUNCTION" | "PROCEDURE" | "CURSOR"
                        ) =>
                    {
                        Some(word.as_str())
                    }
                    _ => None,
                };
            }

            let owner_idx = Self::previous_non_comment_token_index(tokens, prev_idx)?;
            if !Self::token_is_plsql_routine_name_segment(tokens.get(owner_idx)) {
                return None;
            }
            chain_start_idx = owner_idx;
        }
    }

    fn token_is_mysql_routine_parameter_mode(token: &SqlToken) -> bool {
        matches!(
            token,
            SqlToken::Word(word)
                if matches!(word.to_ascii_uppercase().as_str(), "IN" | "OUT" | "INOUT")
        )
    }

    fn token_is_mysql_routine_parameter_name(token: &SqlToken) -> bool {
        match token {
            SqlToken::Word(word) => !Self::is_plsql_non_type_keyword(word),
            SqlToken::String(value) => crate::sql_text::is_quoted_identifier(value),
            _ => false,
        }
    }

    fn expected_plsql_routine_parameter_tail_keyword_candidates(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<&'static [&'static str]> {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type)
            || !Self::cursor_is_inside_routine_param_list(tokens, end)
        {
            return None;
        }

        let visible_end = end.min(tokens.len());
        let open_idx = Self::nearest_unclosed_open_paren_before(tokens, visible_end)?;
        let mut segment_start = open_idx + 1;
        let mut depth = 0i32;
        for (idx, token) in tokens
            .iter()
            .enumerate()
            .take(visible_end)
            .skip(open_idx + 1)
        {
            match token {
                SqlToken::Symbol(sym) if sym == "(" || sym == "[" => depth += 1,
                SqlToken::Symbol(sym) if sym == ")" || sym == "]" => depth = (depth - 1).max(0),
                SqlToken::Symbol(sym) if sym == "," && depth == 0 => segment_start = idx + 1,
                _ => {}
            }
        }

        let segment = tokens
            .get(segment_start..visible_end)
            .unwrap_or(&[])
            .iter()
            .filter(|token| !matches!(token, SqlToken::Comment(_)))
            .collect::<Vec<_>>();
        if segment.iter().any(|token| {
            matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("DEFAULT"))
                || matches!(token, SqlToken::Symbol(sym) if sym == ":=")
        }) {
            return None;
        }

        let plain_parameter_name = |token: &SqlToken| {
            matches!(token, SqlToken::Word(word) if !Self::is_plsql_non_type_keyword(word))
        };
        let word_is = |idx: usize, keyword: &str| {
            matches!(segment.get(idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case(keyword))
        };
        let type_start = match segment.as_slice() {
            [name, ..] if plain_parameter_name(name) && word_is(1, "OUT") => return None,
            [name, ..] if plain_parameter_name(name) && word_is(1, "IN") && word_is(2, "OUT") => {
                return None;
            }
            [name, ..] if plain_parameter_name(name) && word_is(1, "IN") => 2,
            [name, ..] if plain_parameter_name(name) => 1,
            _ => return None,
        };

        if segment.len() > type_start {
            Some(&["DEFAULT"])
        } else {
            None
        }
    }

    /// True when the cursor sits right after a standalone `AS` — an alias-name
    /// slot that introduces a brand-new identifier (`expr AS |`, `relation
    /// AS |`). Such a slot is never an existing column/relation/keyword, so
    /// identifier suggestions are suppressed there, extending the typed-alias
    /// suppression in `LocalAliasContext` (which only engages once a character is
    /// typed) to the still-empty slot. Excluded for data-type slots
    /// (`CAST(x AS |)`), where `AS` introduces a type rather than an alias. The
    /// caller scopes this to the clause where `AS` actually introduces an alias
    /// (a select-list column slot, or a table/derived-table slot).
    fn cursor_word_is_alias_name_after_as(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
    ) -> bool {
        if Self::data_type_position_for_context(deep_ctx, exclude_current_identifier_chain)
            .is_some()
        {
            return false;
        }
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::previous_meaningful_words_upper(tokens, end, 1)
            .last()
            .is_some_and(|word| word == "AS")
    }

    /// True when the cursor sits at the alias-name slot right after `AS` in a
    /// `SELECT` list (`SELECT expr AS |`). That slot names a brand-new column
    /// alias, so identifier suggestions are suppressed there. Scoped to the
    /// select-list column context, where `AS` always introduces an alias.
    fn cursor_is_at_select_list_alias_name_slot(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
    ) -> bool {
        matches!(
            sql_context_for_phase(deep_ctx.phase),
            SqlContext::ColumnOrAll
        ) && Self::cursor_word_is_alias_name_after_as(deep_ctx, exclude_current_identifier_chain)
    }

    /// True when the cursor sits at the alias-name slot right after `AS` in a
    /// table clause (`FROM t AS |`, `FROM (subquery) AS |`, `UPDATE t AS |`,
    /// `MERGE INTO t AS |`, a JOIN target `… JOIN t AS |`). That slot names a
    /// brand-new relation alias — never an existing relation/column/keyword — so
    /// the identifier base is suppressed, mirroring the select-list alias slot
    /// for the table side. This is the empty-slot companion of the typed-alias
    /// suppression `LocalAliasContext` already applies (`FROM t AS x|`), closing
    /// the gap where the bare `FROM t AS |` slot dumped the whole relation
    /// catalog. It stays a column-suppressing slot even for Oracle's flashback
    /// `AS OF`: only the `OF` keyword or a new alias may follow `AS`, never an
    /// identifier. Routed through the keyword-only-slot family (not a hard
    /// suppress) so the clause keywords those target slots still expect —
    /// `UPDATE t AS |` → `SET`, `DELETE … t AS |` → `WHERE`, `… JOIN t AS |` →
    /// `ON`/`USING` — keep flowing from the keyword merge.
    fn cursor_is_at_table_alias_name_slot(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
    ) -> bool {
        matches!(sql_context_for_phase(deep_ctx.phase), SqlContext::TableName)
            && Self::cursor_word_is_alias_name_after_as(deep_ctx, exclude_current_identifier_chain)
    }

    fn cursor_is_before_current_query_from_clause(tokens: &[SqlToken], end: usize) -> bool {
        let depths = crate::ui::sql_depth::paren_depths(tokens);
        let limit = end.min(tokens.len());
        let is_top_level = |idx| crate::ui::sql_depth::is_top_level_depth(&depths, idx);

        if tokens.iter().enumerate().take(limit).any(|(idx, token)| {
            is_top_level(idx)
                && matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("FROM"))
        }) {
            return false;
        }

        for (idx, token) in tokens.iter().enumerate().skip(limit) {
            if !is_top_level(idx) {
                continue;
            }
            match token {
                SqlToken::Word(word) if word.eq_ignore_ascii_case("FROM") => return true,
                SqlToken::Word(word)
                    if matches!(
                        word.to_ascii_uppercase().as_str(),
                        "UNION" | "INTERSECT" | "EXCEPT" | "MINUS"
                    ) =>
                {
                    return false;
                }
                SqlToken::Symbol(sym) if sym == ";" => return false,
                _ => {}
            }
        }
        false
    }

    /// True when the cursor is at a row-count / offset argument — `LIMIT |`,
    /// `LIMIT <offset>, |`, or `OFFSET |`. These accept an integer literal or
    /// bind only, never a column, so column suggestions are suppressed there.
    fn cursor_is_at_row_count_position(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        let toks = Self::meaningful_tokens_before(tokens, end);
        let n = toks.len();
        if n == 0 {
            return false;
        }
        let is_word = |idx: usize, kw: &str| matches!(toks.get(idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case(kw));
        let mysql = crate::sql_text::mysql_compatibility_for_sql("", db_type);
        let mysql_family = db_type.is_none_or(|db_type| db_type.is_mysql_or_mariadb());

        // `LIMIT |` / `OFFSET |`.
        if (is_word(n - 1, "LIMIT") && mysql_family) || (is_word(n - 1, "OFFSET") && !mysql) {
            return true;
        }
        // MySQL `LIMIT <offset>, |` — the count after the comma.
        if n >= 3
            && matches!(toks.get(n - 1), Some(SqlToken::Symbol(sym)) if sym == ",")
            && is_word(n - 3, "LIMIT")
        {
            return true;
        }
        false
    }

    /// True when the cursor sits anywhere inside a row-limiting clause slot where
    /// a column is never valid. This covers both the pure value slots handled by
    /// `cursor_is_at_row_count_position` (`LIMIT |`, `OFFSET |`, `LIMIT off, |`)
    /// and every `FETCH FIRST|NEXT …` / `OFFSET <count> …` slot recognized by
    /// `expected_row_limiting_keyword_candidates` (`FETCH FIRST |`, `FETCH NEXT
    /// <count> |`, `… ROWS |`, `… PERCENT |`, `… ROWS WITH |`, `OFFSET <count>
    /// |`). The phase machine collapses all of these onto `OrderByClause`
    /// (a column context), so without this gate the row-limiting tail would
    /// wrongly offer columns alongside the row-limiting keyword hints.
    fn cursor_is_in_row_limiting_clause(
        tokens: &[SqlToken],
        end: usize,
        phase: intellisense_context::SqlPhase,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if Self::cursor_is_before_current_query_from_clause(tokens, end) {
            return false;
        }
        Self::cursor_is_at_row_count_position(tokens, end, db_type)
            || Self::expected_row_limiting_keyword_candidates(tokens, end, db_type).is_some()
            || Self::cursor_is_after_complete_row_limiting_tail(tokens, end, phase, db_type)
    }

    fn cursor_is_in_row_limiting_clause_for_context_for_db(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        if Self::cursor_is_before_current_query_from_clause(tokens, end) {
            return false;
        }
        if Self::cursor_is_after_complete_row_limiting_tail(tokens, end, deep_ctx.phase, db_type) {
            return true;
        }
        if !matches!(
            deep_ctx.phase,
            intellisense_context::SqlPhase::OrderByClause
        ) {
            return false;
        }
        Self::cursor_is_in_row_limiting_clause(tokens, end, deep_ctx.phase, db_type)
    }

    fn cursor_is_at_opposite_dialect_row_limiting_tail(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        let toks = Self::meaningful_tokens_before(tokens, end);
        let Some(select_idx) = toks.iter().rposition(
            |token| matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("SELECT")),
        ) else {
            return false;
        };
        if !toks[select_idx + 1..].iter().any(
            |token| matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("FROM")),
        ) {
            return false;
        }

        let keyword_is_tail_marker = |idx: usize| -> bool {
            if idx == 0 {
                return false;
            }
            match toks.get(idx - 1) {
                Some(SqlToken::Symbol(symbol)) if symbol == "," => false,
                Some(SqlToken::Word(word))
                    if matches!(
                        word.to_ascii_uppercase().as_str(),
                        "SELECT" | "FROM" | "JOIN" | "APPLY" | "LATERAL" | "BY"
                    ) =>
                {
                    false
                }
                Some(SqlToken::Comment(_)) | None => false,
                _ => true,
            }
        };

        if crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            if toks.iter().enumerate().any(|(idx, token)| {
                matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("FETCH"))
                    && keyword_is_tail_marker(idx)
            }) {
                return true;
            }

            return toks.iter().enumerate().any(|(idx, token)| {
                matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("OFFSET"))
                    && keyword_is_tail_marker(idx)
                    && !toks[select_idx + 1..idx].iter().any(
                        |before| matches!(before, SqlToken::Word(word) if word.eq_ignore_ascii_case("LIMIT")),
                    )
            });
        }

        toks.iter().enumerate().any(|(idx, token)| {
            matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("LIMIT"))
                && keyword_is_tail_marker(idx)
        })
    }

    fn cursor_is_at_opposite_dialect_row_limiting_tail_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        let tokens = Self::current_query_tokens(deep_ctx);
        let cursor_token_len = Self::cursor_token_len_in_current_query(deep_ctx);
        let end = Self::expected_suggestion_context_end(
            tokens,
            cursor_token_len,
            exclude_current_identifier_chain,
        );
        Self::cursor_is_at_opposite_dialect_row_limiting_tail(tokens, end, db_type)
    }

    #[cfg(test)]
    fn cursor_is_in_row_limiting_clause_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
    ) -> bool {
        Self::cursor_is_in_row_limiting_clause_for_context_for_db(
            deep_ctx,
            exclude_current_identifier_chain,
            None,
        )
    }

    fn previous_meaningful_words_with_bind_markers_upper(
        tokens: &[SqlToken],
        end: usize,
        max_words: usize,
    ) -> Vec<(String, bool)> {
        if max_words == 0 {
            return Vec::new();
        }

        let mut words_rev = Vec::new();
        let mut idx = end.min(tokens.len());
        while idx > 0 {
            idx -= 1;
            match &tokens[idx] {
                SqlToken::Comment(_) => {}
                SqlToken::Word(word) => {
                    words_rev.push((
                        word.to_ascii_uppercase(),
                        Self::word_is_preceded_by_bind_colon(tokens, idx),
                    ));
                    if words_rev.len() >= max_words {
                        break;
                    }
                }
                SqlToken::Symbol(_) => {}
                _ => break,
            }
        }
        words_rev.reverse();
        words_rev
    }

    /// True when the last meaningful token before `end` is a Word that is a
    /// qualified member — immediately preceded by `.`, e.g. the `order` in
    /// `t.order`. Such a word is unambiguously a column reference, so a dual-use
    /// clause keyword (`ORDER BY`, `GROUP BY`, `CONNECT BY`, `START WITH`) can
    /// never follow it and its continuation keyword must not be offered. (These
    /// words are reserved, so a bare unqualified use is not valid SQL; the
    /// qualified `t.order ` form — note the trailing space routes here rather than
    /// through qualified-member completion — is the only real-SQL misfire.)
    fn trigger_word_is_qualified_member(tokens: &[SqlToken], end: usize) -> bool {
        let toks = Self::meaningful_tokens_before(tokens, end);
        let last = match toks.len() {
            0 => return false,
            n => n - 1,
        };
        if last == 0 || !matches!(toks.get(last), Some(SqlToken::Word(_))) {
            return false;
        }
        matches!(toks.get(last - 1), Some(SqlToken::Symbol(sym)) if sym == ".")
    }

    fn word_is_preceded_by_bind_colon(tokens: &[SqlToken], word_idx: usize) -> bool {
        let mut idx = word_idx;
        while idx > 0 {
            idx -= 1;
            match &tokens[idx] {
                SqlToken::Comment(_) => {}
                SqlToken::Symbol(symbol) if symbol == ":" => return true,
                _ => return false,
            }
        }
        false
    }

    fn filter_expected_candidates(prefix: &str, candidates: &[&str]) -> Vec<String> {
        let prefix_upper = prefix.to_ascii_uppercase();
        let mut seen = HashSet::new();
        let mut suggestions = Vec::new();

        for candidate in candidates {
            let upper = candidate.to_ascii_uppercase();
            if !prefix_upper.is_empty() && !upper.starts_with(prefix_upper.as_str()) {
                continue;
            }
            if seen.insert(upper) {
                suggestions.push((*candidate).to_string());
                if suggestions.len() >= MAX_MERGED_SUGGESTIONS {
                    break;
                }
            }
        }

        suggestions
    }

    fn expected_candidate_for_prefix(prefix: &str, candidates: &[&str]) -> Option<String> {
        Self::expected_owned_candidate_for_prefix(
            prefix,
            Self::filter_expected_candidates(prefix, candidates),
        )
    }

    fn expected_owned_candidate_for_prefix(
        prefix: &str,
        candidates: Vec<String>,
    ) -> Option<String> {
        if candidates.is_empty() {
            return None;
        }
        if let Some(exact) = candidates
            .iter()
            .find(|candidate| candidate.eq_ignore_ascii_case(prefix))
        {
            return Some(exact.clone());
        }
        (candidates.len() == 1)
            .then(|| candidates.into_iter().next())
            .flatten()
    }

    fn expected_database_link_keyword_candidates(
        words: &[String],
    ) -> Option<&'static [&'static str]> {
        const LINK_KEYWORDS: &[&str] = &["LINK"];
        const DATABASE_LINK_MODIFIERS: &[&str] = &["PUBLIC", "DATABASE"];
        const DATABASE_KEYWORDS: &[&str] = &["DATABASE"];

        let (allows_shared, tail) = match words {
            [first, rest @ ..] if first == "DROP" => (false, rest),
            [first, rest @ ..] if matches!(first.as_str(), "ALTER" | "CREATE") => (true, rest),
            _ => return None,
        };

        match tail {
            [database] if database == "DATABASE" => Some(LINK_KEYWORDS),
            [public, database] if public == "PUBLIC" && database == "DATABASE" => {
                Some(LINK_KEYWORDS)
            }
            [shared] if allows_shared && shared == "SHARED" => Some(DATABASE_LINK_MODIFIERS),
            [shared, database] if allows_shared && shared == "SHARED" && database == "DATABASE" => {
                Some(LINK_KEYWORDS)
            }
            [shared, public] if allows_shared && shared == "SHARED" && public == "PUBLIC" => {
                Some(DATABASE_KEYWORDS)
            }
            [shared, public, database]
                if allows_shared
                    && shared == "SHARED"
                    && public == "PUBLIC"
                    && database == "DATABASE" =>
            {
                Some(LINK_KEYWORDS)
            }
            _ => None,
        }
    }

    fn expected_java_keyword_candidates(words: &[String]) -> Option<&'static [&'static str]> {
        const JAVA_CREATE_DROP_OBJECT_TYPES: &[&str] = &["SOURCE", "CLASS", "RESOURCE"];
        const JAVA_ALTER_OBJECT_TYPES: &[&str] = &["SOURCE", "CLASS"];
        const JAVA_COMPILE_OPTIONS: &[&str] = &["COMPILE", "RESOLVE"];
        const JAVA_KEYWORD: &[&str] = &["JAVA"];
        const NAMED_KEYWORD: &[&str] = &["NAMED"];
        const USING_KEYWORD: &[&str] = &["USING"];

        match words {
            [create, or_kw, replace, and_kw]
                if *create == "CREATE"
                    && *or_kw == "OR"
                    && *replace == "REPLACE"
                    && *and_kw == "AND" =>
            {
                Some(JAVA_COMPILE_OPTIONS)
            }
            [create, or_kw, replace, and_kw, compile]
                if *create == "CREATE"
                    && *or_kw == "OR"
                    && *replace == "REPLACE"
                    && *and_kw == "AND"
                    && matches!(compile.as_str(), "COMPILE" | "RESOLVE") =>
            {
                Some(JAVA_KEYWORD)
            }
            [create, or_kw, replace, java]
                if *create == "CREATE"
                    && *or_kw == "OR"
                    && *replace == "REPLACE"
                    && *java == "JAVA" =>
            {
                Some(JAVA_CREATE_DROP_OBJECT_TYPES)
            }
            [create, or_kw, replace, and_kw, compile, java]
                if *create == "CREATE"
                    && *or_kw == "OR"
                    && *replace == "REPLACE"
                    && *and_kw == "AND"
                    && matches!(compile.as_str(), "COMPILE" | "RESOLVE")
                    && *java == "JAVA" =>
            {
                Some(JAVA_CREATE_DROP_OBJECT_TYPES)
            }
            [.., verb, java] if matches!(verb.as_str(), "CREATE" | "DROP") && *java == "JAVA" => {
                Some(JAVA_CREATE_DROP_OBJECT_TYPES)
            }
            [.., verb, java] if *verb == "ALTER" && *java == "JAVA" => {
                Some(JAVA_ALTER_OBJECT_TYPES)
            }
            [.., java, object_type]
                if *java == "JAVA" && matches!(object_type.as_str(), "SOURCE" | "RESOURCE") =>
            {
                Some(NAMED_KEYWORD)
            }
            [.., java, object_type] if *java == "JAVA" && *object_type == "CLASS" => {
                Some(USING_KEYWORD)
            }
            _ => None,
        }
    }

    fn expected_rollback_segment_keyword_candidates(
        words: &[String],
    ) -> Option<&'static [&'static str]> {
        const SEGMENT_KEYWORD: &[&str] = &["SEGMENT"];

        match words {
            [.., verb, rollback]
                if matches!(verb.as_str(), "ALTER" | "CREATE" | "DROP")
                    && *rollback == "ROLLBACK" =>
            {
                Some(SEGMENT_KEYWORD)
            }
            [.., create, public, rollback]
                if *create == "CREATE" && *public == "PUBLIC" && *rollback == "ROLLBACK" =>
            {
                Some(SEGMENT_KEYWORD)
            }
            _ => None,
        }
    }

    fn oracle_explain_plan_parts(tokens: &[SqlToken], end: usize) -> Option<Vec<String>> {
        let toks = Self::meaningful_tokens_before(tokens, end);
        let statement_start = toks
            .iter()
            .rposition(|token| matches!(token, SqlToken::Symbol(sym) if sym == ";"))
            .map(|idx| idx + 1)
            .unwrap_or(0);
        let parts = toks[statement_start..]
            .iter()
            .filter_map(|token| match token {
                SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
                SqlToken::String(_) => Some("__VALUE__".to_string()),
                SqlToken::Symbol(sym) if sym == "=" || sym == "." => Some(sym.clone()),
                SqlToken::Symbol(_) | SqlToken::Comment(_) => None,
            })
            .collect::<Vec<_>>();
        matches!(parts.first().map(String::as_str), Some("EXPLAIN")).then_some(parts)
    }

    fn expected_oracle_explain_plan_keyword_candidates(
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<&'static [&'static str]> {
        const PLAN_KEYWORD: &[&str] = &["PLAN"];
        const PLAN_OPTIONS_OR_FOR_KEYWORDS: &[&str] = &["SET", "INTO", "FOR"];
        const STATEMENT_ID_KEYWORD: &[&str] = &["STATEMENT_ID"];
        const EQUALS_KEYWORD: &[&str] = &["="];
        const INTO_OR_FOR_KEYWORDS: &[&str] = &["INTO", "FOR"];
        const FOR_KEYWORD: &[&str] = &["FOR"];
        const EXPLAINABLE_STATEMENT_HEAD_KEYWORDS: &[&str] =
            &["SELECT", "INSERT", "UPDATE", "DELETE", "MERGE", "WITH"];

        let parts = Self::oracle_explain_plan_parts(tokens, end)?;

        match parts.as_slice() {
            [explain] if explain == "EXPLAIN" => Some(PLAN_KEYWORD),
            [explain, plan] if explain == "EXPLAIN" && plan == "PLAN" => {
                Some(PLAN_OPTIONS_OR_FOR_KEYWORDS)
            }
            [explain, plan, set_kw]
                if explain == "EXPLAIN" && plan == "PLAN" && set_kw == "SET" =>
            {
                Some(STATEMENT_ID_KEYWORD)
            }
            [explain, plan, set_kw, statement_id]
                if explain == "EXPLAIN"
                    && plan == "PLAN"
                    && set_kw == "SET"
                    && statement_id == "STATEMENT_ID" =>
            {
                Some(EQUALS_KEYWORD)
            }
            [explain, plan, rest @ ..] if explain == "EXPLAIN" && plan == "PLAN" => {
                if rest.last().is_some_and(|last| last == "FOR") {
                    return Some(EXPLAINABLE_STATEMENT_HEAD_KEYWORDS);
                }
                if rest.iter().any(|part| part == "FOR") {
                    return None;
                }
                if matches!(
                    rest,
                    [set_kw, statement_id, equals]
                        if set_kw == "SET" && statement_id == "STATEMENT_ID" && equals == "="
                ) {
                    return Some(&[]);
                }
                if matches!(
                    rest,
                    [set_kw, statement_id, equals, _value, tail @ ..]
                        if set_kw == "SET" && statement_id == "STATEMENT_ID" && equals == "=" && tail.is_empty()
                ) {
                    return Some(INTO_OR_FOR_KEYWORDS);
                }
                if let Some(into_idx) = rest.iter().rposition(|part| part == "INTO") {
                    let after_into = &rest[into_idx + 1..];
                    if after_into.is_empty() || after_into.last().is_some_and(|part| part == ".") {
                        return Some(&[]);
                    }
                    return Some(FOR_KEYWORD);
                }
                None
            }
            _ => None,
        }
    }

    fn expected_oracle_explain_plan_object_suggestion_kind(
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<ExpectedObjectSuggestionKind> {
        let parts = Self::oracle_explain_plan_parts(tokens, end)?;
        let [explain, plan, rest @ ..] = parts.as_slice() else {
            return None;
        };
        if explain != "EXPLAIN" || plan != "PLAN" || rest.iter().any(|part| part == "FOR") {
            return None;
        }
        let into_idx = rest.iter().rposition(|part| part == "INTO")?;
        let after_into = &rest[into_idx + 1..];
        if after_into.is_empty() || after_into.last().is_some_and(|part| part == ".") {
            Some(ExpectedObjectSuggestionKind::Table)
        } else {
            None
        }
    }

    fn is_statement_structural_anchor_word(word: &str) -> bool {
        matches!(
            word,
            "ALTER"
                | "ANALYZE"
                | "CACHE"
                | "CHANGE"
                | "CHECK"
                | "CHECKSUM"
                | "CLONE"
                | "COMMIT"
                | "COMMENT"
                | "CREATE"
                | "DEALLOCATE"
                | "DROP"
                | "EXEC"
                | "EXECUTE"
                | "EXPLAIN"
                | "FLASHBACK"
                | "FLUSH"
                | "HANDLER"
                | "IMPORT"
                | "INSTALL"
                | "KILL"
                | "LOAD"
                | "LOCK"
                | "OPTIMIZE"
                | "PREPARE"
                | "PURGE"
                | "RELEASE"
                | "RENAME"
                | "REPAIR"
                | "RESET"
                | "RESIGNAL"
                | "ROLLBACK"
                | "SET"
                | "SHOW"
                | "SIGNAL"
                | "START"
                | "STOP"
                | "TRUNCATE"
                | "UNINSTALL"
                | "UNLOCK"
                | "XA"
        )
    }

    fn meaningful_tokens_with_indices_before(
        tokens: &[SqlToken],
        end: usize,
    ) -> Vec<(usize, &SqlToken)> {
        tokens
            .get(..end)
            .unwrap_or(tokens)
            .iter()
            .enumerate()
            .filter(|(_, token)| !matches!(token, SqlToken::Comment(_)))
            .collect()
    }

    fn token_can_begin_statement_at(tokens: &[SqlToken], anchor_idx: usize) -> bool {
        match Self::cursor_statement_start_context(tokens, anchor_idx) {
            Some(StatementStartContext::TopLevel) => true,
            Some(StatementStartContext::Plsql(policy)) => policy.allow_statements,
            None => false,
        }
    }

    fn statement_start_anchor_index(
        tokens: &[SqlToken],
        end: usize,
        anchors: &[&str],
    ) -> Option<usize> {
        tokens
            .get(..end)
            .unwrap_or(tokens)
            .iter()
            .enumerate()
            .rev()
            .find_map(|(idx, token)| {
                let SqlToken::Word(word) = token else {
                    return None;
                };
                let upper = word.to_ascii_uppercase();
                (anchors.contains(&upper.as_str())
                    && Self::token_can_begin_statement_at(tokens, idx))
                .then_some(idx)
            })
    }

    fn cursor_has_statement_start_anchor(
        tokens: &[SqlToken],
        end: usize,
        anchors: &[&str],
    ) -> bool {
        Self::statement_start_anchor_index(tokens, end, anchors).is_some()
    }

    fn cursor_in_mysql_set_assignment_value(tokens: &[SqlToken], end: usize) -> bool {
        let toks = Self::meaningful_tokens_before(tokens, end);
        let Some(set_pos) = toks.iter().enumerate().rev().find_map(|(idx, token)| {
            let SqlToken::Word(word) = token else {
                return None;
            };
            (word.eq_ignore_ascii_case("SET")
                && Self::tool_command_word_at_statement_head(&toks, idx, &["SET"]))
            .then_some(idx)
        }) else {
            return false;
        };
        let tail = &toks[set_pos + 1..];
        if tail.is_empty() {
            return false;
        }
        let segment_start = tail
            .iter()
            .rposition(|token| matches!(token, SqlToken::Symbol(sym) if sym == ","))
            .map_or(0, |idx| idx + 1);
        let segment = &tail[segment_start..];
        segment.iter().any(
            |token| matches!(token, SqlToken::Symbol(sym) if matches!(sym.as_str(), "=" | ":=")),
        )
    }

    fn mysql_explain_format_json_into_slot(
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<MysqlExplainIntoSlot> {
        let toks = Self::meaningful_tokens_before(tokens, end);
        let explain_pos = toks.iter().enumerate().rev().find_map(|(idx, token)| {
            let SqlToken::Word(word) = token else {
                return None;
            };
            (word.eq_ignore_ascii_case("EXPLAIN")
                && Self::tool_command_word_at_statement_head(&toks, idx, &["EXPLAIN"]))
            .then_some(idx)
        })?;
        let tail = &toks[explain_pos + 1..];
        let mut idx = 0;
        if !matches!(tail.get(idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("FORMAT"))
        {
            return None;
        }
        idx += 1;
        if matches!(tail.get(idx), Some(SqlToken::Symbol(sym)) if sym == "=") {
            idx += 1;
        }
        if !matches!(tail.get(idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("JSON"))
        {
            return None;
        }
        idx += 1;
        if !matches!(tail.get(idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("INTO"))
        {
            return None;
        }
        let after_into = &tail[idx + 1..];
        match after_into {
            [] => Some(MysqlExplainIntoSlot::VariableName),
            [SqlToken::Symbol(sym)] if sym == "@" => Some(MysqlExplainIntoSlot::VariableName),
            [SqlToken::Word(_)] => Some(MysqlExplainIntoSlot::AfterVariable),
            [SqlToken::Symbol(sym), SqlToken::Word(_)] if sym == "@" => {
                Some(MysqlExplainIntoSlot::AfterVariable)
            }
            _ => None,
        }
    }

    fn mysql_explain_schema_slot(
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<MysqlExplainSchemaSlot> {
        let toks = Self::meaningful_tokens_before(tokens, end);
        let explain_pos = toks.iter().enumerate().rev().find_map(|(idx, token)| {
            let SqlToken::Word(word) = token else {
                return None;
            };
            (word.eq_ignore_ascii_case("EXPLAIN")
                && Self::tool_command_word_at_statement_head(&toks, idx, &["EXPLAIN"]))
            .then_some(idx)
        })?;
        let tail = &toks[explain_pos + 1..];
        let mut idx = 0;
        let mut analyze = false;
        if matches!(tail.get(idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("ANALYZE"))
        {
            analyze = true;
            idx += 1;
        }

        let mut format_value: Option<String> = None;
        if matches!(tail.get(idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("FORMAT"))
        {
            idx += 1;
            if matches!(tail.get(idx), Some(SqlToken::Symbol(sym)) if sym == "=") {
                idx += 1;
            }
            let Some(SqlToken::Word(word)) = tail.get(idx) else {
                return None;
            };
            let upper = word.to_ascii_uppercase();
            if analyze {
                if upper != "TREE" {
                    return None;
                }
            } else if !matches!(upper.as_str(), "JSON" | "TREE" | "TRADITIONAL") {
                return None;
            }
            format_value = Some(upper);
            idx += 1;
        }

        if !analyze
            && matches!(format_value.as_deref(), Some("JSON"))
            && matches!(tail.get(idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("INTO"))
        {
            idx += 1;
            match tail.get(idx) {
                Some(SqlToken::Symbol(sym)) if sym == "@" => {
                    idx += 1;
                    if !matches!(tail.get(idx), Some(SqlToken::Word(_))) {
                        return None;
                    }
                    idx += 1;
                }
                Some(SqlToken::Word(_)) => {
                    idx += 1;
                }
                _ => return None,
            }
        }

        if !matches!(tail.get(idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("FOR"))
        {
            return None;
        }
        idx += 1;
        if !matches!(
            tail.get(idx),
            Some(SqlToken::Word(word))
                if word.eq_ignore_ascii_case("SCHEMA")
                    || word.eq_ignore_ascii_case("DATABASE")
        ) {
            return None;
        }
        idx += 1;
        match &tail[idx..] {
            [] => Some(MysqlExplainSchemaSlot::SchemaName),
            [SqlToken::Word(_) | SqlToken::String(_), SqlToken::Symbol(sym)] if sym == "." => {
                Some(MysqlExplainSchemaSlot::SchemaName)
            }
            [SqlToken::Word(_) | SqlToken::String(_)] => {
                Some(MysqlExplainSchemaSlot::AfterSchemaName { analyze })
            }
            _ => None,
        }
    }

    fn mysql_explain_connection_value_slot(tokens: &[SqlToken], end: usize) -> bool {
        let toks = Self::meaningful_tokens_before(tokens, end);
        let Some(explain_pos) = toks.iter().enumerate().rev().find_map(|(idx, token)| {
            let SqlToken::Word(word) = token else {
                return None;
            };
            (word.eq_ignore_ascii_case("EXPLAIN")
                && Self::tool_command_word_at_statement_head(&toks, idx, &["EXPLAIN"]))
            .then_some(idx)
        }) else {
            return false;
        };
        let tail = &toks[explain_pos + 1..];
        let mut idx = 0;

        if matches!(tail.get(idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("FORMAT"))
        {
            idx += 1;
            if matches!(tail.get(idx), Some(SqlToken::Symbol(sym)) if sym == "=") {
                idx += 1;
            }
            let Some(SqlToken::Word(word)) = tail.get(idx) else {
                return false;
            };
            if !matches!(
                word.to_ascii_uppercase().as_str(),
                "JSON" | "TREE" | "TRADITIONAL"
            ) {
                return false;
            }
            idx += 1;
        }

        if matches!(
            tail.get(idx),
            Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("INTO")
        ) {
            idx += 1;
            match tail.get(idx) {
                Some(SqlToken::Symbol(sym)) if sym == "@" => {
                    idx += 1;
                    if !matches!(tail.get(idx), Some(SqlToken::Word(_))) {
                        return false;
                    }
                    idx += 1;
                }
                Some(SqlToken::Word(_)) => idx += 1,
                _ => return false,
            }
        }

        if !matches!(tail.get(idx), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("FOR"))
        {
            return false;
        }
        idx += 1;
        if !matches!(
            tail.get(idx),
            Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("CONNECTION")
        ) {
            return false;
        }
        idx += 1;
        matches!(
            tail.get(idx..),
            Some([]) | Some([SqlToken::Word(_) | SqlToken::String(_)])
        )
    }

    fn word_is_statement_structural_boundary_after_anchor(word: &str) -> bool {
        matches!(
            word,
            "BEGIN"
                | "DECLARE"
                | "DELETE"
                | "ELSE"
                | "EXCEPT"
                | "EXCEPTION"
                | "FROM"
                | "FULL"
                | "GROUP"
                | "HAVING"
                | "INNER"
                | "INSERT"
                | "INTERSECT"
                | "JOIN"
                | "LEFT"
                | "LOOP"
                | "MERGE"
                | "MINUS"
                | "NATURAL"
                | "ORDER"
                | "RIGHT"
                | "SELECT"
                | "THEN"
                | "UNION"
                | "UPDATE"
                | "VALUES"
                | "WHERE"
                | "WITH"
        )
    }

    fn cursor_is_in_statement_structural_head(tokens: &[SqlToken], end: usize) -> bool {
        let toks = Self::meaningful_tokens_with_indices_before(tokens, end);
        let Some(anchor_pos) = toks
            .iter()
            .enumerate()
            .rev()
            .find_map(|(pos, (idx, token))| {
                let SqlToken::Word(word) = token else {
                    return None;
                };
                (Self::is_statement_structural_anchor_word(&word.to_ascii_uppercase())
                    && Self::token_can_begin_statement_at(tokens, *idx))
                .then_some(pos)
            })
        else {
            return false;
        };

        let anchor_upper = match toks.get(anchor_pos).map(|(_, token)| *token) {
            Some(SqlToken::Word(word)) => word.to_ascii_uppercase(),
            _ => String::new(),
        };

        !toks
            .iter()
            .enumerate()
            .skip(anchor_pos + 1)
            .any(|(pos, (_, token))| match token {
                SqlToken::Symbol(sym) => sym == ";",
                SqlToken::Word(word) => {
                    let upper = word.to_ascii_uppercase();
                    if upper == "WITH"
                        && anchor_upper == "START"
                        && toks[anchor_pos + 1..pos].iter().any(|(_, token)| {
                            matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("TRANSACTION"))
                        })
                    {
                        return false;
                    }
                    if upper == "MERGE"
                        && matches!(anchor_upper.as_str(), "ALTER" | "CREATE")
                        && toks[anchor_pos + 1..pos].iter().any(|(_, token)| {
                            matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("ALGORITHM"))
                        })
                    {
                        return false;
                    }
                    if anchor_upper == "ANALYZE"
                        && matches!(upper.as_str(), "UPDATE" | "WITH")
                        && toks[anchor_pos + 1..pos].iter().any(|(_, token)| {
                            matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("TABLE"))
                        })
                        && (upper == "UPDATE"
                            || toks[anchor_pos + 1..pos].iter().any(|(_, token)| {
                                matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("HISTOGRAM"))
                            }))
                    {
                        return false;
                    }
                    if upper == "WITH"
                        && matches!(anchor_upper.as_str(), "ALTER" | "CREATE")
                        && toks[anchor_pos + 1..pos].iter().any(|(_, token)| {
                            matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("USER"))
                        })
                    {
                        return false;
                    }
                    if upper == "GROUP"
                        && matches!(anchor_upper.as_str(), "ALTER" | "CREATE" | "DROP" | "SET")
                        && toks[anchor_pos + 1..pos].iter().any(|(_, token)| {
                            matches!(token, SqlToken::Word(word) if matches!(word.to_ascii_uppercase().as_str(), "LOGFILE" | "RESOURCE"))
                        })
                    {
                        return false;
                    }
                    if matches!(anchor_upper.as_str(), "ALTER" | "CREATE")
                        && toks[anchor_pos + 1..pos].iter().any(|(_, token)| {
                            matches!(
                                token,
                                SqlToken::Word(word)
                                    if matches!(
                                        word.to_ascii_uppercase().as_str(),
                                        "FUNCTION" | "PROCEDURE"
                                    )
                            )
                        })
                        && !toks[anchor_pos + 1..pos].iter().any(|(_, token)| {
                            matches!(
                                token,
                                SqlToken::Word(word)
                                    if matches!(
                                        word.to_ascii_uppercase().as_str(),
                                        "AS" | "BEGIN" | "IS"
                                    )
                            )
                        })
                    {
                        return false;
                    }
                    if matches!(upper.as_str(), "DELETE" | "INSERT" | "UPDATE")
                        && anchor_upper == "CREATE"
                        && toks[anchor_pos + 1..pos].iter().any(|(_, token)| {
                            matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("TRIGGER"))
                        })
                        && toks[anchor_pos + 1..pos].iter().any(|(_, token)| {
                            matches!(token, SqlToken::Word(word) if matches!(word.to_ascii_uppercase().as_str(), "AFTER" | "BEFORE"))
                        })
                    {
                        return false;
                    }
                    Self::word_is_statement_structural_boundary_after_anchor(&upper)
                }
                _ => false,
            })
    }

    fn cursor_is_in_object_command_head(tokens: &[SqlToken], end: usize) -> bool {
        let toks = Self::meaningful_tokens_with_indices_before(tokens, end);
        let Some(anchor_pos) = toks
            .iter()
            .enumerate()
            .rev()
            .find_map(|(pos, (idx, token))| {
                let SqlToken::Word(word) = token else {
                    return None;
                };
                let upper = word.to_ascii_uppercase();
                (matches!(
                    upper.as_str(),
                    "CALL" | "DESC" | "DESCRIBE" | "EXEC" | "EXECUTE" | "EXPLAIN"
                ) && Self::token_can_begin_statement_at(tokens, *idx))
                .then_some(pos)
            })
        else {
            return false;
        };

        !toks
            .iter()
            .skip(anchor_pos + 1)
            .any(|(_, token)| match token {
                SqlToken::Symbol(sym) => sym == ";",
                SqlToken::Word(word) => Self::word_is_statement_structural_boundary_after_anchor(
                    &word.to_ascii_uppercase(),
                ),
                _ => false,
            })
    }

    fn cursor_is_at_foreign_key_references_table_slot(tokens: &[SqlToken], end: usize) -> bool {
        let toks = Self::meaningful_tokens_before(tokens, end);
        if !matches!(toks.last(), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("REFERENCES"))
        {
            return false;
        }
        if !Self::cursor_is_in_statement_structural_head(tokens, end) {
            return false;
        }

        let first = toks.iter().find_map(|token| match token {
            SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
            _ => None,
        });
        if !matches!(first.as_deref(), Some("ALTER" | "CREATE")) {
            return false;
        }

        toks.iter().any(
            |token| matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("TABLE")),
        )
    }

    fn cursor_is_at_create_on_table_target_slot(tokens: &[SqlToken], end: usize) -> bool {
        let toks = Self::meaningful_tokens_with_indices_before(tokens, end);
        let Some(on_idx) = toks.len().checked_sub(1) else {
            return false;
        };
        if !matches!(toks.get(on_idx), Some((_, SqlToken::Word(word))) if word.eq_ignore_ascii_case("ON"))
        {
            return false;
        }

        let Some(object_idx) =
            toks[..on_idx]
                .iter()
                .enumerate()
                .rev()
                .find_map(|(idx, (_, token))| {
                    let SqlToken::Word(word) = token else {
                        return None;
                    };
                    matches!(word.to_ascii_uppercase().as_str(), "INDEX" | "TRIGGER").then_some(idx)
                })
        else {
            return false;
        };
        let Some(create_idx) =
            toks[..object_idx]
                .iter()
                .enumerate()
                .rev()
                .find_map(|(idx, (_, token))| {
                    matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("CREATE"))
                        .then_some(idx)
                })
        else {
            return false;
        };

        if !Self::token_can_begin_statement_at(tokens, toks[create_idx].0) {
            return false;
        }

        if toks[object_idx + 1..on_idx]
            .iter()
            .any(|(_, token)| match token {
                SqlToken::Symbol(sym) => sym == ";",
                SqlToken::Word(word) => matches!(
                    word.to_ascii_uppercase().as_str(),
                    "BEGIN"
                        | "DECLARE"
                        | "ELSE"
                        | "EXCEPT"
                        | "EXCEPTION"
                        | "FROM"
                        | "GROUP"
                        | "HAVING"
                        | "INTERSECT"
                        | "JOIN"
                        | "LOOP"
                        | "MINUS"
                        | "ORDER"
                        | "SELECT"
                        | "THEN"
                        | "UNION"
                        | "VALUES"
                        | "WHERE"
                        | "WITH"
                ),
                _ => false,
            })
        {
            return false;
        }

        !toks[create_idx + 1..object_idx]
            .iter()
            .any(|(_, token)| match token {
                SqlToken::Symbol(sym) => sym == ";",
                SqlToken::Word(word) => matches!(
                    word.to_ascii_uppercase().as_str(),
                    "BEGIN"
                        | "DECLARE"
                        | "ELSE"
                        | "EXCEPT"
                        | "EXCEPTION"
                        | "FROM"
                        | "GROUP"
                        | "HAVING"
                        | "INTERSECT"
                        | "JOIN"
                        | "LOOP"
                        | "MINUS"
                        | "ORDER"
                        | "SELECT"
                        | "THEN"
                        | "UNION"
                        | "VALUES"
                        | "WHERE"
                        | "WITH"
                ),
                _ => false,
            })
    }

    fn cursor_is_at_oracle_instead_of_trigger_view_target_slot(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return false;
        }
        if !Self::cursor_is_at_create_on_table_target_slot(tokens, end) {
            return false;
        }

        let toks = Self::meaningful_tokens_with_indices_before(tokens, end);
        if !matches!(toks.last(), Some((_, SqlToken::Word(word))) if word.eq_ignore_ascii_case("ON"))
        {
            return false;
        }

        let Some(trigger_idx) = toks.iter().rposition(|(_, token)| {
            matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("TRIGGER"))
        }) else {
            return false;
        };
        let Some(create_idx) = toks[..trigger_idx].iter().rposition(|(_, token)| {
            matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("CREATE"))
        }) else {
            return false;
        };

        if !Self::token_can_begin_statement_at(tokens, toks[create_idx].0) {
            return false;
        }

        toks[trigger_idx + 1..toks.len() - 1]
            .windows(2)
            .any(|pair| {
                matches!(
                    pair,
                    [
                        (_, SqlToken::Word(first)),
                        (_, SqlToken::Word(second))
                    ] if first.eq_ignore_ascii_case("INSTEAD") && second.eq_ignore_ascii_case("OF")
                )
            })
    }

    fn cursor_is_at_mysql_drop_index_on_table_target_slot(tokens: &[SqlToken], end: usize) -> bool {
        let words = Self::previous_meaningful_words_upper(tokens, end, 6);
        matches!(
            words.as_slice(),
            [drop_kw, index_kw, _index_name, on_kw]
                if drop_kw == "DROP" && index_kw == "INDEX" && on_kw == "ON"
        ) || matches!(
            words.as_slice(),
            [drop_kw, index_kw, if_kw, exists_kw, _index_name, on_kw]
                if drop_kw == "DROP"
                    && index_kw == "INDEX"
                    && if_kw == "IF"
                    && exists_kw == "EXISTS"
                    && on_kw == "ON"
        )
    }

    /// True when the cursor sits immediately after `verb` and `verb` heads the
    /// current statement — the object-type slot of a fresh `verb <object>`
    /// statement, not a trailing `verb` sub-clause of an enclosing statement
    /// (`ALTER TABLE t DROP |`). The current statement starts after the last
    /// top-level `;`, so this matches both `DROP |` and `…; DROP |` while rejecting
    /// the buried sub-clause — which neither the over-strict `[last]` nor the
    /// over-greedy `[.., last]` slice pattern can do (the word list drops the `;`).
    fn cursor_at_statement_head_verb(tokens: &[SqlToken], end: usize, verb: &str) -> bool {
        let toks = Self::meaningful_tokens_before(tokens, end);
        let Some(SqlToken::Word(last)) = toks.last() else {
            return false;
        };
        if !last.eq_ignore_ascii_case(verb) {
            return false;
        }
        // Walking back from the verb to the statement boundary, no other word may
        // intervene; a `;` (or the start of input) means the verb is the head.
        toks[..toks.len() - 1]
            .iter()
            .rev()
            .find_map(|token| match token {
                SqlToken::Symbol(sym) if sym == ";" => Some(true),
                SqlToken::Word(_) => Some(false),
                _ => None,
            })
            .unwrap_or(true)
    }

    fn expected_statement_structural_keyword_candidates(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<&'static [&'static str]> {
        const OBJECT_TYPE_KEYWORDS: &[&str] = &[
            "TABLE",
            "VIEW",
            "MATERIALIZED",
            "TYPE",
            "TRIGGER",
            "INDEX",
            "PROCEDURE",
            "FUNCTION",
            "PACKAGE",
            "SEQUENCE",
            "SYNONYM",
            "DATABASE",
            "DIRECTORY",
            "TABLESPACE",
            "USER",
            "ROLE",
            "PROFILE",
            "ROLLBACK",
            "JAVA",
            "LIBRARY",
            "CLUSTER",
            "CONTEXT",
            "DIMENSION",
            "OPERATOR",
            "INDEXTYPE",
            "EDITION",
            "PUBLIC",
        ];
        const ALTER_OBJECT_TYPE_KEYWORDS: &[&str] = &[
            "TABLE",
            "VIEW",
            "MATERIALIZED",
            "TYPE",
            "TRIGGER",
            "INDEX",
            "PROCEDURE",
            "FUNCTION",
            "PACKAGE",
            "SEQUENCE",
            "SYNONYM",
            "DATABASE",
            "TABLESPACE",
            "USER",
            "ROLE",
            "PROFILE",
            "PUBLIC",
            "SHARED",
            "ROLLBACK",
            "JAVA",
            "LIBRARY",
            "CLUSTER",
            "DIMENSION",
            "OPERATOR",
            "INDEXTYPE",
            "SYSTEM",
            "SESSION",
        ];
        const CREATE_OBJECT_TYPE_KEYWORDS: &[&str] = &[
            "OR",
            "FORCE",
            "EDITIONABLE",
            "NONEDITIONABLE",
            "TABLE",
            "VIEW",
            "MATERIALIZED",
            "EDITIONING",
            "TYPE",
            "TRIGGER",
            "INDEX",
            "PROCEDURE",
            "FUNCTION",
            "PACKAGE",
            "SEQUENCE",
            "SYNONYM",
            "DATABASE",
            "DIRECTORY",
            "TABLESPACE",
            "SHARED",
            "USER",
            "ROLE",
            "PROFILE",
            "ROLLBACK",
            "JAVA",
            "LIBRARY",
            "CLUSTER",
            "CONTEXT",
            "DIMENSION",
            "OPERATOR",
            "INDEXTYPE",
            "EDITION",
            "PUBLIC",
        ];
        const CREATE_OR_REPLACE_OBJECT_TYPE_KEYWORDS: &[&str] = &[
            "FORCE",
            "EDITIONABLE",
            "NONEDITIONABLE",
            "TABLE",
            "VIEW",
            "MATERIALIZED",
            "EDITIONING",
            "TYPE",
            "TRIGGER",
            "INDEX",
            "PROCEDURE",
            "FUNCTION",
            "PACKAGE",
            "SEQUENCE",
            "SYNONYM",
            "DIRECTORY",
            "LIBRARY",
            "USER",
            "JAVA",
            "PUBLIC",
        ];
        const CREATE_FORCE_VIEW_PREFIX_KEYWORDS: &[&str] =
            &["EDITIONABLE", "NONEDITIONABLE", "EDITIONING", "VIEW"];
        const COMMENT_OBJECT_TYPE_KEYWORDS: &[&str] = &[
            "COLUMN",
            "TABLE",
            "VIEW",
            "MATERIALIZED",
            "EDITIONING",
            "MINING",
            "OPERATOR",
            "INDEXTYPE",
        ];

        if !Self::cursor_is_in_statement_structural_head(tokens, end) {
            return None;
        }

        let words = Self::previous_meaningful_words_upper(tokens, end, 12);
        if crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return Self::expected_mysql_statement_structural_keyword_candidates(
                tokens,
                end,
                words.as_slice(),
                db_type,
            );
        }
        if Self::is_create_synonym_name_written_context(&words) {
            return Some(&["FOR"]);
        }
        if let Some(candidates) = Self::expected_oracle_explain_plan_keyword_candidates(tokens, end)
        {
            return Some(candidates);
        }
        if let Some(candidates) = Self::expected_database_link_keyword_candidates(&words) {
            return Some(candidates);
        }
        if let Some(candidates) = Self::expected_java_keyword_candidates(&words) {
            return Some(candidates);
        }
        if let Some(candidates) = Self::expected_rollback_segment_keyword_candidates(&words) {
            return Some(candidates);
        }

        // A bare statement-head verb (`CREATE`/`DROP`/`ALTER |`, also after a `;`)
        // opens the object-type list. Gated on the verb actually heading the
        // current statement so a trailing sub-clause verb (`ALTER TABLE t DROP |`)
        // does not leak the `DROP <object>` catalog.
        if Self::cursor_at_statement_head_verb(tokens, end, "CREATE") {
            return Some(CREATE_OBJECT_TYPE_KEYWORDS);
        }
        if Self::cursor_at_statement_head_verb(tokens, end, "DROP") {
            return Some(OBJECT_TYPE_KEYWORDS);
        }
        if Self::cursor_at_statement_head_verb(tokens, end, "ALTER") {
            return Some(ALTER_OBJECT_TYPE_KEYWORDS);
        }

        match words.as_slice() {
            [.., prev, last]
                if *prev == "CREATE" && matches!(last.as_str(), "UNIQUE" | "BITMAP") =>
            {
                Some(&["INDEX"])
            }
            [.., prev, last] if *prev == "CREATE" && *last == "GLOBAL" => Some(&["TEMPORARY"]),
            [.., a, b, c] if *a == "CREATE" && *b == "GLOBAL" && *c == "TEMPORARY" => {
                Some(&["TABLE"])
            }
            [.., prev, last]
                if matches!(prev.as_str(), "CREATE" | "DROP" | "ALTER" | "ON")
                    && *last == "MATERIALIZED" =>
            {
                Some(&["VIEW"])
            }
            [.., a, b, c, d]
                if *a == "CREATE" && *b == "OR" && *c == "REPLACE" && *d == "MATERIALIZED" =>
            {
                Some(&["VIEW"])
            }
            [.., a, b, c]
                if matches!(a.as_str(), "ALTER" | "CREATE" | "DROP")
                    && *b == "MATERIALIZED"
                    && *c == "VIEW" =>
            {
                Some(&["LOG"])
            }
            [.., a, b, c, d]
                if matches!(a.as_str(), "ALTER" | "CREATE" | "DROP")
                    && *b == "MATERIALIZED"
                    && *c == "VIEW"
                    && *d == "LOG" =>
            {
                Some(&["ON"])
            }
            [.., prev, last]
                if matches!(prev.as_str(), "CREATE" | "ON") && *last == "EDITIONING" =>
            {
                Some(&["VIEW"])
            }
            [.., a, b, c, d]
                if *a == "CREATE" && *b == "OR" && *c == "REPLACE" && *d == "EDITIONING" =>
            {
                Some(&["VIEW"])
            }
            [.., prev, last] if *prev == "CREATE" && *last == "FORCE" => {
                Some(CREATE_FORCE_VIEW_PREFIX_KEYWORDS)
            }
            [.., a, b, c, d]
                if *a == "CREATE" && *b == "OR" && *c == "REPLACE" && *d == "FORCE" =>
            {
                Some(CREATE_FORCE_VIEW_PREFIX_KEYWORDS)
            }
            // `CREATE [OR REPLACE] {EDITIONABLE|NONEDITIONABLE} |` → the object type
            // that clause applies to (function/procedure/package/type/trigger/view/
            // synonym, all of which support the editioning modifier).
            [.., prev, last]
                if *prev == "CREATE"
                    && matches!(last.as_str(), "EDITIONABLE" | "NONEDITIONABLE") =>
            {
                Some(CREATE_OR_REPLACE_OBJECT_TYPE_KEYWORDS)
            }
            [.., a, b, c, d]
                if *a == "CREATE"
                    && *b == "OR"
                    && *c == "REPLACE"
                    && matches!(d.as_str(), "EDITIONABLE" | "NONEDITIONABLE") =>
            {
                Some(CREATE_OR_REPLACE_OBJECT_TYPE_KEYWORDS)
            }
            [.., a, b, c]
                if *a == "CREATE"
                    && *b == "FORCE"
                    && matches!(c.as_str(), "EDITIONABLE" | "NONEDITIONABLE") =>
            {
                Some(&["VIEW"])
            }
            [.., a, b, c, d, e]
                if *a == "CREATE"
                    && *b == "OR"
                    && *c == "REPLACE"
                    && *d == "FORCE"
                    && matches!(e.as_str(), "EDITIONABLE" | "NONEDITIONABLE") =>
            {
                Some(&["VIEW"])
            }
            [.., prev, last]
                if matches!(prev.as_str(), "CREATE" | "DROP")
                    && matches!(last.as_str(), "PACKAGE" | "TYPE") =>
            {
                Some(&["BODY"])
            }
            [.., a, b, c, d]
                if *a == "CREATE"
                    && *b == "OR"
                    && *c == "REPLACE"
                    && matches!(d.as_str(), "PACKAGE" | "TYPE") =>
            {
                Some(&["BODY"])
            }
            [.., prev, last] if *prev == "CREATE" && *last == "PUBLIC" => {
                Some(&["SYNONYM", "DATABASE", "ROLLBACK"])
            }
            [.., prev, last] if matches!(prev.as_str(), "ALTER" | "DROP") && *last == "PUBLIC" => {
                Some(&["SYNONYM", "DATABASE"])
            }
            [.., a, b, c, d]
                if *a == "CREATE" && *b == "OR" && *c == "REPLACE" && *d == "PUBLIC" =>
            {
                Some(&["SYNONYM"])
            }
            [.., prev, last] if *prev == "COMMENT" && *last == "ON" => {
                Some(COMMENT_OBJECT_TYPE_KEYWORDS)
            }
            [.., a, b, c] if *a == "CREATE" && *b == "OR" && *c == "REPLACE" => {
                Some(CREATE_OR_REPLACE_OBJECT_TYPE_KEYWORDS)
            }
            [.., last]
                if (*last == "TRUNCATE" || *last == "LOCK")
                    && Self::cursor_at_statement_head_verb(tokens, end, last) =>
            {
                Some(&["TABLE"])
            }
            [.., last]
                if *last == "FLASHBACK"
                    && Self::cursor_at_statement_head_verb(tokens, end, last) =>
            {
                Some(&["TABLE", "DATABASE"])
            }
            [.., last]
                if *last == "PURGE" && Self::cursor_at_statement_head_verb(tokens, end, last) =>
            {
                Some(&[
                    "TABLE",
                    "INDEX",
                    "RECYCLEBIN",
                    "DBA_RECYCLEBIN",
                    "TABLESPACE",
                ])
            }
            [.., last]
                if *last == "ANALYZE" && Self::cursor_at_statement_head_verb(tokens, end, last) =>
            {
                Some(&["TABLE", "INDEX", "CLUSTER"])
            }
            [.., prev, last] if *prev == "ALTER" && *last == "SESSION" => Some(&["SET"]),
            [.., a, b, c] if *a == "ALTER" && *b == "SESSION" && *c == "SET" => {
                Some(&["CURRENT_SCHEMA"])
            }
            [.., last] if *last == "COMMENT" => Some(&["ON"]),
            [.., last] if *last == "EXECUTE" => Some(&["IMMEDIATE"]),
            [.., prev, last] if *prev == "CREATE" && *last == "OR" => Some(&["REPLACE"]),
            _ => None,
        }
    }

    fn expected_mariadb_package_keyword_candidates(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<&'static [&'static str]> {
        if !completion_db_type_is_mariadb(db_type) {
            return None;
        }

        let words = Self::meaningful_tokens_before(tokens, end)
            .into_iter()
            .filter_map(|token| match token {
                SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
                SqlToken::String(_) => Some("__VALUE__".to_string()),
                SqlToken::Symbol(_) => None,
                _ => None,
            })
            .collect::<Vec<_>>();
        let create_pos = words.iter().rposition(|word| word == "CREATE")?;
        let mut idx = create_pos + 1;
        if idx >= words.len() {
            return None;
        }

        if words.get(idx).map(String::as_str) == Some("OR") {
            if words.get(idx + 1).map(String::as_str) != Some("REPLACE") {
                return None;
            }
            idx += 2;
        }

        if words.get(idx).map(String::as_str) == Some("DEFINER") {
            if idx + 1 >= words.len() {
                return None;
            }
            idx += 2;
        }

        if words.get(idx).map(String::as_str) != Some("PACKAGE") {
            return None;
        }
        idx += 1;

        if idx == words.len() {
            return Some(&["BODY", "IF"]);
        }

        if words.get(idx).map(String::as_str) == Some("BODY") {
            idx += 1;
            if idx == words.len() {
                return Some(&["IF"]);
            }
        }

        if words.get(idx).map(String::as_str) == Some("IF") {
            if idx + 1 == words.len() {
                return Some(&["NOT"]);
            }
            if words.get(idx + 1).map(String::as_str) != Some("NOT") {
                return None;
            }
            if idx + 2 == words.len() {
                return Some(&["EXISTS"]);
            }
            if words.get(idx + 2).map(String::as_str) != Some("EXISTS") {
                return None;
            }
            idx += 3;
        }

        if idx >= words.len() {
            return None;
        }

        idx += 1;
        if idx == words.len() {
            return Some(Self::mariadb_package_tail_candidates(false, false));
        }

        let mut has_comment = false;
        let mut has_sql_security = false;
        while idx < words.len() {
            match words.get(idx).map(String::as_str) {
                Some("COMMENT") if !has_comment => {
                    if idx + 1 == words.len() {
                        return None;
                    }
                    if words.get(idx + 1).map(String::as_str) != Some("__VALUE__") {
                        return None;
                    }
                    has_comment = true;
                    idx += 2;
                }
                Some("SQL") if !has_sql_security => {
                    if idx + 1 == words.len() {
                        return Some(&["SECURITY"]);
                    }
                    if words.get(idx + 1).map(String::as_str) != Some("SECURITY") {
                        return None;
                    }
                    if idx + 2 == words.len() {
                        return Some(&["DEFINER", "INVOKER"]);
                    }
                    if !matches!(
                        words.get(idx + 2).map(String::as_str),
                        Some("DEFINER" | "INVOKER")
                    ) {
                        return None;
                    }
                    has_sql_security = true;
                    idx += 3;
                }
                Some("AS" | "IS") => return None,
                _ => return None,
            }

            if idx == words.len() {
                return Some(Self::mariadb_package_tail_candidates(
                    has_comment,
                    has_sql_security,
                ));
            }
        }

        None
    }

    fn mariadb_package_tail_candidates(
        has_comment: bool,
        has_sql_security: bool,
    ) -> &'static [&'static str] {
        match (has_comment, has_sql_security) {
            (false, false) => &["AS", "COMMENT", "IS", "SQL"],
            (true, false) => &["AS", "IS", "SQL"],
            (false, true) => &["AS", "COMMENT", "IS"],
            (true, true) => &["AS", "IS"],
        }
    }

    fn expected_mariadb_create_role_keyword_candidates(
        tokens: &[SqlToken],
        end: usize,
        words: &[String],
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<&'static [&'static str]> {
        if !completion_db_type_is_mariadb(db_type) {
            return None;
        }
        if Self::meaningful_tokens_before(tokens, end)
            .last()
            .is_some_and(|token| matches!(token, SqlToken::Symbol(sym) if sym == ","))
        {
            return None;
        }

        let create_idx = words.iter().rposition(|word| word == "CREATE")?;
        let mut idx = create_idx + 1;
        let has_or_replace = words.get(idx).map(String::as_str) == Some("OR")
            && words.get(idx + 1).map(String::as_str) == Some("REPLACE");
        if words.get(idx).map(String::as_str) == Some("OR")
            && words.get(idx + 1).map(String::as_str) == Some("REPLACE")
        {
            idx += 2;
        }
        if words.get(idx).map(String::as_str) != Some("ROLE") {
            return None;
        }
        idx += 1;
        if idx == words.len() {
            return if has_or_replace {
                Some(&["IF"])
            } else {
                None
            };
        }
        if words.get(idx).map(String::as_str) == Some("IF") {
            if !has_or_replace {
                if words.get(idx + 1).map(String::as_str) == Some("NOT")
                    && words.get(idx + 2).map(String::as_str) == Some("EXISTS")
                {
                    idx += 3;
                } else {
                    return None;
                }
            } else {
            if idx + 1 == words.len() {
                return Some(&["NOT"]);
            }
            if words.get(idx + 1).map(String::as_str) == Some("NOT") {
                if idx + 2 == words.len() {
                    return Some(&["EXISTS"]);
                }
                if words.get(idx + 2).map(String::as_str) != Some("EXISTS") {
                    return None;
                }
                idx += 3;
            } else {
                return None;
            }
            }
        }
        if idx >= words.len() {
            return None;
        }

        idx += 1;
        match words.get(idx).map(String::as_str) {
            None => Some(&["WITH"]),
            Some("WITH") if idx + 1 == words.len() => Some(&["ADMIN"]),
            Some("WITH")
                if words.get(idx + 1).map(String::as_str) == Some("ADMIN")
                    && idx + 2 == words.len() =>
            {
                Some(&["CURRENT_ROLE", "CURRENT_USER"])
            }
            _ => None,
        }
    }

