    fn expected_mysql_drop_index_option_value_object_suggestion_kind(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<ExpectedObjectSuggestionKind> {
        let toks = Self::meaningful_tokens_before(tokens, end);
        if !matches!(toks.first(), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("DROP"))
            || !matches!(toks.get(1), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("INDEX"))
        {
            return None;
        }

        let on_idx = toks.iter().position(
            |token| matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("ON")),
        )?;
        let mut idx = on_idx + 1;
        if !matches!(toks.get(idx), Some(SqlToken::Word(_))) {
            return None;
        }
        idx += 1;
        while matches!(toks.get(idx), Some(SqlToken::Symbol(sym)) if sym == ".")
            && matches!(toks.get(idx + 1), Some(SqlToken::Word(_)))
        {
            idx += 2;
        }

        let mariadb = completion_db_type_is_mariadb(db_type);
        toks.get(idx..)
            .is_some_and(|tail| {
                tail.iter().any(|token| match token {
                    SqlToken::Word(word) => {
                        matches!(
                            word.to_ascii_uppercase().as_str(),
                            "ALGORITHM" | "LOCK"
                        ) || (mariadb
                            && matches!(word.to_ascii_uppercase().as_str(), "WAIT" | "NOWAIT"))
                    }
                    _ => false,
                })
            })
            .then_some(ExpectedObjectSuggestionKind::NoSuggestions)
    }

    fn cursor_is_at_mysql_alter_table_add_index_option_tail(
        tokens: &[SqlToken],
        end: usize,
        _db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        let toks = Self::meaningful_tokens_before(tokens, end);
        if !matches!(toks.first(), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("ALTER"))
            || !toks.iter().any(
                |token| matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("TABLE")),
            )
        {
            return false;
        }

        let Some(add_idx) = toks.iter().position(
            |token| matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("ADD")),
        ) else {
            return false;
        };
        let add_tail_has_index = toks[add_idx + 1..].iter().any(|token| {
            matches!(
                token,
                SqlToken::Word(word)
                    if matches!(
                        word.to_ascii_uppercase().as_str(),
                        "INDEX" | "KEY" | "FULLTEXT" | "SPATIAL"
                    )
            )
        });
        if !add_tail_has_index {
            return false;
        }

        let mut depth = 0_i32;
        let mut closed_index_columns_idx = None;
        for (idx, token) in toks.iter().enumerate().skip(add_idx + 1) {
            match token {
                SqlToken::Symbol(sym) if sym == "(" => depth += 1,
                SqlToken::Symbol(sym) if sym == ")" => {
                    depth -= 1;
                    if depth <= 0 {
                        closed_index_columns_idx = Some(idx);
                    }
                }
                _ => {}
            }
        }
        let Some(close_idx) = closed_index_columns_idx else {
            return false;
        };
        let tail = toks.get(close_idx + 1..).unwrap_or(&[]);
        if tail
            .iter()
            .any(|token| matches!(token, SqlToken::Symbol(sym) if sym == ","))
        {
            return false;
        }
        Self::mysql_index_option_tail_has_option_keyword(tail)
    }

    fn cursor_is_at_mysql_create_table_inline_index_option_tail(
        tokens: &[SqlToken],
        end: usize,
        _db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        let toks = Self::meaningful_tokens_before(tokens, end);
        if !matches!(toks.first(), Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("CREATE"))
            || !toks.iter().any(
                |token| matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("TABLE")),
            )
        {
            return false;
        }

        let Some(close_idx) = toks.iter().enumerate().rev().find_map(|(idx, token)| {
            matches!(token, SqlToken::Symbol(sym) if sym == ")").then_some(idx)
        }) else {
            return false;
        };
        let mut depth = 0_i32;
        let mut open_idx = None;
        for (idx, token) in toks[..close_idx].iter().enumerate().rev() {
            match token {
                SqlToken::Symbol(sym) if sym == ")" => depth += 1,
                SqlToken::Symbol(sym) if sym == "(" => {
                    if depth == 0 {
                        open_idx = Some(idx);
                        break;
                    }
                    depth -= 1;
                }
                _ => {}
            }
        }
        let Some(open_idx) = open_idx else {
            return false;
        };
        let segment_start = toks[..open_idx]
            .iter()
            .enumerate()
            .rev()
            .find_map(|(idx, token)| {
                matches!(token, SqlToken::Symbol(sym) if sym == "," || sym == "(")
                    .then_some(idx + 1)
            })
            .unwrap_or(0);
        let segment = &toks[segment_start..open_idx];
        let is_index_segment = segment.iter().any(|token| {
            matches!(
                token,
                SqlToken::Word(word)
                    if matches!(
                        word.to_ascii_uppercase().as_str(),
                        "FULLTEXT" | "INDEX" | "KEY" | "SPATIAL" | "UNIQUE"
                    )
            )
        }) || segment.windows(2).any(|pair| {
            matches!(
                pair,
                [SqlToken::Word(primary), SqlToken::Word(key)]
                    if primary.eq_ignore_ascii_case("PRIMARY") && key.eq_ignore_ascii_case("KEY")
            )
        });
        if !is_index_segment {
            return false;
        }

        let tail = toks.get(close_idx + 1..).unwrap_or(&[]);
        if tail
            .iter()
            .any(|token| matches!(token, SqlToken::Symbol(sym) if sym == ","))
        {
            return false;
        }
        Self::mysql_index_option_tail_has_option_keyword(tail)
    }

    fn mysql_index_option_tail_has_option_keyword(tail: &[&SqlToken]) -> bool {
        tail.iter().any(|token| {
            matches!(
                token,
                SqlToken::Word(word)
                    if matches!(
                        word.to_ascii_uppercase().as_str(),
                        "COMMENT"
                            | "ENGINE_ATTRIBUTE"
                            | "INVISIBLE"
                            | "KEY_BLOCK_SIZE"
                            | "PARSER"
                            | "SECONDARY_ENGINE_ATTRIBUTE"
                            | "VISIBLE"
                            | "WITH"
                    )
            )
        })
    }

    fn expected_mysql_rename_user_object_suggestion_kind(
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<ExpectedObjectSuggestionKind> {
        let items: Vec<String> = Self::meaningful_tokens_before(tokens, end)
            .into_iter()
            .filter_map(|token| match token {
                SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
                SqlToken::String(_) => Some("__VALUE__".to_string()),
                SqlToken::Symbol(symbol) if matches!(symbol.as_str(), "," | "@") => {
                    Some(symbol.clone())
                }
                SqlToken::Symbol(_) | SqlToken::Comment(_) => None,
            })
            .collect();
        let user_slot = match items.as_slice() {
            [rename, user] if rename == "RENAME" && user == "USER" => true,
            [rename, user, .., comma] if rename == "RENAME" && user == "USER" && comma == "," => {
                true
            }
            _ => false,
        };
        user_slot.then_some(ExpectedObjectSuggestionKind::User)
    }

    fn expected_mysql_existing_user_object_suggestion_kind(
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<ExpectedObjectSuggestionKind> {
        let items = Self::meaningful_tokens_before(tokens, end)
            .into_iter()
            .filter_map(Self::mysql_user_account_slot_item)
            .collect::<Vec<_>>();
        let user_slot = match items.as_slice() {
            [verb, object_type]
                if matches!(verb.as_str(), "ALTER" | "DROP") && object_type == "USER" =>
            {
                true
            }
            [drop, object_type] if drop == "DROP" && object_type == "ROLE" => true,
            [verb, object_type, if_kw, exists_kw]
                if matches!(verb.as_str(), "ALTER" | "DROP")
                    && object_type == "USER"
                    && if_kw == "IF"
                    && exists_kw == "EXISTS" =>
            {
                true
            }
            [drop, object_type, if_kw, exists_kw]
                if drop == "DROP"
                    && object_type == "ROLE"
                    && if_kw == "IF"
                    && exists_kw == "EXISTS" =>
            {
                true
            }
            [verb, object_type, .., comma]
                if matches!(verb.as_str(), "ALTER" | "DROP")
                    && object_type == "USER"
                    && comma == "," =>
            {
                true
            }
            [drop, object_type, .., comma]
                if drop == "DROP" && object_type == "ROLE" && comma == "," =>
            {
                true
            }
            _ => false,
        };
        user_slot.then_some(ExpectedObjectSuggestionKind::User)
    }

    fn mysql_user_account_slot_item(token: &SqlToken) -> Option<String> {
        match token {
            SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
            SqlToken::String(_) => Some("__VALUE__".to_string()),
            SqlToken::Symbol(symbol) if matches!(symbol.as_str(), "," | "@") => {
                Some(symbol.clone())
            }
            SqlToken::Symbol(_) | SqlToken::Comment(_) => None,
        }
    }

    fn expected_mysql_role_account_object_suggestion_kind(
        tokens: &[SqlToken],
        end: usize,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<ExpectedObjectSuggestionKind> {
        let items = Self::meaningful_tokens_before(tokens, end)
            .into_iter()
            .filter_map(Self::mysql_user_account_slot_item)
            .collect::<Vec<_>>();
        let role_or_account_slot = match items.as_slice() {
            [set, role] if set == "SET" && role == "ROLE" => true,
            [set, role, all, except]
                if set == "SET" && role == "ROLE" && all == "ALL" && except == "EXCEPT" =>
            {
                true
            }
            [set, role, .., comma] if set == "SET" && role == "ROLE" && comma == "," => true,
            [set, default, role] if set == "SET" && default == "DEFAULT" && role == "ROLE" => true,
            [set, default, role, .., separator]
                if set == "SET"
                    && default == "DEFAULT"
                    && role == "ROLE"
                    && matches!(separator.as_str(), "," | "TO") =>
            {
                true
            }
            _ => false,
        };
        (role_or_account_slot
            || (completion_db_type_is_mariadb(db_type)
                && Self::mariadb_create_role_admin_account_slot(&items)))
        .then_some(ExpectedObjectSuggestionKind::User)
    }

    fn mariadb_create_role_admin_account_slot(items: &[String]) -> bool {
        if items.first().map(String::as_str) != Some("CREATE") {
            return false;
        }

        let mut idx = 1;
        if items.get(idx).map(String::as_str) == Some("OR")
            && items.get(idx + 1).map(String::as_str) == Some("REPLACE")
        {
            idx += 2;
        }
        if items.get(idx).map(String::as_str) != Some("ROLE") {
            return false;
        }
        idx += 1;
        if items.get(idx).map(String::as_str) == Some("IF") {
            if items.get(idx + 1).map(String::as_str) != Some("NOT")
                || items.get(idx + 2).map(String::as_str) != Some("EXISTS")
            {
                return false;
            }
            idx += 3;
        }
        if idx >= items.len() {
            return false;
        }

        idx += 1;
        matches!(
            items.get(idx..),
            Some([with_kw, admin]) if with_kw == "WITH" && admin == "ADMIN"
        )
    }

    fn expected_mysql_set_password_account_object_suggestion_kind(
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<ExpectedObjectSuggestionKind> {
        let items = Self::meaningful_tokens_before(tokens, end)
            .into_iter()
            .filter_map(Self::mysql_user_account_slot_item)
            .collect::<Vec<_>>();
        let account_slot = matches!(
            items.as_slice(),
            [set, password, for_kw] if set == "SET" && password == "PASSWORD" && for_kw == "FOR"
        );
        account_slot.then_some(ExpectedObjectSuggestionKind::User)
    }

    fn expected_mysql_definer_account_object_suggestion_kind(
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<ExpectedObjectSuggestionKind> {
        let items = Self::meaningful_tokens_before(tokens, end)
            .into_iter()
            .filter_map(|token| match token {
                SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
                SqlToken::String(_) => Some("__VALUE__".to_string()),
                SqlToken::Symbol(symbol) if matches!(symbol.as_str(), "=" | "@") => {
                    Some(symbol.clone())
                }
                SqlToken::Symbol(_) | SqlToken::Comment(_) => None,
            })
            .collect::<Vec<_>>();
        if !matches!(items.first().map(String::as_str), Some("CREATE" | "ALTER")) {
            return None;
        }
        let definer_idx = items.iter().rposition(|item| item == "DEFINER")?;
        if definer_idx >= 2
            && matches!(
                (items.get(definer_idx - 2), items.get(definer_idx - 1)),
                (Some(sql), Some(security)) if sql == "SQL" && security == "SECURITY"
            )
        {
            return None;
        }

        let account_tail = items.get(definer_idx + 1..).unwrap_or(&[]);
        let user_slot = match account_tail {
            [] => true,
            [eq] if eq == "=" => true,
            _ => false,
        };
        user_slot.then_some(ExpectedObjectSuggestionKind::User)
    }

    fn expected_mysql_index_cache_object_suggestion_kind(
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<ExpectedObjectSuggestionKind> {
        let items: Vec<String> = Self::meaningful_tokens_before(tokens, end)
            .into_iter()
            .filter_map(|token| match token {
                SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
                SqlToken::String(_) => Some("__VALUE__".to_string()),
                SqlToken::Symbol(symbol) if symbol == "," => Some(symbol.clone()),
                SqlToken::Symbol(_) | SqlToken::Comment(_) => None,
            })
            .collect();

        let table_tail = match items.as_slice() {
            [cache_kw, index_kw, rest @ ..] if cache_kw == "CACHE" && index_kw == "INDEX" => rest,
            [load_kw, index_kw, into_kw, cache_kw, rest @ ..]
                if load_kw == "LOAD"
                    && index_kw == "INDEX"
                    && into_kw == "INTO"
                    && cache_kw == "CACHE" =>
            {
                rest
            }
            _ => return None,
        };
        let segment_start = table_tail
            .iter()
            .rposition(|item| item == ",")
            .map_or(0, |idx| idx + 1);
        let segment = &table_tail[segment_start..];
        segment
            .is_empty()
            .then_some(ExpectedObjectSuggestionKind::Table)
    }

    fn expected_mysql_handler_table_object_suggestion_kind(
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<ExpectedObjectSuggestionKind> {
        let words = Self::meaningful_tokens_before(tokens, end)
            .into_iter()
            .filter_map(|token| match token {
                SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
                SqlToken::Symbol(_) | SqlToken::String(_) | SqlToken::Comment(_) => None,
            })
            .collect::<Vec<_>>();
        matches!(words.as_slice(), [handler] if handler == "HANDLER")
            .then_some(ExpectedObjectSuggestionKind::Table)
    }

    /// The grantee slot of `GRANT … TO <grantee>` / `REVOKE … FROM <grantee>`
    /// (including a role grant, `GRANT role TO <grantee>`) names a user or role,
    /// never a schema object. Resolves the slot right after the `TO`/`FROM`
    /// separator to the `User` kind so the whole-catalog dump is suppressed
    /// there. Multi-grantee continuations after a comma stay in the same grantee
    /// slot (`GRANT ... TO alice, |`, `REVOKE ... FROM alice, |`).
    fn expected_grant_revoke_grantee_kind(
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<ExpectedObjectSuggestionKind> {
        let (separator_idx, separator) =
            Self::grant_revoke_grantee_separator_before_cursor(tokens, end)?;
        let verb = Self::grant_revoke_verb_before_separator(tokens, separator_idx)?;
        let expected_separator = if verb == "GRANT" { "TO" } else { "FROM" };
        (separator == expected_separator).then_some(ExpectedObjectSuggestionKind::User)
    }

    fn grant_revoke_grantee_separator_before_cursor(
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<(usize, String)> {
        let last_idx = Self::previous_non_comment_token_index(tokens, end)?;
        match tokens.get(last_idx)? {
            SqlToken::Word(word) if matches!(word.to_ascii_uppercase().as_str(), "TO" | "FROM") => {
                Some((last_idx, word.to_ascii_uppercase()))
            }
            SqlToken::Symbol(symbol) if symbol == "," => {
                let mut scan_end = last_idx;
                while let Some(idx) = Self::previous_non_comment_token_index(tokens, scan_end) {
                    if let Some(SqlToken::Word(word)) = tokens.get(idx) {
                        let upper = word.to_ascii_uppercase();
                        if matches!(upper.as_str(), "TO" | "FROM") {
                            return Some((idx, upper));
                        }
                        if matches!(upper.as_str(), "GRANT" | "REVOKE") {
                            return None;
                        }
                    }
                    scan_end = idx;
                }
                None
            }
            _ => None,
        }
    }

    fn grant_revoke_verb_before_separator(
        tokens: &[SqlToken],
        separator_idx: usize,
    ) -> Option<&str> {
        for token in tokens.get(..separator_idx.min(tokens.len()))? {
            if let SqlToken::Word(word) = token {
                if word.eq_ignore_ascii_case("GRANT") {
                    return Some("GRANT");
                }
                if word.eq_ignore_ascii_case("REVOKE") {
                    return Some("REVOKE");
                }
            }
        }
        None
    }

    fn previous_non_comment_token_index(tokens: &[SqlToken], end: usize) -> Option<usize> {
        tokens
            .get(..end.min(tokens.len()))?
            .iter()
            .enumerate()
            .rev()
            .find(|(_, token)| !matches!(token, SqlToken::Comment(_)))
            .map(|(idx, _)| idx)
    }

    fn token_word_is_part_of_qualified_identifier(tokens: &[SqlToken], idx: usize) -> bool {
        matches!(tokens.get(idx), Some(SqlToken::Word(_)))
            && (matches!(
                Self::previous_non_comment_token_index(tokens, idx)
                    .and_then(|prev_idx| tokens.get(prev_idx)),
                Some(SqlToken::Symbol(sym)) if sym == "."
            ) || matches!(
                Self::next_non_comment_token_index(tokens, idx.saturating_add(1))
                    .and_then(|next_idx| tokens.get(next_idx)),
                Some(SqlToken::Symbol(sym)) if sym == "."
            ))
    }

    fn next_non_comment_token_index(tokens: &[SqlToken], start: usize) -> Option<usize> {
        tokens
            .iter()
            .enumerate()
            .skip(start.min(tokens.len()))
            .find(|(_, token)| !matches!(token, SqlToken::Comment(_)))
            .map(|(idx, _)| idx)
    }

    fn expected_grant_revoke_object_suggestion_kind(
        words: &[String],
    ) -> Option<ExpectedObjectSuggestionKind> {
        if words.last().is_none_or(|word| word != "ON") {
            return None;
        }
        let verb_idx = words
            .iter()
            .rposition(|word| matches!(word.as_str(), "GRANT" | "REVOKE" | "AUDIT" | "NOAUDIT"))?;
        let privilege_words = words.get(verb_idx + 1..words.len().saturating_sub(1))?;
        if privilege_words.is_empty() {
            return None;
        }
        if privilege_words
            .iter()
            .all(|word| Self::is_executable_object_privilege(word))
        {
            return Some(ExpectedObjectSuggestionKind::Executable);
        }
        if privilege_words
            .iter()
            .all(|word| Self::is_relation_or_sequence_object_privilege(word))
        {
            return Some(ExpectedObjectSuggestionKind::RelationOrSequence);
        }
        // `AUDIT`/`NOAUDIT` also accept audit options that are broader than
        // GRANT/REVOKE object privileges. Keep those object audit slots open,
        // but only after the precise privilege families above have had a chance
        // to narrow the catalog.
        if matches!(words[verb_idx].as_str(), "AUDIT" | "NOAUDIT") {
            return Some(ExpectedObjectSuggestionKind::SchemaObject);
        }

        None
    }

    fn expected_oracle_audit_user_object_suggestion_kind(
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<ExpectedObjectSuggestionKind> {
        let last_idx = Self::previous_non_comment_token_index(tokens, end)?;
        let mut scan_end = last_idx;
        let mut by_idx = match tokens.get(last_idx)? {
            SqlToken::Word(word) if word.eq_ignore_ascii_case("BY") => Some(last_idx),
            SqlToken::Symbol(symbol) if symbol == "," => None,
            _ => return None,
        };

        if by_idx.is_none() {
            while let Some(idx) = Self::previous_non_comment_token_index(tokens, scan_end) {
                if let Some(SqlToken::Word(word)) = tokens.get(idx) {
                    let upper = word.to_ascii_uppercase();
                    if upper == "BY" {
                        by_idx = Some(idx);
                        break;
                    }
                    if matches!(upper.as_str(), "AUDIT" | "NOAUDIT") {
                        return None;
                    }
                }
                scan_end = idx;
            }
        }

        let by_idx = by_idx?;
        let mut audit_idx = None;
        let mut has_on_between_audit_and_by = false;
        for (idx, token) in tokens.iter().enumerate().take(by_idx) {
            if let SqlToken::Word(word) = token {
                let upper = word.to_ascii_uppercase();
                if matches!(upper.as_str(), "AUDIT" | "NOAUDIT") {
                    audit_idx = Some(idx);
                    has_on_between_audit_and_by = false;
                } else if upper == "ON" && audit_idx.is_some() {
                    has_on_between_audit_and_by = true;
                }
            }
        }

        // Object-audit `... ON obj BY |` is the access/session mode slot, not a
        // user list. Plain `AUDIT ... BY |` and comma continuations name users.
        audit_idx
            .is_some()
            .then_some(())
            .filter(|_| !has_on_between_audit_and_by)
            .map(|_| ExpectedObjectSuggestionKind::User)
    }

    fn expected_oracle_associate_statistics_object_suggestion_kind(
        tokens: &[SqlToken],
        end: usize,
    ) -> Option<ExpectedObjectSuggestionKind> {
        let last_idx = Self::previous_non_comment_token_index(tokens, end)?;
        let mut scan_end = last_idx;
        let mut kind_idx = match tokens.get(last_idx)? {
            SqlToken::Word(word)
                if matches!(
                    word.to_ascii_uppercase().as_str(),
                    "COLUMNS" | "FUNCTIONS" | "PACKAGES" | "TYPES" | "INDEXES" | "INDEXTYPES"
                ) =>
            {
                Some(last_idx)
            }
            SqlToken::Symbol(symbol) if symbol == "," => None,
            _ => return None,
        };

        if kind_idx.is_none() {
            while let Some(idx) = Self::previous_non_comment_token_index(tokens, scan_end) {
                if let Some(SqlToken::Word(word)) = tokens.get(idx) {
                    let upper = word.to_ascii_uppercase();
                    if matches!(
                        upper.as_str(),
                        "COLUMNS" | "FUNCTIONS" | "PACKAGES" | "TYPES" | "INDEXES" | "INDEXTYPES"
                    ) {
                        kind_idx = Some(idx);
                        break;
                    }
                    if matches!(upper.as_str(), "ASSOCIATE" | "DISASSOCIATE") {
                        return None;
                    }
                }
                scan_end = idx;
            }
        }

        let kind_idx = kind_idx?;
        let mut has_statistics = false;
        let mut has_separator = false;
        let mut has_associate_head = false;
        for token in tokens.iter().take(kind_idx) {
            if let SqlToken::Word(word) = token {
                let upper = word.to_ascii_uppercase();
                if matches!(upper.as_str(), "ASSOCIATE" | "DISASSOCIATE") {
                    has_associate_head = true;
                    has_statistics = false;
                    has_separator = false;
                } else if has_associate_head && upper == "STATISTICS" {
                    has_statistics = true;
                } else if has_associate_head && matches!(upper.as_str(), "WITH" | "FROM") {
                    has_separator = true;
                }
            }
        }
        if !(has_associate_head && has_statistics && has_separator) {
            return None;
        }

        match tokens.get(kind_idx)? {
            SqlToken::Word(word) => match word.to_ascii_uppercase().as_str() {
                "COLUMNS" => Some(ExpectedObjectSuggestionKind::ColumnOwner),
                "FUNCTIONS" => Some(ExpectedObjectSuggestionKind::Function),
                "PACKAGES" => Some(ExpectedObjectSuggestionKind::Package),
                "TYPES" => Some(ExpectedObjectSuggestionKind::Type),
                "INDEXES" => Some(ExpectedObjectSuggestionKind::Index),
                "INDEXTYPES" => Some(ExpectedObjectSuggestionKind::Indextype),
                _ => None,
            },
            _ => None,
        }
    }

    fn cursor_is_at_mysql_oracle_only_associate_statistics_slot_for_context(
        deep_ctx: &intellisense_context::CursorContext,
        exclude_current_identifier_chain: bool,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        if !crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return false;
        }

        let tokens = deep_ctx.statement_tokens.as_ref();
        let context_end = Self::expected_suggestion_context_end(
            tokens,
            deep_ctx.cursor_token_len,
            exclude_current_identifier_chain,
        );
        if !Self::cursor_has_statement_start_anchor(
            tokens,
            context_end,
            &["ASSOCIATE", "DISASSOCIATE"],
        ) {
            return false;
        }

        let words = Self::previous_meaningful_words_upper(tokens, context_end, 16);
        matches!(
            words.first().map(String::as_str),
            Some("ASSOCIATE" | "DISASSOCIATE")
        ) && words.iter().any(|word| word == "STATISTICS")
    }

    fn is_executable_object_privilege(word: &str) -> bool {
        matches!(word, "EXECUTE" | "DEBUG")
    }

    fn is_relation_or_sequence_object_privilege(word: &str) -> bool {
        matches!(
            word,
            "SELECT"
                | "READ"
                | "INSERT"
                | "UPDATE"
                | "DELETE"
                | "REFERENCES"
                | "INDEX"
                | "ALTER"
                | "FLASHBACK"
                | "QUERY"
                | "REWRITE"
        )
    }

    fn expected_suggestion_context_end(
        tokens: &[SqlToken],
        cursor_token_len: usize,
        exclude_current_identifier_chain: bool,
    ) -> usize {
        if !exclude_current_identifier_chain {
            return cursor_token_len.min(tokens.len());
        }

        Self::current_qualified_identifier_chain_start(tokens, cursor_token_len)
            .unwrap_or(cursor_token_len)
            .min(tokens.len())
    }

    fn expected_keyword_suggestion_context_end(
        tokens: &[SqlToken],
        cursor_token_len: usize,
        prefix: &str,
    ) -> usize {
        if !prefix.is_empty() && cursor_token_len > 0 {
            match tokens.get(cursor_token_len.saturating_sub(1)) {
                Some(SqlToken::Word(word)) if word.to_ascii_uppercase().starts_with(&prefix.to_ascii_uppercase()) => {
                    return cursor_token_len - 1;
                }
                _ => {}
            }
        }
        if !prefix.is_empty()
            && tokens
                .get(cursor_token_len)
                .is_some_and(|token| matches!(token, SqlToken::Word(word) if word.to_ascii_uppercase().starts_with(&prefix.to_ascii_uppercase())))
        {
            return cursor_token_len.min(tokens.len());
        }
        let end =
            Self::expected_suggestion_context_end(tokens, cursor_token_len, !prefix.is_empty());
        if prefix.is_empty() || end < cursor_token_len || cursor_token_len == 0 {
            return end;
        }

        end
    }

    fn collect_expected_object_suggestions_for_kind(
        data: &mut IntellisenseData,
        prefix: &str,
        kind: ExpectedObjectSuggestionKind,
    ) -> Vec<String> {
        Self::collect_expected_object_suggestions_for_kind_for_db(data, prefix, kind, None)
    }

    fn collect_expected_object_suggestions_for_kind_for_db(
        data: &mut IntellisenseData,
        prefix: &str,
        kind: ExpectedObjectSuggestionKind,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Vec<String> {
        Self::collect_filtered_expected_object_suggestions_for_kind_for_db(
            data, prefix, kind, db_type,
        )
    }

    fn resolve_expected_object_completion_suggestions(
        intellisense_data: &Arc<Mutex<IntellisenseData>>,
        prefix: &str,
        qualifier: Option<&str>,
        at_dedicated_column_slot: bool,
        deep_ctx: &intellisense_context::CursorContext,
        db_type: crate::db::DatabaseType,
        source_allowance: CompletionSourceAllowance,
    ) -> (Option<ExpectedObjectSuggestionKind>, Vec<String>) {
        let expected_object_kind = if qualifier.is_none() && !at_dedicated_column_slot {
            Self::expected_object_suggestion_kind_for_db(prefix, None, deep_ctx, Some(db_type))
        } else {
            None
        };
        let suggestions = if !at_dedicated_column_slot
            && (source_allowance.expected_object_suggestions
                || expected_object_kind
                    .is_some_and(Self::expected_object_kind_overrides_source_allowance))
        {
            Self::collect_expected_object_suggestions_for_completion_context(
                intellisense_data,
                prefix,
                expected_object_kind,
                Some(db_type),
            )
        } else {
            Vec::new()
        };
        (expected_object_kind, suggestions)
    }

    fn expected_object_kind_overrides_source_allowance(
        kind: ExpectedObjectSuggestionKind,
    ) -> bool {
        !matches!(kind, ExpectedObjectSuggestionKind::NoSuggestions)
    }

    fn collect_expected_object_suggestions_for_completion_context(
        intellisense_data: &Arc<Mutex<IntellisenseData>>,
        prefix: &str,
        kind: Option<ExpectedObjectSuggestionKind>,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Vec<String> {
        let Some(kind) = kind else {
            return Vec::new();
        };

        let mut data = intellisense_data
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        Self::collect_filtered_expected_object_suggestions_for_kind_for_db(
            &mut data, prefix, kind, db_type,
        )
    }

    fn collect_filtered_expected_object_suggestions_for_kind_for_db(
        data: &mut IntellisenseData,
        prefix: &str,
        kind: ExpectedObjectSuggestionKind,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Vec<String> {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            match kind {
                ExpectedObjectSuggestionKind::Routine => {
                    return data.get_procedure_object_suggestions(prefix);
                }
                ExpectedObjectSuggestionKind::Executable => {
                    return Self::merge_suggestions_with_context_aliases(
                        data.get_procedure_object_suggestions(prefix),
                        data.get_function_object_suggestions(prefix),
                        false,
                    );
                }
                ExpectedObjectSuggestionKind::RelationOrSequence
                | ExpectedObjectSuggestionKind::ColumnOwner => {
                    let suggestions = data.get_table_object_suggestions(prefix);
                    return Self::merge_suggestions_with_context_aliases(
                        suggestions,
                        data.get_view_object_suggestions(prefix),
                        false,
                    );
                }
                _ => {}
            }
        }

        let mut suggestions = match kind {
            ExpectedObjectSuggestionKind::NoSuggestions => Vec::new(),
            ExpectedObjectSuggestionKind::SchemaObject => {
                let mut suggestions = data.get_object_suggestions(prefix);
                suggestions.retain(|suggestion| {
                    !Self::matches_string_list_case_insensitive(&data.users, suggestion)
                });
                suggestions
            }
            ExpectedObjectSuggestionKind::Routine => data.get_routine_object_suggestions(prefix),
            ExpectedObjectSuggestionKind::Executable => {
                data.get_executable_object_suggestions(prefix)
            }
            ExpectedObjectSuggestionKind::RelationOrSequence => {
                data.get_relation_or_sequence_object_suggestions(prefix)
            }
            ExpectedObjectSuggestionKind::ColumnOwner => {
                data.get_column_owner_object_suggestions(prefix)
            }
            ExpectedObjectSuggestionKind::Table => data.get_table_object_suggestions(prefix),
            ExpectedObjectSuggestionKind::View => data.get_view_object_suggestions(prefix),
            ExpectedObjectSuggestionKind::MaterializedView => {
                data.get_materialized_view_object_suggestions(prefix)
            }
            ExpectedObjectSuggestionKind::Type => data.get_type_object_suggestions(prefix),
            ExpectedObjectSuggestionKind::Trigger => data.get_trigger_object_suggestions(prefix),
            ExpectedObjectSuggestionKind::Event => data.get_event_object_suggestions(prefix),
            ExpectedObjectSuggestionKind::Index => data.get_index_object_suggestions(prefix),
            ExpectedObjectSuggestionKind::Procedure => {
                data.get_procedure_object_suggestions(prefix)
            }
            ExpectedObjectSuggestionKind::Function => data.get_function_object_suggestions(prefix),
            ExpectedObjectSuggestionKind::Package => data.get_package_object_suggestions(prefix),
            ExpectedObjectSuggestionKind::Sequence => data.get_sequence_object_suggestions(prefix),
            ExpectedObjectSuggestionKind::Synonym => data.get_synonym_object_suggestions(prefix),
            ExpectedObjectSuggestionKind::PublicSynonym => {
                data.get_public_synonym_object_suggestions(prefix)
            }
            ExpectedObjectSuggestionKind::DatabaseLink => {
                data.get_database_link_object_suggestions(prefix)
            }
            ExpectedObjectSuggestionKind::Directory => {
                data.get_directory_object_suggestions(prefix)
            }
            ExpectedObjectSuggestionKind::Library => data.get_library_object_suggestions(prefix),
            ExpectedObjectSuggestionKind::Cluster => data.get_cluster_object_suggestions(prefix),
            ExpectedObjectSuggestionKind::Context => data.get_context_object_suggestions(prefix),
            ExpectedObjectSuggestionKind::Dimension => {
                data.get_dimension_object_suggestions(prefix)
            }
            ExpectedObjectSuggestionKind::Operator => data.get_operator_object_suggestions(prefix),
            ExpectedObjectSuggestionKind::Indextype => {
                data.get_indextype_object_suggestions(prefix)
            }
            ExpectedObjectSuggestionKind::Edition => data.get_edition_object_suggestions(prefix),
            ExpectedObjectSuggestionKind::JavaSource => {
                data.get_java_source_object_suggestions(prefix)
            }
            ExpectedObjectSuggestionKind::JavaClass => {
                data.get_java_class_object_suggestions(prefix)
            }
            ExpectedObjectSuggestionKind::JavaResource => {
                data.get_java_resource_object_suggestions(prefix)
            }
            ExpectedObjectSuggestionKind::Database => data.get_schema_suggestions(prefix),
            ExpectedObjectSuggestionKind::User => data.get_user_suggestions(prefix),
        };

        if !matches!(kind, ExpectedObjectSuggestionKind::NoSuggestions)
            && !prefix.is_empty()
            && !matches!(
                kind,
                ExpectedObjectSuggestionKind::SchemaObject | ExpectedObjectSuggestionKind::User
            )
            && !crate::sql_text::mysql_compatibility_for_sql("", db_type)
        {
            suggestions = Self::merge_suggestions_with_context_aliases(
                suggestions,
                data.get_user_suggestions(prefix),
                false,
            );
        }

        suggestions
    }

    /// Prefix-aware structural keywords whose current token is deliberately
    /// excluded from `context_end`. These slots cannot be recovered from a
    /// catalog-wide keyword list: each keyword is admitted only by its local
    /// grammar anchor, so a missing exact parser phase never widens completion.
    fn expected_precise_typed_structural_keyword_candidates(
        prefix: &str,
        tokens: &[SqlToken],
        end: usize,
        phase: intellisense_context::SqlPhase,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<&'static [&'static str]> {
        if prefix.is_empty() {
            return None;
        }

        let matches_prefix = |keyword: &str| {
            crate::ui::intellisense::suggestion_matches_completion_prefix(keyword, prefix)
        };
        let prefix_upper = prefix.to_ascii_uppercase();
        let typed_idx = [end, end.saturating_sub(1)].into_iter().find(|idx| {
            matches!(
                tokens.get(*idx),
                Some(SqlToken::Word(word))
                    if word.to_ascii_uppercase().starts_with(&prefix_upper)
            )
        });
        let structural_end = typed_idx.unwrap_or(end).min(tokens.len());
        let words = Self::words_for_keyword_slot(tokens, structural_end);
        let last = words.last().map(String::as_str);

        if matches_prefix("BODY") {
            if let Some(show_idx) = words.iter().rposition(|word| word == "SHOW") {
                let tail = &words[show_idx..];
                if matches!(
                    tail,
                    [show, errors, kind]
                        if show == "SHOW"
                            && errors == "ERRORS"
                            && matches!(kind.as_str(), "PACKAGE" | "TYPE")
                ) || matches!(
                    tail,
                    [show, errors, kind, typed]
                        if show == "SHOW"
                            && errors == "ERRORS"
                            && matches!(kind.as_str(), "PACKAGE" | "TYPE")
                            && crate::ui::intellisense::suggestion_matches_completion_prefix(
                                "BODY", typed,
                            )
                ) {
                    return Some(&["BODY"]);
                }
            }
        }

        if matches_prefix("CONSTANT")
            && !crate::sql_text::mysql_compatibility_for_sql("", db_type)
            && Self::cursor_is_in_plsql_declaration_region(tokens, structural_end)
            && typed_idx.is_some_and(|current_idx| {
                Self::next_non_comment_token_index(tokens, current_idx + 1)
                    .and_then(|idx| Self::token_word(tokens.get(idx)?))
                    .is_some_and(|word| !Self::is_plsql_non_type_keyword(word))
            })
            && Self::meaningful_tokens_before(tokens, structural_end)
                .last()
                .is_some_and(|token| {
                    matches!(token, SqlToken::Word(word) if !Self::is_plsql_non_type_keyword(word))
                })
        {
            return Some(&["CONSTANT"]);
        }

        if !crate::sql_text::mysql_compatibility_for_sql("", db_type)
            && matches!(
                words.as_slice(),
                [alter, scope, set]
                    if alter == "ALTER"
                        && matches!(scope.as_str(), "SESSION" | "SYSTEM")
                        && set == "SET"
            )
        {
            const SESSION_PARAMETERS: &[&str] = &[
                "CURRENT_SCHEMA",
                "NLS_DATE_FORMAT",
                "NLS_DATE_LANGUAGE",
                "NLS_TIMESTAMP_FORMAT",
                "NLS_TIMESTAMP_TZ_FORMAT",
                "OPTIMIZER_MODE",
            ];
            const SYSTEM_PARAMETERS: &[&str] = &[
                "DB_RECOVERY_FILE_DEST",
                "OPEN_CURSORS",
                "OPTIMIZER_MODE",
            ];
            return if words.get(1).map(String::as_str) == Some("SESSION") {
                Some(SESSION_PARAMETERS)
            } else {
                Some(SYSTEM_PARAMETERS)
            };
        }

        if matches_prefix("AS") {
            if last == Some("STORE")
                && words.iter().any(|word| word == "LOB")
                && words.iter().any(|word| matches!(word.as_str(), "CREATE" | "ALTER"))
            {
                return Some(&["AS"]);
            }

            let current_is_followed_by_open_paren = typed_idx
                .and_then(|current_idx| Self::next_non_comment_token_index(tokens, current_idx + 1))
                .is_some_and(|next_idx| {
                    matches!(tokens.get(next_idx), Some(SqlToken::Symbol(symbol)) if symbol == "(")
                });
            if current_is_followed_by_open_paren {
                if let Some(with_idx) = words.iter().rposition(|word| word == "WITH") {
                    let tail = &words[with_idx + 1..];
                    if !tail.is_empty()
                        && tail.last().is_some_and(|word| {
                            !matches!(
                                word.as_str(),
                                "AS" | "SELECT" | "FROM" | "WHERE" | "JOIN" | "ON"
                            )
                        })
                    {
                        return Some(&["AS"]);
                    }
                }
                if let Some(window_idx) = words.iter().rposition(|word| word == "WINDOW") {
                    let tail = &words[window_idx + 1..];
                    if !tail.is_empty()
                        && tail.last().is_some_and(|word| {
                            !matches!(word.as_str(), "AS" | "ORDER" | "PARTITION" | "ROWS" | "RANGE")
                        })
                    {
                        return Some(&["AS"]);
                    }
                }
            }

            let in_oracle_unpivot_alias_mapping = !crate::sql_text::mysql_compatibility_for_sql(
                "", db_type,
            ) && typed_idx.is_some_and(|current_idx| {
                let previous_is_identifier = Self::previous_non_comment_token_index(
                    tokens,
                    current_idx,
                )
                .is_some_and(|idx| matches!(tokens.get(idx), Some(SqlToken::Word(_))));
                let next_is_label = Self::next_non_comment_token_index(tokens, current_idx + 1)
                    .is_some_and(|idx| matches!(tokens.get(idx), Some(SqlToken::String(_))));
                let unpivot_idx = tokens
                    .get(..current_idx)
                    .unwrap_or(&[])
                    .iter()
                    .rposition(|token| {
                        matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("UNPIVOT"))
                    });
                let in_idx = tokens
                    .get(..current_idx)
                    .unwrap_or(&[])
                    .iter()
                    .rposition(|token| {
                        matches!(token, SqlToken::Word(word) if word.eq_ignore_ascii_case("IN"))
                    });
                previous_is_identifier
                    && next_is_label
                    && unpivot_idx.zip(in_idx).is_some_and(|(unpivot_idx, in_idx)| {
                        unpivot_idx < in_idx
                    })
            });
            if in_oracle_unpivot_alias_mapping {
                return Some(&["AS"]);
            }

            let define_idx = words.iter().rposition(|word| word == "DEFINE");
            let in_match_recognize_definition = define_idx.is_some_and(|define_idx| {
                (words.iter().any(|word| word == "MATCH_RECOGNIZE")
                    || words.len() == define_idx + 2)
                    && typed_idx.is_some_and(|current_idx| {
                    let previous = Self::previous_non_comment_token_index(tokens, current_idx)
                        .and_then(|idx| Self::token_word(tokens.get(idx)?));
                    let next = Self::next_non_comment_token_index(tokens, current_idx + 1)
                        .and_then(|idx| Self::token_word(tokens.get(idx)?));
                    previous.zip(next).is_some_and(|(previous, next)| {
                        previous.eq_ignore_ascii_case(next)
                    })
                    })
            });
            let in_model_measure_definition = words
                .iter()
                .rposition(|word| word == "MODEL")
                .zip(words.iter().rposition(|word| word == "MEASURES"))
                .is_some_and(|(model_idx, measures_idx)| model_idx < measures_idx)
                && words
                    .iter()
                    .rposition(|word| word == "RULES")
                    .is_none_or(|rules_idx| {
                        words
                            .iter()
                            .rposition(|word| word == "MEASURES")
                            .is_some_and(|measures_idx| rules_idx < measures_idx)
                    });
            if in_match_recognize_definition || in_model_measure_definition {
                return Some(&["AS"]);
            }

            if matches!(
                phase,
                intellisense_context::SqlPhase::SelectList
                    | intellisense_context::SqlPhase::PivotClause
                    | intellisense_context::SqlPhase::MatchRecognizeClause
                    | intellisense_context::SqlPhase::ModelClause
            ) && Self::cursor_follows_complete_operand(tokens, structural_end) == Some(true)
            {
                return Some(&["AS"]);
            }
        }

        if matches_prefix("END") {
            let has_plsql_body = words.iter().any(|word| word == "BEGIN")
                && words.iter().any(|word| {
                    matches!(
                        word.as_str(),
                        "DECLARE" | "FUNCTION" | "PACKAGE" | "PROCEDURE" | "TRIGGER" | "TYPE"
                    )
                });
            if has_plsql_body {
                return Some(&["END"]);
            }
        }

        None
    }

    fn matches_string_list_case_insensitive(values: &[String], candidate: &str) -> bool {
        values
            .iter()
            .any(|value| value.eq_ignore_ascii_case(candidate))
    }
    fn expected_qualifier_member_kinds(
        kind: ExpectedObjectSuggestionKind,
    ) -> Option<&'static [QualifiedMemberKind]> {
        match kind {
            ExpectedObjectSuggestionKind::NoSuggestions => Some(&[]),
            ExpectedObjectSuggestionKind::SchemaObject => Some(&[
                QualifiedMemberKind::Table,
                QualifiedMemberKind::View,
                QualifiedMemberKind::MaterializedView,
                QualifiedMemberKind::Type,
                QualifiedMemberKind::Trigger,
                QualifiedMemberKind::Event,
                QualifiedMemberKind::Index,
                QualifiedMemberKind::Procedure,
                QualifiedMemberKind::Function,
                QualifiedMemberKind::Package,
                QualifiedMemberKind::Sequence,
                QualifiedMemberKind::Synonym,
                QualifiedMemberKind::PublicSynonym,
                QualifiedMemberKind::DatabaseLink,
                QualifiedMemberKind::Directory,
                QualifiedMemberKind::Library,
                QualifiedMemberKind::Cluster,
                QualifiedMemberKind::Context,
                QualifiedMemberKind::Dimension,
                QualifiedMemberKind::Operator,
                QualifiedMemberKind::Indextype,
                QualifiedMemberKind::Edition,
                QualifiedMemberKind::JavaSource,
                QualifiedMemberKind::JavaClass,
                QualifiedMemberKind::JavaResource,
            ]),
            ExpectedObjectSuggestionKind::Routine => Some(&[
                QualifiedMemberKind::Procedure,
                QualifiedMemberKind::Function,
                QualifiedMemberKind::Package,
            ]),
            ExpectedObjectSuggestionKind::Executable => Some(&[
                QualifiedMemberKind::Procedure,
                QualifiedMemberKind::Function,
                QualifiedMemberKind::Package,
                QualifiedMemberKind::Type,
            ]),
            ExpectedObjectSuggestionKind::RelationOrSequence => Some(&[
                QualifiedMemberKind::Table,
                QualifiedMemberKind::View,
                QualifiedMemberKind::MaterializedView,
                QualifiedMemberKind::Sequence,
                QualifiedMemberKind::Synonym,
                QualifiedMemberKind::PublicSynonym,
            ]),
            ExpectedObjectSuggestionKind::ColumnOwner => Some(&[
                QualifiedMemberKind::Table,
                QualifiedMemberKind::View,
                QualifiedMemberKind::MaterializedView,
                QualifiedMemberKind::Synonym,
                QualifiedMemberKind::PublicSynonym,
            ]),
            ExpectedObjectSuggestionKind::Table => Some(&[QualifiedMemberKind::Table]),
            ExpectedObjectSuggestionKind::View => Some(&[QualifiedMemberKind::View]),
            ExpectedObjectSuggestionKind::MaterializedView => {
                Some(&[QualifiedMemberKind::MaterializedView])
            }
            ExpectedObjectSuggestionKind::Type => Some(&[QualifiedMemberKind::Type]),
            ExpectedObjectSuggestionKind::Trigger => Some(&[QualifiedMemberKind::Trigger]),
            ExpectedObjectSuggestionKind::Event => Some(&[QualifiedMemberKind::Event]),
            ExpectedObjectSuggestionKind::Index => Some(&[QualifiedMemberKind::Index]),
            ExpectedObjectSuggestionKind::Procedure => Some(&[QualifiedMemberKind::Procedure]),
            ExpectedObjectSuggestionKind::Function => Some(&[QualifiedMemberKind::Function]),
            ExpectedObjectSuggestionKind::Package => Some(&[QualifiedMemberKind::Package]),
            ExpectedObjectSuggestionKind::Sequence => Some(&[QualifiedMemberKind::Sequence]),
            ExpectedObjectSuggestionKind::Synonym => Some(&[QualifiedMemberKind::Synonym]),
            ExpectedObjectSuggestionKind::PublicSynonym => {
                Some(&[QualifiedMemberKind::PublicSynonym])
            }
            ExpectedObjectSuggestionKind::DatabaseLink => {
                Some(&[QualifiedMemberKind::DatabaseLink])
            }
            ExpectedObjectSuggestionKind::Directory => Some(&[QualifiedMemberKind::Directory]),
            ExpectedObjectSuggestionKind::Library => Some(&[QualifiedMemberKind::Library]),
            ExpectedObjectSuggestionKind::Cluster => Some(&[QualifiedMemberKind::Cluster]),
            ExpectedObjectSuggestionKind::Context => Some(&[QualifiedMemberKind::Context]),
            ExpectedObjectSuggestionKind::Dimension => Some(&[QualifiedMemberKind::Dimension]),
            ExpectedObjectSuggestionKind::Operator => Some(&[QualifiedMemberKind::Operator]),
            ExpectedObjectSuggestionKind::Indextype => Some(&[QualifiedMemberKind::Indextype]),
            ExpectedObjectSuggestionKind::Edition => Some(&[QualifiedMemberKind::Edition]),
            ExpectedObjectSuggestionKind::JavaSource => Some(&[QualifiedMemberKind::JavaSource]),
            ExpectedObjectSuggestionKind::JavaClass => Some(&[QualifiedMemberKind::JavaClass]),
            ExpectedObjectSuggestionKind::JavaResource => {
                Some(&[QualifiedMemberKind::JavaResource])
            }
            ExpectedObjectSuggestionKind::Database => Some(&[]),
            ExpectedObjectSuggestionKind::User => Some(&[QualifiedMemberKind::User]),
        }
    }

    fn expected_qualifier_member_kinds_for_db(
        kind: ExpectedObjectSuggestionKind,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Option<&'static [QualifiedMemberKind]> {
        if crate::sql_text::mysql_compatibility_for_sql("", db_type) {
            return match kind {
                ExpectedObjectSuggestionKind::Routine => Some(&[QualifiedMemberKind::Procedure]),
                ExpectedObjectSuggestionKind::Executable => Some(&[
                    QualifiedMemberKind::Procedure,
                    QualifiedMemberKind::Function,
                ]),
                ExpectedObjectSuggestionKind::RelationOrSequence
                | ExpectedObjectSuggestionKind::ColumnOwner => {
                    Some(&[QualifiedMemberKind::Table, QualifiedMemberKind::View])
                }
                _ => Self::expected_qualifier_member_kinds(kind),
            };
        }

        Self::expected_qualifier_member_kinds(kind)
    }

    fn expected_object_kind_allows_relation_member_cache(
        kind: ExpectedObjectSuggestionKind,
    ) -> bool {
        matches!(
            kind,
            ExpectedObjectSuggestionKind::RelationOrSequence
                | ExpectedObjectSuggestionKind::ColumnOwner
        )
    }

    fn expected_object_kind_uses_typed_relation_member_cache(
        kind: ExpectedObjectSuggestionKind,
    ) -> bool {
        matches!(
            kind,
            ExpectedObjectSuggestionKind::Table
                | ExpectedObjectSuggestionKind::View
                | ExpectedObjectSuggestionKind::MaterializedView
        )
    }

    fn suggestion_matches_expected_object_kind_for_qualifier(
        data: &IntellisenseData,
        qualifier: &str,
        candidate: &str,
        kind: ExpectedObjectSuggestionKind,
        db_type: Option<crate::db::DatabaseType>,
    ) -> bool {
        let Some(expected_kinds) = Self::expected_qualifier_member_kinds_for_db(kind, db_type)
        else {
            return false;
        };
        if data.qualifier_member_has_kind_metadata(qualifier, candidate) {
            return data.qualifier_member_matches_kinds(qualifier, candidate, expected_kinds)
                == Some(true);
        }

        Self::expected_object_kind_allows_relation_member_cache(kind)
            && data.qualifier_relation_member_matches(qualifier, candidate)
    }

    #[cfg(test)]
    fn expected_member_suggestions_for_qualifier(
        data: &mut IntellisenseData,
        qualifier: &str,
        prefix: &str,
        deep_ctx: &intellisense_context::CursorContext,
    ) -> Vec<String> {
        Self::expected_member_suggestions_for_qualifier_for_db(
            data, qualifier, prefix, deep_ctx, None,
        )
    }

    fn expected_member_suggestions_for_qualifier_for_db(
        data: &mut IntellisenseData,
        qualifier: &str,
        prefix: &str,
        deep_ctx: &intellisense_context::CursorContext,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Vec<String> {
        let mut suggestions = data.get_member_suggestions(qualifier, prefix, false);
        let mut member_qualifier = qualifier.to_string();
        if suggestions.is_empty() {
            if let Some(target) =
                Self::oracle_synonym_target_with_member_cache(data, qualifier, false, db_type)
            {
                let target_suggestions = data.get_member_suggestions(&target, prefix, false);
                if !target_suggestions.is_empty() {
                    member_qualifier = target;
                    suggestions = target_suggestions;
                }
            }
        }
        let member_qualifier = member_qualifier.as_str();
        if !crate::sql_text::mysql_compatibility_for_sql("", db_type)
            && Self::cursor_is_at_plsql_exception_name(
                deep_ctx.statement_tokens.as_ref(),
                deep_ctx.cursor_token_len,
            )
        {
            suggestions.retain(|suggestion| {
                !Self::qualified_member_has_known_schema_object_kind(
                    data,
                    member_qualifier,
                    suggestion,
                )
            });
            return suggestions;
        }
        let forced_type_kind = Self::data_type_position_for_context_for_db(
            deep_ctx,
            true,
            db_type,
        )
        .is_some_and(|position| Self::data_type_position_allows_user_type_objects(position, db_type))
        .then_some(ExpectedObjectSuggestionKind::Type);
        let Some(kind) = forced_type_kind.or_else(|| {
            Self::expected_object_suggestion_kind_for_db(
                prefix,
                Some(qualifier),
                deep_ctx,
                db_type,
            )
        }) else {
            return suggestions;
        };

        if matches!(kind, ExpectedObjectSuggestionKind::SchemaObject) {
            let Some(expected_kinds) = Self::expected_qualifier_member_kinds_for_db(kind, db_type)
            else {
                return suggestions;
            };
            let mut filtered = Vec::new();
            let mut seen = HashSet::new();
            for suggestion in &suggestions {
                match data.qualifier_member_matches_kinds(
                    member_qualifier,
                    suggestion,
                    expected_kinds,
                ) {
                    Some(false)
                        if data.qualifier_member_has_kind_metadata(member_qualifier, suggestion) =>
                    {
                        continue;
                    }
                    Some(true) | None => {}
                    Some(false) => {}
                }
                if seen.insert(Self::completion_identifier_lookup_upper(suggestion)) {
                    filtered.push(suggestion.clone());
                }
                if filtered.len() >= MAX_MERGED_SUGGESTIONS {
                    break;
                }
            }
            return filtered;
        }

        let mut filtered = Vec::new();
        let mut seen = HashSet::new();
        for suggestion in &suggestions {
            if !Self::suggestion_matches_expected_object_kind_for_qualifier(
                data,
                member_qualifier,
                suggestion,
                kind,
                db_type,
            ) {
                continue;
            }
            if seen.insert(Self::completion_identifier_lookup_upper(suggestion)) {
                filtered.push(suggestion.clone());
            }
            if filtered.len() >= MAX_MERGED_SUGGESTIONS {
                break;
            }
        }
        filtered
    }

    fn qualified_member_has_known_schema_object_kind(
        data: &IntellisenseData,
        qualifier: &str,
        candidate: &str,
    ) -> bool {
        const KNOWN_SCHEMA_OBJECT_KINDS: &[QualifiedMemberKind] = &[
            QualifiedMemberKind::Table,
            QualifiedMemberKind::View,
            QualifiedMemberKind::MaterializedView,
            QualifiedMemberKind::Type,
            QualifiedMemberKind::Trigger,
            QualifiedMemberKind::Event,
            QualifiedMemberKind::Index,
            QualifiedMemberKind::Procedure,
            QualifiedMemberKind::Function,
            QualifiedMemberKind::Package,
            QualifiedMemberKind::Sequence,
            QualifiedMemberKind::Synonym,
            QualifiedMemberKind::PublicSynonym,
            QualifiedMemberKind::DatabaseLink,
            QualifiedMemberKind::Directory,
            QualifiedMemberKind::Library,
            QualifiedMemberKind::Cluster,
            QualifiedMemberKind::Context,
            QualifiedMemberKind::Dimension,
            QualifiedMemberKind::Operator,
            QualifiedMemberKind::Indextype,
            QualifiedMemberKind::Edition,
            QualifiedMemberKind::JavaSource,
            QualifiedMemberKind::JavaClass,
            QualifiedMemberKind::JavaResource,
            QualifiedMemberKind::User,
        ];

        data.qualifier_member_matches_kinds(qualifier, candidate, KNOWN_SCHEMA_OBJECT_KINDS)
            .unwrap_or(false)
    }

    #[cfg(test)]
    fn expected_relation_member_suggestions_for_qualifier(
        data: &mut IntellisenseData,
        qualifier: &str,
        prefix: &str,
        deep_ctx: &intellisense_context::CursorContext,
    ) -> Vec<String> {
        Self::expected_relation_member_suggestions_for_qualifier_for_db(
            data, qualifier, prefix, deep_ctx, None,
        )
    }

    fn expected_relation_member_suggestions_for_qualifier_for_db(
        data: &mut IntellisenseData,
        qualifier: &str,
        prefix: &str,
        deep_ctx: &intellisense_context::CursorContext,
        db_type: Option<crate::db::DatabaseType>,
    ) -> Vec<String> {
        let relation_suggestions = data.get_member_suggestions(qualifier, prefix, true);
        let suggestions = Self::merge_suggestions_with_context_aliases(
            data.get_member_suggestions(qualifier, prefix, false),
            relation_suggestions,
            false,
        );
        let kind = Self::expected_object_suggestion_kind_for_db(
            prefix,
            Some(qualifier),
            deep_ctx,
            db_type,
        )
        .or_else(|| {
            let context =
                Self::classify_intellisense_context(deep_ctx, deep_ctx.statement_tokens.as_ref());
            matches!(context, SqlContext::TableName)
                .then_some(ExpectedObjectSuggestionKind::RelationOrSequence)
        });
        let Some(kind) = kind else { return suggestions };
        if matches!(kind, ExpectedObjectSuggestionKind::SchemaObject) {
            if suggestions.is_empty() {
                return suggestions;
            }
            let Some(expected_kinds) = Self::expected_qualifier_member_kinds_for_db(kind, db_type)
            else {
                return suggestions;
            };
            let mut filtered = Vec::new();
            let mut saw_kind_metadata = false;
            let mut seen = HashSet::new();
            for suggestion in &suggestions {
                match data.qualifier_member_matches_kinds(qualifier, suggestion, expected_kinds) {
                    Some(true) => {
                        saw_kind_metadata = true;
                        if seen.insert(Self::completion_identifier_lookup_upper(suggestion)) {
                            filtered.push(suggestion.clone());
                        }
                    }
                    Some(false)
                        if data.qualifier_member_has_kind_metadata(qualifier, suggestion) =>
                    {
                        saw_kind_metadata = true;
                    }
                    Some(false) => {
                        if seen.insert(Self::completion_identifier_lookup_upper(suggestion)) {
                            filtered.push(suggestion.clone());
                        }
                    }
                    None => {
                        if seen.insert(Self::completion_identifier_lookup_upper(suggestion)) {
                            filtered.push(suggestion.clone());
                        }
                    }
                }
                if filtered.len() >= MAX_MERGED_SUGGESTIONS {
                    break;
                }
            }
            return if saw_kind_metadata {
                filtered
            } else {
                suggestions
            };
        }
        let Some(expected_kinds) = Self::expected_qualifier_member_kinds_for_db(kind, db_type)
        else {
            return suggestions;
        };

        let mut filtered = Vec::new();
        let mut seen = HashSet::new();
        for suggestion in &suggestions {
            let matches = if data.qualifier_member_has_kind_metadata(qualifier, suggestion) {
                data.qualifier_member_matches_kinds(qualifier, suggestion, expected_kinds)
                    == Some(true)
            } else {
                Self::expected_object_kind_allows_relation_member_cache(kind)
                    && data.qualifier_relation_member_matches(qualifier, suggestion)
            };
            if matches && seen.insert(Self::completion_identifier_lookup_upper(suggestion)) {
                filtered.push(suggestion.clone());
            }
            if filtered.len() >= MAX_MERGED_SUGGESTIONS {
                break;
            }
        }
        filtered
    }

